def procesar_nodo(nodo, datos, referencia_historica=None):
    """Calcula el índice sólo sobre una respuesta cuya identidad y cobertura estén verificadas."""
    try:
        referencia = _referencia_meteorologica(referencia_historica)
        limpio, horas, metadatos = _validar_respuesta_meteorologica(nodo, datos, referencia)
    except (TypeError, ValueError) as error:
        salida = resultado_sin_datos(nodo, str(error))
        salida.update(consulta_meteorologica=None, referencia_datos=None, celda_lat=np.nan,
                      celda_lon=np.nan, distancia_celda_km=np.nan, capas_humedad_vigentes=0,
                      fecha_humedad_suelo=None, antiguedad_humedad_horas=np.nan,
                      cobertura_meteorologica=False, indice_parcial=np.nan)
        return salida
    salida = _procesar_nodo_motor_experimental(nodo, limpio, referencia)
    salida.update(metadatos)
    cobertura = {}
    for variable, prefijo in (('precipitation', 'lluvia'), ('rain', 'rain'),
                             ('showers', 'showers'), ('runoff', 'runoff')):
        for etiqueta, cantidad in (('24', 24), ('72', 72), ('7d', 168)):
            for futura in (False, True):
                if futura and variable in ('rain', 'showers'):
                    continue
                infijo = ('_futura_' if variable == 'precipitation' else '_futuro_') if futura else '_'
                campo = prefijo + infijo + etiqueta
                valor, recibidas = _suma_ventana_meteorologica(
                    horas, limpio['hourly'].get(variable), referencia, cantidad, futura)
                salida[campo] = round(valor, 2 if variable == 'runoff' else 1) if np.isfinite(valor) else np.nan
                cobertura[campo] = {'horas_validas': recibidas, 'horas_requeridas': cantidad,
                                    'completa': bool(np.isfinite(valor))}
    valor_et0, _ = _suma_ventana_meteorologica(
        horas, limpio['hourly'].get('et0_fao_evapotranspiration'), referencia, 24, True)
    salida['et0_24'] = round(valor_et0, 2) if np.isfinite(valor_et0) else np.nan
    faltantes = [campo for campo in ('lluvia_7d', 'lluvia_futura_72', 'runoff_72')
                 if not cobertura[campo]['completa']]
    if metadatos['capas_humedad_vigentes'] < 3:
        faltantes.append('humedad de al menos tres capas con antigüedad máxima de tres horas')
    completa = not faltantes
    salida['cobertura_ventanas'] = cobertura
    salida['cobertura_meteorologica'] = completa
    salida['estado_datos'] = 'OK' if completa else 'INCOMPLETO'
    salida['error_datos'] = '' if completa else 'Índice no disponible: falta cobertura completa de ' + ', '.join(faltantes)
    if not completa:
        salida['indice'] = np.nan
        salida['nivel'] = 'SIN DATOS'
        salida['accion'] = accion_desde_nivel('SIN DATOS')
    # Las variables instantáneas opcionales tampoco reutilizan indefinidamente un valor antiguo.
    for variable, campo in (('temperature_2m', 'temperatura'), ('apparent_temperature', 'sensacion'),
                            ('dew_point_2m', 'punto_rocio'), ('relative_humidity_2m', 'humedad_relativa'),
                            ('pressure_msl', 'presion_msl'), ('surface_pressure', 'presion_superficie'),
                            ('cloud_cover', 'nubosidad'), ('cloud_cover_low', 'nubosidad_baja'),
                            ('cloud_cover_mid', 'nubosidad_media'), ('cloud_cover_high', 'nubosidad_alta'),
                            ('wind_speed_10m', 'viento'), ('wind_gusts_10m', 'rafaga'),
                            ('wind_direction_10m', 'direccion_viento'), ('weather_code', 'codigo_tiempo'),
                            ('cape', 'cape'), ('vapour_pressure_deficit', 'vpd'),
                            ('evapotranspiration', 'evapotranspiracion'), ('et0_fao_evapotranspiration', 'et0')):
        valores = limpio['hourly'].get(variable, [])
        if not isinstance(valores, (list, tuple, np.ndarray)) or len(valores) != len(horas):
            salida[campo] = np.nan
            continue
        try:
            posiciones = np.where((horas <= referencia) & np.isfinite(np.asarray(valores, dtype=float)))[0]
        except (TypeError, ValueError):
            posiciones = []
        if not len(posiciones) or referencia - horas[posiciones[-1]] > pd.Timedelta(hours=3):
            salida[campo] = np.nan
    if not np.isfinite(salida.get('direccion_viento', np.nan)):
        salida['direccion_viento_texto'] = 'Sin dato'
    if not np.isfinite(salida.get('codigo_tiempo', np.nan)):
        salida['descripcion_tiempo'] = 'Sin dato'
    return salida




def obtener_todos_los_nodos():

    datos_lista = obtener_datos_ecmwf()
    resultados = []

    if len(datos_lista) != len(NODOS):

        datos_lista = list(
            datos_lista
        )

        while len(datos_lista) < len(NODOS):
            datos_lista.append(
                {
                    "error":
                    "Respuesta incompleta de Open-Meteo"
                }
            )

        datos_lista = datos_lista[
            :len(NODOS)
        ]

    for nodo, datos in zip(
        NODOS,
        datos_lista,
    ):
        resultados.append(
            procesar_nodo(
                nodo,
                datos,
            )
        )

    return pd.DataFrame(
        resultados
    )


def guardar_historial(df):

    if df.empty:
        return

    columnas = [
        "actualizado",
        "localidad",
        "provincia",
        "partido",
        "indice",
        "nivel",
        "nivel_meteorologico",
        "cobertura_territorial",
        "motivos_semaforo",
        "temperatura",
        "humedad_relativa",
        "presion_msl",
        "viento",
        "rafaga",
        "cape",
        "humedad_suelo_promedio",
        "humedad_0_7",
        "humedad_7_28",
        "humedad_28_100",
        "humedad_100_255",
        "lluvia_24",
        "lluvia_72",
        "lluvia_7d",
        "lluvia_futura_24",
        "lluvia_futura_72",
        "lluvia_futura_7d",
        "rain_24",
        "rain_72",
        "rain_7d",
        "showers_24",
        "showers_72",
        "showers_7d",
        "runoff_24",
        "runoff_72",
        "runoff_7d",
        "prob_lluvia",
        "prob_lluvia_24",
        "prob_lluvia_72",
        "tendencia",
    ]

    columnas_validas = [
        columna
        for columna in columnas
        if columna in df.columns
    ]

    nuevo = df[
        columnas_validas
    ].copy()

    try:

        if HISTORY_FILE.exists():

            anterior = pd.read_csv(
                HISTORY_FILE
            )

            combinado = pd.concat(
                [
                    anterior,
                    nuevo,
                ],
                ignore_index=True,
            )

        else:
            combinado = nuevo

        if len(combinado) > 50000:
            combinado = combinado.tail(
                50000
            ).copy()

        combinado.to_csv(
            HISTORY_FILE,
            index=False,
        )

    except Exception:
        pass


def obtener_secrets_telegram():

    try:

        token = str(
            st.secrets.get(
                "TELEGRAM_BOT_TOKEN",
                "",
            )
        ).strip()

        chat_id = str(
            st.secrets.get(
                "TELEGRAM_CHAT_ID",
                "",
            )
        ).strip()

        return token, chat_id

    except Exception:
        return "", ""


def _numero_telegram(valor):
    try:
        numero = float(valor)
        return round(numero, 2) if np.isfinite(numero) else None
    except (TypeError, ValueError):
        return None


def _destino_estado_telegram(token, chat_id):
    # Separa bots y canales sin almacenar credenciales en el registro.
    return hashlib.sha256((token + '\0' + chat_id.lower()).encode('utf-8')).hexdigest()


def _conexion_estado_telegram():
    conexion = sqlite3.connect(str(TELEGRAM_DB_FILE), timeout=10)
    conexion.row_factory = sqlite3.Row
    conexion.execute('PRAGMA busy_timeout=10000')
    conexion.execute('''CREATE TABLE IF NOT EXISTS telegram_estado (
        destino TEXT NOT NULL, nodo TEXT NOT NULL, estado TEXT NOT NULL,
        PRIMARY KEY (destino, nodo))''')
    conexion.execute('''CREATE TABLE IF NOT EXISTS telegram_envios (
        id TEXT PRIMARY KEY, destino TEXT NOT NULL, nodo TEXT NOT NULL,
        localidad TEXT NOT NULL, provincia TEXT NOT NULL, tipo TEXT NOT NULL,
        motivo TEXT NOT NULL, creado TEXT NOT NULL, intento TEXT NOT NULL,
        indice REAL, indice_anterior REAL, mensaje TEXT NOT NULL,
        estado TEXT NOT NULL, message_id INTEGER, detalle TEXT,
        intentos INTEGER NOT NULL DEFAULT 1)''')
    conexion.commit()
    return conexion


def _guardar_nodo_telegram(conexion, destino, nodo, estado):
    conexion.execute(
        'INSERT INTO telegram_estado(destino,nodo,estado) VALUES (?,?,?) '
        'ON CONFLICT(destino,nodo) DO UPDATE SET estado=excluded.estado',
        (destino, nodo, json.dumps(estado, ensure_ascii=False, allow_nan=False)),
    )


def _fecha_calculo_telegram(row):
    # "actualizado" es hora de cálculo de la app, no emisión del modelo.
    try:
        return datetime.strptime(str(row.get('actualizado', '')), '%d/%m/%Y %H:%M').replace(tzinfo=TZ).astimezone(timezone.utc)
    except (TypeError, ValueError):
        return None


def _fecha_registro_telegram(valor):
    try:
        fecha = datetime.fromisoformat(str(valor))
        return fecha.astimezone(timezone.utc) if fecha.tzinfo else None
    except (TypeError, ValueError):
        return None


def _sesion_telegram_personalizada():
    # Las capas y umbrales privados cambian el panel de una sesión, no el canal.
    claves = ('ficha_umbral_local', 'ficha_umbral_amarillo', 'ficha_cal_protocolo',
              'ficha_indices', 'ficha_satelites', 'ficha_suelo', 'ficha_suelo_raster',
              'ficha_dem_por_localidad', 'ficha_relieve', 'ficha_ina_resultado')
    for clave in claves:
        valor = st.session_state.get(clave)
        if isinstance(valor, pd.DataFrame):
            if not valor.empty:
                return True
        elif isinstance(valor, (dict, list, tuple)):
            if len(valor):
                return True
        elif valor is not None:
            return True
    return False


def historial_envios_telegram(limite=30):
    token, chat_id = obtener_secrets_telegram()
    if not token or not chat_id:
        return pd.DataFrame()
    conexion = None
    try:
        conexion = _conexion_estado_telegram()
        registros = conexion.execute(
            'SELECT id,creado,intento,localidad,provincia,tipo,motivo,indice_anterior,'
            'indice,estado,message_id,detalle,intentos FROM telegram_envios '
            'WHERE destino=? ORDER BY creado DESC LIMIT ?',
            (_destino_estado_telegram(token, chat_id), int(limite)),
        ).fetchall()
        return pd.DataFrame([dict(r) for r in registros])
    except (sqlite3.Error, OSError, ValueError):
        return pd.DataFrame()
    finally:
        if conexion is not None:
            conexion.close()


def enviar_telegram_detallado(mensaje):
    """Valida la respuesta de Bot API sin exportar credenciales ni el chat."""
    token, chat_id = obtener_secrets_telegram()
    resultado = {'fecha': ahora().isoformat(), 'ok': False, 'http': None,
                 'message_id': None, 'incierto': False, 'detalle': 'Credenciales no configuradas'}
    if not token or not chat_id:
        return resultado
    def detalle_seguro(valor):
        texto = str(valor)
        for secreto in (str(token), str(chat_id)):
            if secreto:
                texto = texto.replace(secreto, '[oculto]')
        return texto[:300]
    try:
        response = requests.post(
            f'https://api.telegram.org/bot{token}/sendMessage',
            json={'chat_id': chat_id, 'text': mensaje, 'parse_mode': 'HTML',
                  'disable_web_page_preview': True},
            timeout=15,
        )
        resultado['http'] = response.status_code
        datos = response.json()
        if not isinstance(datos, dict):
            raise ValueError('Bot API no devolvió un objeto JSON')
        enviado = datos.get('result') or {}
        message_id = enviado.get('message_id') if isinstance(enviado, dict) else None
        resultado['ok'] = bool(200 <= response.status_code < 300 and datos.get('ok') is True
                               and isinstance(message_id, int) and message_id > 0)
        if resultado['ok']:
            resultado.update(message_id=message_id, detalle='Bot API confirmó el envío; recepción en el chat pendiente de comprobar')
        else:
            resultado['incierto'] = datos.get('ok') is not False
            resultado['detalle'] = detalle_seguro(datos.get('description', 'Respuesta sin confirmación válida de envío'))
    except requests.exceptions.RequestException:
        resultado['incierto'] = True
        resultado['detalle'] = 'Fallo de conexión o tiempo de espera; envío no confirmado'
    except (ValueError, TypeError):
        resultado['incierto'] = True
        resultado['detalle'] = 'Respuesta de Bot API inválida; envío no confirmado'
    return resultado


def enviar_telegram(mensaje):
    return enviar_telegram_detallado(mensaje)['ok']


def generar_mensaje_alerta(row):

    emoji = emoji_nivel(
        row["nivel"]
    )

    prob = row.get(
        "prob_lluvia",
        np.nan,
    )

    prob_texto = (
        f"{prob:.0f}%"
        if pd.notna(prob)
        else "Sin dato"
    )

    # La humedad se convierte de m³/m³ a %
    # únicamente para presentación.
    humedad_suelo_pct = (
        row["humedad_suelo_promedio"] * 100
        if pd.notna(
            row["humedad_suelo_promedio"]
        )
        else np.nan
    )

    humedad_suelo_texto = (
        f"{humedad_suelo_pct:.1f}%"
        if np.isfinite(humedad_suelo_pct)
        else "Sin dato"
    )

    return f"""
{emoji} <b>ALERTA ZÁRATE–CAMPANA</b>

<b>Semáforo:</b> {row["nivel"]}
<b>Datos meteorológicos completos:</b> {"Sí" if row.get("estado_datos") == "OK" else "No"}
<b>Evidencia:</b> {html.escape(str(row.get("motivos_semaforo", "Índice meteorológico")))}
<b>Localidad:</b> {html.escape(str(row["localidad"]))}
<b>Partido:</b> {html.escape(str(row.get("partido", "")))}
<b>Provincia:</b> {html.escape(str(row["provincia"]))}

<b>Índice meteorológico experimental:</b> {row["indice"]:.1f}/100

<b>Condiciones actuales:</b>
Temperatura: {row["temperatura"]:.1f} °C
Humedad relativa: {row["humedad_relativa"]:.0f}%
Viento: {row["viento"]:.1f} km/h ({row["direccion_viento_texto"]})
Ráfaga: {row["rafaga"]:.1f} km/h
CAPE: {row["cape"]:.0f} J/kg

<b>Humedad del suelo media:</b>
{humedad_suelo_texto}

<b>Precipitación antecedente:</b>
24 h: {row["lluvia_24"]:.1f} mm
72 h: {row["lluvia_72"]:.1f} mm
7 días: {row["lluvia_7d"]:.1f} mm

<b>Pronóstico:</b>
24 h: {row["lluvia_futura_24"]:.1f} mm
72 h: {row["lluvia_futura_72"]:.1f} mm
7 días: {row["lluvia_futura_7d"]:.1f} mm

<b>Runoff antecedente 72 h:</b>
{row["runoff_72"]:.2f} mm

<b>Probabilidad máxima de precipitación en 72 h:</b>
{prob_texto}

<b>Tendencia del runoff modelado:</b>
{row["tendencia"]}

<b>Acción recomendada:</b>
{acciones_telegram_html(row)}

<i>Cálculo meteorológico: {row["actualizado"]} ART (no es la hora de emisión del modelo)</i>

⚠️ Sistema experimental.
No reemplaza avisos oficiales.
""".strip()


def clave_alerta(row):
    """Firma de valores; fechas de apertura y textos explicativos no son cambios."""
    campos = ('indice', 'humedad_suelo_promedio', 'lluvia_24', 'lluvia_72', 'lluvia_7d',
              'lluvia_futura_24', 'lluvia_futura_72', 'lluvia_futura_7d', 'runoff_72')
    contenido = {'provincia': str(row.get('provincia', '')), 'localidad': str(row.get('localidad', '')),
                 'nivel': str(row.get('nivel', '')), **{c: _numero_telegram(row.get(c)) for c in campos}}
    return hashlib.sha256(json.dumps(contenido, sort_keys=True, allow_nan=False).encode('utf-8')).hexdigest()


def _mensaje_evento_telegram(row, evento):
    anterior = evento.get('indice_anterior')
    anterior_texto = f'{anterior:.1f}/100' if anterior is not None else 'Sin índice previo'
    cabecera = (
        f"<b>{html.escape(evento['tipo'])}</b>\n"
        f"<b>ID del evento:</b> {evento['id']}\n"
        f"<b>Motivo del envío:</b> {html.escape(evento['motivo'])}\n"
        f"<b>Índice de referencia anterior:</b> {anterior_texto}\n"
        f"<b>Evaluación que generó el evento:</b> {ahora().strftime('%d/%m/%Y %H:%M')} ART\n\n"
    )
    return cabecera + generar_mensaje_alerta(row)


def procesar_alertas_telegram(df, guardar_registro=None):
    """Registro compartido y reserva previa: recargar no es un evento meteorológico."""
    token, chat_id = obtener_secrets_telegram()
    resultado = {'configurado': bool(token and chat_id), 'enviadas': 0, 'fallidas': 0,
                 'pendientes': int(df.nivel.eq('ROJO').sum()) if 'nivel' in df else 0,
                 'omitidas': 0, 'inicializadas': 0, 'sin_datos': 0, 'atrasadas': 0,
                 'inciertas': 0, 'pausado_sesion': False, 'registro_error': ''}
    if not token or not chat_id or df.empty:
        return resultado
    if _sesion_telegram_personalizada():
        resultado['pausado_sesion'] = True
        return resultado
    destino = _destino_estado_telegram(token, chat_id)
    momento = ahora().astimezone(timezone.utc)
    conexion = None
    try:
        conexion = _conexion_estado_telegram()
        for _, row in df.iterrows():
            nivel = str(row.get('nivel', 'SIN DATOS'))
            fecha_calculo = _fecha_calculo_telegram(row)
            if (nivel not in ('VERDE', 'AMARILLO', 'ROJO') or fecha_calculo is None
                    or momento - fecha_calculo > timedelta(hours=12)
                    or fecha_calculo - momento > timedelta(minutes=5)):
                resultado['sin_datos'] += 1
                continue
            nodo = json.dumps([str(row['provincia']), str(row['localidad'])], ensure_ascii=False)
            indice = _numero_telegram(row.get('indice'))
            firma = clave_alerta(row)
            fecha_iso = fecha_calculo.isoformat()
            evento = None
            conexion.execute('BEGIN IMMEDIATE')
            previo = conexion.execute('SELECT estado FROM telegram_estado WHERE destino=? AND nodo=?', (destino, nodo)).fetchone()
            if previo is None:
                estado = {'nivel': nivel, 'indice': indice, 'fecha_calculo': fecha_iso,
                          'firma': firma, 'referencia_indice': indice, 'referencia_fecha': momento.isoformat(),
                          'episodio': 1 if nivel == 'ROJO' else 0, 'pendiente_id': None, 'descenso_desde': None}
                _guardar_nodo_telegram(conexion, destino, nodo, estado)
                conexion.commit()
                resultado['inicializadas'] += 1
                continue
            estado = json.loads(previo['estado'])
            fecha_previa = _fecha_registro_telegram(estado.get('fecha_calculo'))
            if fecha_previa is not None and fecha_calculo < fecha_previa:
                conexion.commit()
                resultado['atrasadas'] += 1
                continue
            anterior_nivel = estado.get('nivel')
            if nivel != 'ROJO':
                # Un gris nunca cierra un episodio. Una bajada válida debe durar 15 min.
                if anterior_nivel == 'ROJO':
                    descenso = _fecha_registro_telegram(estado.get('descenso_desde'))
                    if descenso is None:
                        estado['descenso_desde'] = fecha_iso
                    elif fecha_calculo - descenso >= timedelta(minutes=15):
                        estado.update(nivel=nivel, pendiente_id=None, descenso_desde=None,
                                      referencia_indice=indice, referencia_fecha=momento.isoformat())
                else:
                    estado.update(nivel=nivel, referencia_indice=indice, referencia_fecha=momento.isoformat())
                estado.update(indice=indice, fecha_calculo=fecha_iso, firma=firma)
                _guardar_nodo_telegram(conexion, destino, nodo, estado)
                conexion.commit()
                continue
            estado['descenso_desde'] = None
            pendiente_id = estado.get('pendiente_id')
            if pendiente_id:
                reservado = conexion.execute('SELECT * FROM telegram_envios WHERE id=?', (pendiente_id,)).fetchone()
                intento_previo = _fecha_registro_telegram(reservado['intento']) if reservado else None
                if (reservado and reservado['estado'] == 'rechazado' and intento_previo
                        and momento - intento_previo >= timedelta(minutes=15)):
                    evento = dict(reservado)
                    evento['indice'] = indice
                    evento['motivo'] = 'Reintento de un aviso rechazado por Telegram; la evaluación actual sigue en ROJO.'
                    evento['mensaje'] = _mensaje_evento_telegram(row, evento)
                    conexion.execute("UPDATE telegram_envios SET estado='reservado',intento=?,indice=?,motivo=?,mensaje=?,intentos=intentos+1 WHERE id=?", (momento.isoformat(), indice, evento['motivo'], evento['mensaje'], pendiente_id))
                else:
                    indice_pendiente = _numero_telegram(reservado['indice']) if reservado else None
                    cambio_pendiente = indice - indice_pendiente if indice is not None and indice_pendiente is not None else None
                    nuevo_cambio = (reservado and reservado['estado'] in ('reservado', 'incierto')
                                   and cambio_pendiente is not None
                                   and (cambio_pendiente >= 20 or (abs(cambio_pendiente) >= 10
                                        and intento_previo and momento - intento_previo >= timedelta(hours=3))))
                    if nuevo_cambio:
                        evento = {'tipo': 'ACTUALIZACIÓN DE ALERTA',
                                  'motivo': f'Nuevo cambio del índice de {cambio_pendiente:+.1f} puntos; el aviso anterior quedó sin confirmación. Este es un evento distinto.',
                                  'indice_anterior': indice_pendiente, 'indice': indice}
                    else:
                        resultado['omitidas'] += 1
                        if reservado and reservado['estado'] in ('reservado', 'incierto'):
                            resultado['inciertas'] += 1
                        estado.update(indice=indice, fecha_calculo=fecha_iso, firma=firma)
                        _guardar_nodo_telegram(conexion, destino, nodo, estado)
                        conexion.commit()
                        continue
            elif anterior_nivel != 'ROJO':
                estado['episodio'] = int(estado.get('episodio', 0)) + 1
                evento = {'tipo': 'ALERTA NUEVA', 'motivo': f'Paso de {anterior_nivel} a ROJO en la localidad.',
                          'indice_anterior': estado.get('indice'), 'indice': indice}
            else:
                referencia = _numero_telegram(estado.get('referencia_indice'))
                referencia_fecha = _fecha_registro_telegram(estado.get('referencia_fecha'))
                if referencia is None and indice is not None:
                    estado.update(referencia_indice=indice, referencia_fecha=momento.isoformat())
                    referencia = indice
                    referencia_fecha = momento
                diferencia = indice - referencia if indice is not None and referencia is not None else None
                cambio = diferencia is not None and abs(diferencia) >= 10
                intervalo = referencia_fecha is not None and momento - referencia_fecha >= timedelta(hours=3)
                aumento_rapido = diferencia is not None and diferencia >= 20
                if cambio and (intervalo or aumento_rapido):
                    direccion = 'subió' if diferencia > 0 else 'bajó'
                    evento = {'tipo': 'ACTUALIZACIÓN DE ALERTA',
                              'motivo': f'Permanece ROJO; el índice {direccion} {abs(diferencia):.1f} puntos respecto de la referencia registrada.'
                                        + (' Aumento de al menos 20 puntos: aviso sin esperar tres horas.' if aumento_rapido else ''),
                              'indice_anterior': referencia, 'indice': indice}
                else:
                    resultado['omitidas'] += 1
            estado.update(nivel='ROJO', indice=indice, fecha_calculo=fecha_iso, firma=firma)
            if evento is None:
                _guardar_nodo_telegram(conexion, destino, nodo, estado)
                conexion.commit()
                continue
            if 'id' not in evento:
                evento['id'] = uuid.uuid4().hex[:12]
                evento['mensaje'] = _mensaje_evento_telegram(row, evento)
                conexion.execute(
                    'INSERT INTO telegram_envios(id,destino,nodo,localidad,provincia,tipo,motivo,creado,intento,'
                    'indice,indice_anterior,mensaje,estado) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',
                    (evento['id'], destino, nodo, str(row['localidad']), str(row['provincia']), evento['tipo'],
                     evento['motivo'], momento.isoformat(), momento.isoformat(), evento['indice'],
                     evento['indice_anterior'], evento['mensaje'], 'reservado'),
                )
            estado['pendiente_id'] = evento['id']
            _guardar_nodo_telegram(conexion, destino, nodo, estado)
            # La reserva queda persistida ANTES de llamar a Telegram, incluso si se interrumpe el proceso.
            conexion.commit()
            if guardar_registro is not None:
                # El monitor conserva también la reserva fuera del servidor temporal.
                # Si falla esta escritura, no se llama a Telegram.
                guardar_registro()
            try:
                envio = enviar_telegram_detallado(evento['mensaje'])
            except Exception:
                envio = {'ok': False, 'incierto': True, 'message_id': None,
                         'detalle': 'Envío interrumpido; confirmación pendiente de revisar en el canal.'}
            estado_envio = 'enviado' if envio['ok'] else 'incierto' if envio.get('incierto') else 'rechazado'
            conexion.execute('BEGIN IMMEDIATE')
            conexion.execute('UPDATE telegram_envios SET estado=?,message_id=?,detalle=? WHERE id=?',
                             (estado_envio, envio.get('message_id'), envio.get('detalle', ''), evento['id']))
            ultimo = conexion.execute('SELECT estado FROM telegram_estado WHERE destino=? AND nodo=?', (destino, nodo)).fetchone()
            if envio['ok'] and ultimo:
                estado_actual = json.loads(ultimo['estado'])
                if estado_actual.get('pendiente_id') == evento['id']:
                    estado_actual.update(pendiente_id=None, referencia_indice=evento['indice'],
                                         referencia_fecha=momento.isoformat())
                    _guardar_nodo_telegram(conexion, destino, nodo, estado_actual)
            conexion.commit()
            if guardar_registro is not None:
                guardar_registro()
            if envio['ok']:
                resultado['enviadas'] += 1
            elif envio.get('incierto'):
                resultado['inciertas'] += 1
            else:
                resultado['fallidas'] += 1
    except (sqlite3.Error, OSError, ValueError, TypeError, KeyError, RuntimeError):
        if conexion is not None:
            conexion.rollback()
        resultado['registro_error'] = 'No se pudo completar el registro compartido. Los envíos sin registro se bloquean para evitar repeticiones.'
    finally:
        if conexion is not None:
            conexion.close()
    return resultado


def crear_mapa(df):
    from portada_zc import hover_meteorologico_zc
    df=df.copy()
    # Un índice ausente conserva un punto visible; su tamaño no expresa riesgo.
    df['_tamano_mapa']=12.0
    colores = {
        "VERDE": "green",
        "AMARILLO": "yellow",
        "ROJO": "red",
        "SIN DATOS": "#64748b",
    }

    referencia=ahora()
    df['_detalle_publico']=df.apply(lambda r:hover_meteorologico_zc(r,referencia),axis=1)

    fig = px.scatter_map(
        df,
        lat="lat",
        lon="lon",
        color="nivel",
        size="_tamano_mapa",
        size_max=14,
        custom_data=['_detalle_publico'],
        labels={'nivel':'Índice meteorológico'},
        color_discrete_map=colores,
        center={
            "lat": MAP_CENTER_LAT,
            "lon": MAP_CENTER_LON,
        },
        zoom=MAP_ZOOM,
        height=680,
    )

    fig.update_traces(hovertemplate='%{customdata[0]}<extra></extra>')
    fig.update_layout(
        map_style="open-street-map",
        margin={
            "r": 0,
            "t": 0,
            "l": 0,
            "b": 0,
        },
        legend={
            "title": "Semáforo meteorológico"
        },
        uirevision=firma_cobertura(),
    )
    for provincia,geometria in GEOMETRIAS_LITORAL.items():
        for poligono in _anillos_provincia(geometria):
            exterior=poligono[0]
            fig.add_trace(go.Scattermap(lon=[p[0] for p in exterior],lat=[p[1] for p in exterior],
                mode='lines',line={'color':'#475569','width':1},name=provincia,
                showlegend=False,hoverinfo='skip'))
    return fig


