RECOMENDACIONES_NIVELES = {}  # Defined with local actions below



ACCIONES_FICHA = {nivel: plan['resumen'] for nivel,plan in RECOMENDACIONES_NIVELES.items()}


def recomendaciones_para_alerta(row):
    """Orientaciones por semáforo meteorológico; no recalcula umbrales ni habilita recursos."""
    nivel=str(row.get('nivel','SIN DATOS')).strip().upper()
    nivel={'BAJO':'VERDE','MEDIO':'AMARILLO','ALTO':'ROJO','MUY ALTO':'ROJO'}.get(nivel,nivel)
    if nivel not in RECOMENDACIONES_NIVELES:
        nivel='SIN DATOS'
    incompleta=str(row.get('estado_datos','SIN DATOS'))!='OK'
    cobertura=row.get('cobertura_meteorologica',True)
    if cobertura is None or pd.isna(cobertura) or not bool(cobertura):
        incompleta=True
    try:
        incompleta |= not np.isfinite(float(row.get('indice',np.nan)))
    except (ValueError,TypeError):
        incompleta=True
    fecha=row.get('actualizado')
    if isinstance(fecha,str) and fecha.strip():
        try:
            incompleta |= not dato_vigente(datetime.strptime(fecha,'%d/%m/%Y %H:%M'),12)
        except (ValueError,TypeError):
            incompleta=True
    else:
        incompleta=True
    # La orientación meteorológica se complementa con la evaluación fluvial y local.
    if nivel=='VERDE' and incompleta:
        nivel='SIN DATOS'
    plan=json.loads(json.dumps(RECOMENDACIONES_NIVELES[nivel],ensure_ascii=False))
    plan['nivel']=nivel
    plan['contexto']='Contrastá este plan con la crecida, la sudestada y los partes locales. ' + ('La meteorología está incompleta o antigua; verificá sus fechas.' if incompleta else 'El semáforo meteorológico es una de las fuentes para preparar medidas.')
    modelo=st.session_state.get('zc_modelo_predictivo_resultado',{})
    senales=[a for a in modelo.get('alertas',[]) if a.get('localidad')==row.get('localidad') or
             (a.get('partido')==row.get('partido') and a.get('mecanismo')=='Tendencia del pronóstico fluvial')]
    if senales:
        prioritaria=max(senales,key=lambda a:a.get('prioridad',0))
        plan['contexto']='Modelo predictivo: '+prioritaria['nivel']+'. Revisá su período, evidencia y acción en el panel superior. '+plan['contexto']
    plan['fuentes']=json.loads(json.dumps(FUENTES_PREVENCION,ensure_ascii=False))
    return plan


