def localidad_prioritaria(df):
    if df.empty:
        return None
    prioridad={'ROJO':3,'AMARILLO':2,'VERDE':1,'SIN DATOS':0}
    orden=df.assign(_prioridad=df.nivel.map(prioridad).fillna(0),
                    _indice=pd.to_numeric(df.indice,errors='coerce').fillna(-1))
    return orden.sort_values(['_prioridad','_indice','localidad'],ascending=[False,False,True]).iloc[0]['localidad']


def umbrales_semaforo():
    # Same experimental reference thresholds; no local adjustment is presented as validated.
    return 35.0, 55.0



def nivel_desde_indice(indice):
    if not np.isfinite(indice):
        return 'SIN DATOS'
    amarillo, rojo = umbrales_semaforo()
    return 'ROJO' if indice >= rojo else 'AMARILLO' if indice >= amarillo else 'VERDE'


def emoji_nivel(nivel):
    return {'VERDE': '🟢', 'AMARILLO': '🟡', 'ROJO': '🔴', 'SIN DATOS': '⚪',
            'BAJO': '🟢', 'MEDIO': '🟡', 'ALTO': '🔴', 'MUY ALTO': '🔴'}.get(nivel, '⚪')


def accion_desde_nivel(nivel):
    return ACCIONES_FICHA.get(nivel, ACCIONES_FICHA['SIN DATOS'])


def fusion_territorial(modelo, agua=None, suelo=None, cota_baja=None, rio=None):
    amarillo, rojo = umbrales_semaforo()
    try:
        indice = float(modelo.get('indice', np.nan))
        valido = bool(np.isfinite(indice) and modelo.get('cobertura_meteorologica', True)
                      and modelo.get('estado_datos') == 'OK')
        valido &= dato_vigente(datetime.strptime(str(modelo.get('actualizado', '')), '%d/%m/%Y %H:%M'), 12)
    except (ValueError, TypeError):
        valido = False
        indice = np.nan
    nivel = nivel_desde_indice(indice) if valido else 'SIN DATOS'
    motivos = [f'Índice meteorológico {indice:.1f}/100; amarillo ≥ {amarillo:g}, rojo ≥ {rojo:g}'] if valido else ['Meteorología ausente, incompleta o de más de 12 horas']
    motivos.append('Escala experimental sin calibración local; no incluye crecidas, sudestada ni drenaje de cada barrio')
    return {'semaforo':nivel, 'motivos':motivos, 'cobertura':int(valido)}


def componentes_localidad(nodo):
    # Local river station influence, permanent water and soil thresholds are not calibrated.
    return None, None, None, None


def integrar_semaforo(df):
    filas = []
    for _, r in df.iterrows():
        row = r.to_dict()
        nodo = next((n for n in NODOS if n['localidad'] == row['localidad']), row)
        fusion = fusion_territorial(row, *componentes_localidad(nodo))
        row['partido'] = nodo.get('partido', '')
        row['referencia'] = nodo.get('referencia', '')
        row['nivel_meteorologico'] = fusion['semaforo']
        row['nivel'] = fusion['semaforo']
        plan=recomendaciones_para_alerta(row)
        row['accion'] = plan['resumen']
        row['accion_prioritaria'] = plan['ahora'][0]
        row['cobertura_territorial'] = fusion['cobertura']
        row['motivos_semaforo'] = ' | '.join(fusion['motivos'])
        filas.append(row)
    return pd.DataFrame(filas)


def url_publica_evidencia(url, oficial=False):
    from ipaddress import ip_address
    p = urlparse(str(url))
    if p.scheme != 'https' or not p.hostname or p.username or p.password or p.port not in (None, 443):
        raise ValueError('Usá una URL pública HTTPS sin credenciales')
    host = p.hostname.lower()
    if host == 'localhost' or host.endswith(('.local', '.internal')):
        raise ValueError('No se admiten direcciones locales')
    try:
        if not ip_address(host).is_global:
            raise ValueError('No se admiten direcciones privadas')
    except ValueError as exc:
        if 'direcciones privadas' in str(exc):
            raise
    if oficial and not host.endswith(('.gob.ar', '.gov.ar', '.inta.gob.ar')):
        raise ValueError('Esta conexión necesita un dominio oficial argentino .gob.ar o .gov.ar')
    return str(url)


@st.cache_data(ttl=1800, show_spinner=False)
def descargar_registro(url, formato):
    # Registros públicos; nunca se pide un token ni se envía una credencial del usuario.
    url = url_publica_evidencia(url, oficial=True)
    r = requests.get(url, timeout=(4, 15), allow_redirects=False)
    r.raise_for_status()
    if len(r.content) > 5_000_000:
        raise ValueError('Registro mayor a 5 MB')
    if formato == 'CSV':
        from io import StringIO
        return pd.read_csv(StringIO(r.content.decode('utf-8-sig'))).fillna('')
    return r.json()


def extraer_trimestre(texto):
    meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre']
    inicial = normalizar_nombre(texto[:450]).lower()
    hallados = re.findall(r'\b('+'|'.join(meses)+r')\b', inicial)[:3]
    ys = re.findall(r'\b20\d{2}\b', inicial)
    if len(hallados) != 3 or not ys:
        raise ValueError('No se pudo determinar el período del pronóstico')
    year = int(ys[0]); mes = meses.index(hallados[0])+1
    inicio = datetime(year, mes, 1, tzinfo=TZ)
    siguiente = inicio
    for _ in range(3):
        siguiente = (siguiente.replace(day=28)+timedelta(days=4)).replace(day=1)
    return inicio, siguiente-timedelta(seconds=1), '–'.join(hallados)+' '+str(year)


def leer_pdf_trimestral(contenido, url):
    import fitz
    if len(contenido)>12_000_000 or not contenido.startswith(b'%PDF'):
        raise ValueError('No se recibió un PDF SMN válido de hasta 12 MB')
    with fitz.open(stream=contenido, filetype='pdf') as doc:
        if not 1 <= len(doc) <= 35:
            raise ValueError('Documento vacío o demasiado extenso')
        texto = '\n'.join(p.get_text() for p in doc)
        inicio, fin, periodo = extraer_trimestre(texto)
        match = re.search(r'(?:Informe\s+)?elaborado(?:\s+el)?\s+(.{1,80})', texto, re.I)
        emision = _zc_fecha_es(match[1]) if match else None
        # Render all pages: precipitation, temperature and interpretation legends.
        paginas = [p.get_pixmap(matrix=fitz.Matrix(1.0,1.0)).tobytes('png') for p in doc]
        return {'url':url, 'inicio':inicio, 'fin':fin, 'periodo':periodo, 'emision':emision,
                'paginas':paginas, 'pdf':contenido, 'consulta':ahora().isoformat(), 'error':''}


# BEGIN DESCARGAS PUBLICAS ZC 1.5.2
def _zc_respuesta_publica_zc(contenido, url, estado, cabeceras, transporte):
    """Adapta una descarga pública acotada a la interfaz requests.Response."""
    import re
    respuesta = requests.Response()
    respuesta.status_code = estado
    respuesta._content = contenido
    respuesta._content_consumed = True
    respuesta.url = url
    respuesta.headers.update(dict(cabeceras))
    content_type = respuesta.headers.get('Content-Type', '')
    charset = re.search(r'charset\s*=\s*["\']?([^;\s"\']+)', content_type, re.I)
    if charset:
        respuesta.encoding = charset[1]
    else:
        meta = re.search(rb'<meta\b[^>]*charset\s*=\s*["\']?([a-z0-9_\-]+)', contenido[:8192], re.I)
        if meta:
            respuesta.encoding = meta[1].decode('ascii')
    respuesta.transporte_publico = transporte
    return respuesta


def descargar_publico_con_respaldo_zc(url, headers=None, timeout=(3, 8), max_bytes=6 * 1024 * 1024):
    """GET público: respaldo ordinario sólo ante fallos de transporte del primer cliente."""
    from urllib.request import Request, urlopen
    from urllib.error import HTTPError, URLError
    from urllib.parse import urlparse
    from http.client import IncompleteRead
    import ssl
    origen = urlparse(str(url))
    try:
        valido = (origen.scheme == 'https' and origen.hostname and not origen.username and
                  not origen.password and origen.port in {None, 443})
    except ValueError:
        valido = False
    if not valido:
        raise ValueError('La descarga pública requiere una URL HTTPS sin credenciales.')
    if not isinstance(max_bytes, int) or isinstance(max_bytes, bool) or not 1 <= max_bytes <= 6 * 1024 * 1024:
        raise ValueError('El límite de la descarga pública debe ser de hasta 6 MiB.')
    cabeceras = dict(headers or {'User-Agent': 'Alerta-Zarate-Campana/fuentes-publicas'})
    try:
        with requests.get(url, headers=cabeceras, timeout=timeout, stream=True) as r:
            r.raise_for_status()
            partes = []
            total = 0
            for parte in r.iter_content(chunk_size=65536):
                if not parte:
                    continue
                total += len(parte)
                if total > max_bytes:
                    raise ValueError('La descarga pública supera el tamaño admitido.')
                partes.append(parte)
            return _zc_respuesta_publica_zc(b''.join(partes), r.url, r.status_code, r.headers, 'requests')
    except requests.exceptions.SSLError:
        raise
    except (requests.exceptions.ConnectTimeout, requests.exceptions.ReadTimeout, requests.exceptions.ConnectionError):
        # No cambia URL, autorización ni verificación TLS. Las respuestas HTTP
        # denegadas y los certificados inválidos nunca llegan a este respaldo.
        try:
            with urlopen(Request(url, headers=cabeceras), timeout=12) as r:
                contenido = r.read(max_bytes + 1)
                if len(contenido) > max_bytes:
                    raise ValueError('La descarga pública supera el tamaño admitido.')
                return _zc_respuesta_publica_zc(contenido, r.geturl(), r.status, r.headers, 'urllib')
        except HTTPError as exc:
            r = _zc_respuesta_publica_zc(b'', exc.geturl(), exc.code, exc.headers or {}, 'urllib')
            raise requests.exceptions.HTTPError('La fuente pública respondió HTTP ' + str(exc.code), response=r) from exc
        except URLError as exc:
            if isinstance(exc.reason, ssl.SSLError):
                raise requests.exceptions.SSLError('No se pudo verificar TLS de la fuente pública.') from exc
            raise requests.exceptions.ConnectionError('No se completó la descarga pública de respaldo.') from exc
        except ssl.SSLError as exc:
            raise requests.exceptions.SSLError('No se pudo verificar TLS de la fuente pública.') from exc
        except TimeoutError as exc:
            raise requests.exceptions.ReadTimeout('La fuente pública de respaldo no respondió a tiempo.') from exc
        except IncompleteRead as exc:
            raise requests.exceptions.ConnectionError('La fuente pública de respaldo devolvió un contenido incompleto.') from exc

