@st.cache_data(ttl=21600, show_spinner=False)
def obtener_roni():
    try:
        return parsear_roni(descargar_publico(RONI_URL).text), 'Consulta pública NOAA CPC'
    except Exception:
        return pd.DataFrame(), 'No se pudo recuperar una serie RONI utilizable.'


def mostrar_enos_ficha():
    st.subheader('El Niño / La Niña · contexto estacional')
    st.write('El estado del Pacífico tropical ayuda a planificar la vigilancia estacional. No determina una crecida, sudestada o inundación local por sí solo.')
    if st.button('Actualizar fuentes ENOS', key='zc_enos_refresh'):
        obtener_roni.clear()
        obtener_discusion_enos.clear()
    diagnostico = obtener_discusion_enos()
    st.markdown('**Diagnóstico oficial NOAA CPC**')
    if diagnostico.get('error'):
        st.warning('No se pudo confirmar el diagnóstico mensual: '+diagnostico['error'])
    else:
        fecha = diagnostico['emision']
        siguiente = diagnostico.get('siguiente')
        edad = edad_fuente(fecha)
        vigente = np.isfinite(edad) and 0 <= edad <= 45*24 and (siguiente is None or ahora().date() < siguiente.date())
        st.write('Estado publicado: **'+diagnostico['estado']+'**')
        st.caption(f'Emisión: {fecha:%d/%m/%Y} · Consulta: {diagnostico["consulta"]}')
        if not vigente:
            st.warning('Diagnóstico antiguo, futuro o con una actualización ya prevista. Consultá el documento más reciente antes de interpretar el estado actual.')
        if siguiente is not None:
            st.caption(f'Próxima emisión indicada por NOAA: {siguiente:%d/%m/%Y}.')
    a,b,c = st.columns(3)
    a.link_button('Diagnóstico NOAA en español', ENSO_ADVISORY_URL, use_container_width=True)
    b.link_button('Documento oficial PDF', ENSO_ADVISORY_PDF, use_container_width=True)
    c.link_button('Probabilidades oficiales ENOS', ENSO_PROBABILITIES_URL, use_container_width=True)
    st.divider()
    d, origen = obtener_roni()
    if d.empty:
        st.warning(origen)
        st.link_button('Consultar serie RONI en NOAA CPC', RONI_URL)
    else:
        d = d.sort_values(['año','mes_central'])
        ultimo = d.iloc[-1]
        vigencia = vigencia_roni(d)
        st.metric('Último RONI publicado · anomalía relativa Niño 3.4', f'{ultimo.RONI:+.1f} °C')
        st.caption(f'{origen} · trimestre {ultimo.trimestre} {int(ultimo["año"])} · {fase_roni(d)}')
        st.caption(f'Fin del trimestre: {vigencia["fin"]:%d/%m/%Y}. NOAA actualiza esta tabla hasta el día 5 de cada mes; los últimos valores son estimaciones revisables.')
        if vigencia['estado'] in ('atrasado','futuro'):
            st.warning('El último período recibido es antiguo o aún no terminó. Se conserva como contexto documental y no confirma una condición actual.')
        primero=int(d['año'].min())
        ultimo_anio=int(d['año'].max())
        st.markdown('**Serie histórica RONI · intervalo de años**')
        if primero<ultimo_anio:
            desde_anio,hasta_anio=st.slider('Años de la serie histórica',min_value=primero,max_value=ultimo_anio,
                value=(max(primero,ultimo_anio-12),ultimo_anio),step=1,key='zc_roni_intervalo_anios')
        else:
            desde_anio=hasta_anio=primero
            st.caption(f'La fuente recibida contiene un solo año: {primero}.')
        vista=d[d['año'].between(desde_anio,hasta_anio)].copy()
        st.caption(f'Cobertura recibida: {primero}–{ultimo_anio}. Intervalo del gráfico: {desde_anio}–{hasta_anio}. El diagnóstico y el último RONI mostrado corresponden al período más reciente publicado.')
        vista['fecha'] = pd.to_datetime(dict(year=vista['año'], month=vista.mes_central, day=15))
        fig = px.line(vista, x='fecha', y='RONI', hover_data=['trimestre'])
        fig.add_hline(y=.5, line_color='red')
        fig.add_hline(y=-.5, line_color='blue')
        st.plotly_chart(fig, use_container_width=True, key='ficha_roni_chart')
        with st.expander('Tabla RONI del intervalo histórico seleccionado'):
            st.dataframe(vista[['año','trimestre','RONI']],hide_index=True,use_container_width=True)
        st.download_button('Descargar intervalo histórico RONI',vista.to_csv(index=False).encode('utf-8-sig'),
            f'NOAA_RONI_{desde_anio}_{hasta_anio}.csv','text/csv',key='zc_roni_csv_intervalo')
        st.caption('RONI usa medias móviles de tres meses. La secuencia histórica de cinco trimestres y el diagnóstico operativo del sistema acoplado tienen propósitos distintos. RONI y ONI no son intercambiables.')
        st.download_button('Descargar serie RONI', d.to_csv(index=False).encode('utf-8-sig'), 'NOAA_RONI.csv', 'text/csv', key='ficha_roni_csv')
        st.link_button('Fuente de la serie NOAA CPC', RONI_URL)
    st.link_button('Perspectiva climática oficial SMN', 'https://www.smn.gob.ar/pronostico-trimestral', key='zc_enos_smn')
    st.caption('El informe trimestral SMN, sus mapas y sus fechas se consultan en Datos oficiales SMN → Productos oficiales.')


@st.cache_data(ttl=21600, show_spinner=False)
def consultar_trimestral():
    try:
        pagina = descargar_publico_con_respaldo_zc(TRIMESTRAL_REPO, timeout=(3,8)); pagina.raise_for_status()
        candidatos = re.findall(r'href=["\']([^"\']*/handle/20\.500\.12160/\d+)["\'][^>]*>\s*Pron(?:ó|&oacute;)stico clim', pagina.text, re.I)
        if not candidatos:
            raise ValueError('No se identificó un informe trimestral en el repositorio oficial.')
        ficha = urljoin(TRIMESTRAL_REPO, candidatos[0])
        detalle = descargar_publico_con_respaldo_zc(ficha, timeout=(3,8)); detalle.raise_for_status()
        pdfs = re.findall(r'href=["\']([^"\']*bitstream[^"\']*\.pdf[^"\']*)["\']', detalle.text, re.I)
        if not pdfs:
            raise ValueError('El informe no tiene un PDF público identificable.')
        url = urljoin(ficha, html.unescape(pdfs[0]))
        if urlparse(url).hostname != 'repositorio.smn.gob.ar':
            raise ValueError('El PDF no pertenece al repositorio SMN.')
        pdf = descargar_publico_con_respaldo_zc(url, timeout=(3,8)); pdf.raise_for_status()
        return leer_pdf_trimestral(pdf.content, url)
    except Exception:
        return {'error':'No se pudo recuperar un informe trimestral verificable del repositorio SMN. Consultá la publicación oficial o cargá su PDF.',
                'referencia_documental':referencias_documentales_zc()['smn_trimestral']}


