def _inta_producto_permitido(seccion, producto, tipo):
    return any((seccion, producto, tipo) == p[:3] for p in PRODUCTOS_INTA.values())


@st.cache_data(ttl=3600, show_spinner=False)
def catalogo_inta(seccion, producto, tipo):
    url = INTA_BASE + '/productos/geosepa/componentes/listar_archivos.php'
    if not _inta_producto_permitido(seccion, producto, tipo):
        return {'catalogo': {}, 'error': 'Producto no incluido en el catálogo de esta página.', 'url': url}
    try:
        r = requests.get(url, params={'seccion': seccion, 'producto': producto, 'tipo': tipo},
                         timeout=(3, 8), headers={'User-Agent': 'Alerta-Zarate-Campana (fuentes publicas)'})
        r.raise_for_status()
        if urlparse(r.url).hostname != 'sepa.inta.gob.ar' or len(r.content) > 1_000_000:
            raise ValueError('Respuesta del catálogo fuera del origen o tamaño esperado')
        datos = r.json()
        if not isinstance(datos, dict) or not datos:
            raise ValueError('Catálogo vacío o formato no reconocido')
        return {'catalogo': datos, 'consultado': ahora().isoformat(), 'url': r.url, 'error': ''}
    except Exception:
        return {'catalogo': {}, 'url': url, 'error':
                'No se pudo consultar el catálogo público INTA.'}


def fechas_producto_inta(catalogo, tipo):
    filas = []
    if not isinstance(catalogo, dict) or tipo not in ('decada', 'juliano'):
        return filas
    for year, valores in catalogo.items():
        if not re.fullmatch(r'\d{4}', str(year)) or not 1900 <= int(year) <= 2100:
            continue
        if tipo == 'decada' and isinstance(valores, dict):
            for mes, decadas in valores.items():
                if not isinstance(decadas, (list, tuple)):
                    continue
                for decada in decadas:
                    try:
                        dec = int(decada)
                        if dec not in (1, 2, 3):
                            continue
                        inicio = datetime(int(year), int(mes), 1 + 10 * (dec - 1))
                        siguiente = (inicio.replace(day=28) + timedelta(days=4)).replace(day=1)
                        fin = inicio.replace(day=10 * dec) if dec < 3 else siguiente - timedelta(days=1)
                        filas.append({'inicio': inicio, 'fin': fin,
                                      'sufijo': f'{int(year):04}{int(mes):02}_{dec}'})
                    except (ValueError, TypeError, OverflowError):
                        continue
        elif tipo == 'juliano' and isinstance(valores, (list, tuple)):
            for juliano in valores:
                try:
                    jul = int(juliano)
                    inicio = datetime(int(year), 1, 1) + timedelta(days=jul - 1)
                    if jul < 1 or inicio.year != int(year):
                        continue
                    fin = min(inicio + timedelta(days=15), datetime(int(year), 12, 31))
                    filas.append({'inicio': inicio, 'fin': fin, 'sufijo': f'{int(year):04}{jul:03}'})
                except (ValueError, TypeError, OverflowError):
                    continue
    unicas = {f['sufijo']: f for f in filas}
    return sorted(unicas.values(), key=lambda x: x['inicio'], reverse=True)[:10000]


@st.cache_data(ttl=21600, show_spinner=False)
def imagen_inta_publica(seccion, producto, nombre):
    permitido = next((p for p in PRODUCTOS_INTA.values() if p[:2] == (seccion, producto)), None)
    if permitido is None:
        return {'error': 'Producto INTA no reconocido.'}
    patron = (re.escape(permitido[3]) + r'_\d{6}_[123]' if permitido[2] == 'decada'
              else re.escape(permitido[3]) + r'_\d{7}')
    if not re.fullmatch(patron, str(nombre)):
        return {'error': 'Nombre de imagen INTA no reconocido.'}
    base = f'{INTA_BASE}/productos/geosepa/{seccion}/{producto}/jpg/{nombre}'
    extensiones = ('gif', 'jpg', 'png') if producto == 'compuesto_16d_ndvi' else ('jpg', 'png', 'gif')
    for ext in extensiones:
        try:
            r = requests.get(base + '.' + ext, timeout=(3, 8),
                             headers={'User-Agent': 'Alerta-Zarate-Campana (fuentes publicas)'})
            if r.status_code == 404:
                continue
            r.raise_for_status()
            if urlparse(r.url).hostname != 'sepa.inta.gob.ar' or not 100 < len(r.content) <= 12_000_000:
                raise ValueError('Origen o tamaño de imagen no esperado')
            with Image.open(BytesIO(r.content)) as imagen:
                ancho, alto = imagen.size
                formato = imagen.format
                if formato not in ('JPEG', 'PNG', 'GIF') or ancho * alto > 25_000_000:
                    raise ValueError('Formato o dimensiones de imagen no admitidos')
                imagen.verify()
            return {'bytes': r.content, 'url': r.url, 'error': '', 'ancho': ancho, 'alto': alto,
                    'formato': formato, 'consultado': ahora().isoformat(),
                    'mime': {'JPEG': 'image/jpeg', 'PNG': 'image/png', 'GIF': 'image/gif'}[formato]}
        except Exception:
            break
    return {'error': 'No se pudo recuperar una imagen pública verificable del período elegido.'}


def mostrar_catalogo_inta_zc():
    st.subheader('INTA SEPA · mapas publicados de suelo y vegetación')
    st.write('Explorá productos y períodos oficiales con su leyenda original. Son mapas regionales que incluyen Buenos Aires; no una medición en cada punto de Zárate–Campana.')
    producto = st.selectbox('Producto oficial INTA', list(PRODUCTOS_INTA), key='zc_inta_producto')
    seccion, codigo, tipo, prefijo = PRODUCTOS_INTA[producto]
    pagina = f'{INTA_BASE}/productos/geosepa/{seccion}/{codigo}/'
    meta = INTA_PRODUCTOS_META[codigo]
    st.caption(meta['descripcion'])
    st.caption('Variable: ' + meta['variable'] + ' · Unidad: ' + meta['unidad'] + ' · ' + meta['ventana'])
    st.info(meta['limite'])
    if st.button('Volver a consultar productos INTA', key='zc_inta_actualizar'):
        catalogo_inta.clear()
        imagen_inta_publica.clear()
    with st.spinner('Consultando períodos publicados por INTA…'):
        resultado = catalogo_inta(seccion, codigo, tipo)
    periodos = fechas_producto_inta(resultado.get('catalogo'), tipo)
    hoy = ahora().date()
    disponibles = [f for f in periodos if f['fin'].date() <= hoy]
    if resultado.get('error'):
        st.warning(resultado['error'] + ' Abrí la fuente oficial o volvé a consultar más tarde.')
    elif not disponibles:
        st.warning('El catálogo no tiene períodos cerrados con fechas reconocidas. No se presenta un mapa sin período verificable.')
    else:
        consulta = _ui_fecha_local(resultado.get('consultado'))
        st.caption('Consulta del catálogo: ' + (consulta.strftime('%d/%m/%Y %H:%M ART') if consulta is not None else 'sin confirmar') + '. Esta fecha no es la emisión ni el período de observación del mapa.')
        anios = sorted({f['inicio'].year for f in disponibles}, reverse=True)
        clave_anio = 'zc_inta_anio_' + codigo
        if st.session_state.get(clave_anio) not in anios:
            st.session_state.pop(clave_anio, None)
        anio = st.selectbox('Año del archivo publicado', anios, key=clave_anio)
        por_anio = [f for f in disponibles if f['inicio'].year == anio]
        sufijos = [f['sufijo'] for f in por_anio]
        por_sufijo = {f['sufijo']: f for f in por_anio}
        clave_periodo = 'zc_inta_periodo_' + codigo + '_' + str(anio)
        if st.session_state.get(clave_periodo) not in sufijos:
            st.session_state.pop(clave_periodo, None)
        sufijo = st.selectbox('Período publicado', sufijos,
            format_func=lambda valor: f'{por_sufijo[valor]["inicio"]:%d/%m/%Y} – {por_sufijo[valor]["fin"]:%d/%m/%Y}',
            key=clave_periodo)
        fecha = por_sufijo[sufijo]
        dias = (hoy - fecha['fin'].date()).days
        st.caption(f'La ventana terminó hace {dias} días. El mapa representa ese período; no se presenta como lectura de hoy.')
        if len(disponibles) != len(periodos):
            st.caption('Se omiten del selector los períodos cuya ventana termina después de hoy.')
        with st.spinner('Recuperando el mapa público del período elegido…'):
            imagen = imagen_inta_publica(seccion, codigo, prefijo + '_' + sufijo)
        if imagen.get('error'):
            st.warning(imagen['error'] + ' La falta de imagen no significa suelo seco ni ausencia de inundación.')
        else:
            st.image(imagen['bytes'], use_container_width=True,
                     caption=f'INTA SEPA · {producto} · {fecha["inicio"]:%d/%m/%Y} a {fecha["fin"]:%d/%m/%Y} · leyenda original')
            st.link_button('Abrir imagen original de INTA', imagen['url'])
            extension = {'JPEG': 'jpg', 'PNG': 'png', 'GIF': 'gif'}[imagen['formato']]
            st.download_button('Descargar mapa oficial', imagen['bytes'], prefijo + '_' + sufijo + '.' + extension,
                               imagen['mime'], key='zc_inta_mapa_descarga')
        with st.expander('Archivo de períodos y procedencia'):
            tabla = pd.DataFrame([{'Inicio': f['inicio'].strftime('%Y-%m-%d'),
                                  'Fin': f['fin'].strftime('%Y-%m-%d'), 'Identificador publicado': f['sufijo']}
                                 for f in disponibles])
            st.dataframe(tabla, hide_index=True, use_container_width=True)
            st.download_button('Descargar períodos del catálogo', tabla.to_csv(index=False).encode('utf-8-sig'),
                               'INTA_' + codigo + '_periodos.csv', 'text/csv', key='zc_inta_periodos_descarga')
            st.link_button('Catálogo público utilizado', resultado['url'])
            st.caption('Las fechas se interpretan a partir del catálogo decadal o del día juliano del compuesto. No se obtiene una fecha de emisión independiente ni valores locales del mapa.')
    st.link_button('Descripción, metodología y descargas oficiales del producto', pagina)
    if meta.get('metodologia'):
        st.link_button('Leer metodología oficial INTA', meta['metodologia'])
    st.link_button('Abrir todos los productos INTA SEPA', INTA_BASE + '/productos/')
    st.caption('Fuente: INTA · equipo SEPA, Instituto de Clima y Agua. Se conserva la imagen oficial y su leyenda.')
    st.caption('La cartografía conserva su extensión y leyenda originales. No se superpone con límites inventados ni modifica el semáforo meteorológico.')



def _zc_hidro_invalidar_observaciones_guardadas():
    st.session_state.pop('zc_ina_observaciones_guardadas',None)


def _zc_hidro_conservar_observaciones_zc(resultado,serie_id,dias):
    """Preserve successful queries across UI reruns; replace errors without old current data."""
    if not isinstance(resultado,dict):
        resultado={'df':pd.DataFrame(),'error':'La consulta INA no devolvió un resultado verificable.'}
    bucket=dict(st.session_state.get('zc_ina_observaciones_guardadas',{}))
    clave=f'{int(serie_id)}:{int(dias)}'
    if resultado.get('error'):
        # A failed refresh invalidates earlier period views of the same station.
        bucket={k:v for k,v in bucket.items() if not str(k).startswith(f'{int(serie_id)}:')}
        resultado={**resultado,'df':pd.DataFrame()}
    bucket[clave]={**resultado,'serie_id':int(serie_id),'dias':int(dias),
                   'consulta':resultado.get('consulta') or ahora().isoformat()}
    st.session_state['zc_ina_observaciones_guardadas']=bucket


def _zc_hidro_observaciones_para_mostrar_zc(resultado,serie_id,dias,referencia=None):
    ref=_ui_fecha_local(referencia if referencia is not None else ahora())
    if not isinstance(resultado,dict) or resultado.get('serie_id')!=int(serie_id) or resultado.get('dias')!=int(dias):
        return {'df':pd.DataFrame(),'actual':False,'error':'La consulta guardada no coincide con la estación y el período seleccionados.'}
    if resultado.get('error'):
        return {**resultado,'df':pd.DataFrame(),'actual':False}
    df=resultado.get('df')
    if not isinstance(df,pd.DataFrame) or df.empty or not {'fecha','observado'}.issubset(df.columns):
        return {**resultado,'df':pd.DataFrame(),'actual':False,'error':'La consulta guardada no contiene fechas y alturas observadas utilizables.'}
    df=df.copy()
    fechas=df.fecha.map(_ui_fecha_local)
    alturas=pd.to_numeric(df.observado,errors='coerce')
    validos=fechas.notna() & np.isfinite(alturas)
    df=df.loc[validos].copy()
    df['fecha']=fechas.loc[validos]
    df['observado']=alturas.loc[validos]
    df=df.sort_values('fecha').drop_duplicates('fecha',keep='last')
    if df.empty or ref is None:
        return {**resultado,'df':pd.DataFrame(),'actual':False,'error':'No se pudo verificar el tiempo de las observaciones guardadas.'}
    ultimo=df.iloc[-1]
    edad_h=(ref-ultimo.fecha).total_seconds()/3600
    zona=ultimo.get('zona_horaria_verificada',False)
    zona_confirmada=isinstance(zona,(bool,np.bool_)) and bool(zona)
    actual=bool(zona_confirmada and np.isfinite(edad_h) and 0<=edad_h<=6)
    return {**resultado,'df':df,'ultimo':ultimo,'edad_horas':edad_h,'actual':actual,'error':''}


