def _zc_fecha_es(texto):
    meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre']
    patron = r'\b(\d{1,2})\s+de\s+(' + '|'.join(meses) + r')\s+de\s+(20\d{2})\b'
    match = re.search(patron, normalizar_nombre(texto).lower())
    if not match:
        return None
    try:
        return datetime(int(match[3]), meses.index(match[2])+1, int(match[1]), tzinfo=TZ)
    except ValueError:
        return None


def parsear_discusion_enos(contenido):
    texto = re.sub(r'<(?:script|style)\b[^>]*>.*?</(?:script|style)>', '', str(contenido), flags=re.I|re.S)
    texto = html.unescape(re.sub(r'<[^>]+>', ' ', texto))
    texto = re.sub(r'\s+', ' ', texto).strip()
    cabecera = re.search(r'DISCUSI[ÓO]N\s+DIAGN[ÓO]STICA', texto, flags=re.I)
    estado = re.search(r'Estatus del Sistema de alerta del ENSO\s*:\s*(.{1,180}?)\s*Sinopsis\s*:', texto, flags=re.I)
    if not cabecera or not estado:
        raise ValueError('No se reconoció la discusión diagnóstica oficial en español.')
    emision = _zc_fecha_es(texto[cabecera.end():estado.start()])
    if emision is None:
        raise ValueError('La discusión no tiene una fecha de emisión identificable.')
    siguiente_match = re.search(r'pr[óo]xima Discusi[óo]n Diagn[óo]stica.*?programada para(?: el)?\s+(.{1,70})', texto, flags=re.I)
    siguiente = _zc_fecha_es(siguiente_match[1]) if siguiente_match else None
    return {'emision':emision, 'estado':estado[1].strip(), 'siguiente':siguiente,
            'url':ENSO_ADVISORY_URL, 'consulta':ahora().isoformat(), 'error':''}


