def vigencia_roni(df, referencia=None):
    if df.empty:
        return {'estado':'sin_datos', 'fin':None, 'esperado':None}
    ref = pd.Timestamp(referencia if referencia is not None else ahora())
    ref = ref.tz_localize(TZ) if ref.tzinfo is None else ref.tz_convert(TZ)
    ultimo = df.sort_values(['año','mes_central']).iloc[-1]
    central = pd.Timestamp(year=int(ultimo['año']), month=int(ultimo['mes_central']), day=1, tz=TZ)
    fin = central + pd.DateOffset(months=2) - pd.Timedelta(seconds=1)
    # NOAA publishes by the 5th: then the last completed calendar month is expected.
    inicio_mes = ref.normalize().replace(day=1)
    esperado = inicio_mes - pd.Timedelta(seconds=1)
    if ref.day < 5:
        esperado = inicio_mes - pd.DateOffset(months=1) - pd.Timedelta(seconds=1)
    estado = 'futuro' if fin > ref else 'atrasado' if fin < esperado else 'periodo_reciente'
    return {'estado':estado, 'fin':fin, 'esperado':esperado}


