def estado_periodo_trimestral(inicio, fin, referencia=None):
    ref = fecha_fuente(referencia if referencia is not None else ahora())
    inicio, fin = fecha_fuente(inicio), fecha_fuente(fin)
    if fin < inicio:
        raise ValueError('El período termina antes de comenzar.')
    if inicio > ref:
        return 'previsto'
    if fin < ref:
        return 'vencido'
    return 'vigente_mes_actual' if (inicio.year,inicio.month)==(ref.year,ref.month) else 'vigente_iniciado_antes'


def validar_eventos_locales_zc(df):
    requeridas = {'evento_id','partido','localidad','lat','lon','fecha_inicio','fecha_fin',
                  'tipo_evento','anegamiento_confirmado','fuente_impacto','autoridad',
                  'emision_pronostico','indice_pronosticado','fecha_evidencia','observaciones'}
    if not requeridas.issubset(df.columns):
        raise ValueError('Faltan columnas: '+', '.join(sorted(requeridas-set(df.columns))))
    if not 1 <= len(df) <= 2000:
        raise ValueError('Se necesitan de 1 a 2.000 registros.')
    d = df.copy()
    for campo in requeridas - {'lat','lon','indice_pronosticado'}:
        d[campo] = d[campo].fillna('').astype(str).str.strip()
    if d.evento_id.eq('').any() or d.evento_id.duplicated().any():
        raise ValueError('Cada registro necesita un evento_id único.')
    if not d.partido.map(normalizar_nombre).isin(['ZARATE','CAMPANA']).all():
        raise ValueError('Los partidos admitidos son Zárate y Campana.')
    if d.localidad.eq('').any():
        raise ValueError('Cada registro necesita una localidad o sector.')
    for campo in ['lat','lon','indice_pronosticado']:
        aportado=d[campo].fillna('').astype(str).str.strip().ne('')
        convertido=pd.to_numeric(d[campo],errors='coerce')
        if (aportado & convertido.isna()).any() or d[campo].map(lambda valor:isinstance(valor,(bool,np.bool_))).any():
            raise ValueError('Campo declarado no numérico: '+campo)
        d[campo] = convertido
    if not all(provincia_de_coordenadas(lat,lon) for lat,lon in zip(d.lat,d.lon)):
        raise ValueError('Las coordenadas deben pertenecer al entorno de trabajo Zárate–Campana.')
    tipos = {'lluvia_anegamiento','crecida','sudestada','control_negativo'}
    if not d.tipo_evento.isin(tipos).all():
        raise ValueError('Tipo de evento: lluvia_anegamiento, crecida, sudestada o control_negativo.')
    if not d.anegamiento_confirmado.isin(['si','no','sin_confirmar']).all():
        raise ValueError('Anegamiento: si, no o sin_confirmar.')
    if (d.tipo_evento.eq('control_negativo') & d.anegamiento_confirmado.ne('no')).any():
        raise ValueError('Un control negativo necesita ausencia de anegamiento documentada como no.')
    for campo in ['fecha_inicio','fecha_fin','fecha_evidencia']:
        if d[campo].eq('').any():
            raise ValueError('Cada registro necesita '+campo+'.')
        d[campo] = d[campo].map(fecha_fuente)
    if (d.fecha_fin < d.fecha_inicio).any():
        raise ValueError('Un evento termina antes de comenzar.')
    if any((d[campo] > fecha_fuente(ahora())).any() for campo in ['fecha_inicio','fecha_fin','fecha_evidencia']):
        raise ValueError('Un registro histórico no puede tener inicio, final o evidencia futuros.')
    if (d.fecha_evidencia < d.fecha_inicio).any():
        raise ValueError('La evidencia de impacto no puede preceder al inicio del episodio.')
    if (d.tipo_evento.eq('control_negativo') & (d.fecha_evidencia < d.fecha_fin)).any():
        raise ValueError('La evidencia del control negativo debe cubrir el período completo hasta su final.')
    d['emision_pronostico'] = d.emision_pronostico.map(lambda valor:fecha_fuente(valor) if valor else pd.NaT)
    indices = d.indice_pronosticado.dropna()
    if not indices.between(0,100).all():
        raise ValueError('Los índices aportados deben estar entre 0 y 100.')
    for fuente in d.fuente_impacto:
        url_publica_evidencia(fuente)
    if d.autoridad.eq('').any():
        raise ValueError('Cada registro necesita autoridad o responsable de la evidencia.')
    d['prediccion_previa_registrada'] = [pd.notna(emision) and np.isfinite(indice) and emision<=inicio
        for emision,indice,inicio in zip(d.emision_pronostico,d.indice_pronosticado,d.fecha_inicio)]
    d['procedencia'] = 'Registro aportado por el usuario; evidencia sin verificación independiente'
    return d


def mostrar_registro_validacion_local_zc():
    st.subheader('Registro de episodios y controles locales')
    st.caption('Cargá la plantilla de esta pestaña para revisar y conservar la evidencia. Fechas ISO interpretadas en ART cuando no tienen offset; coordenadas aproximadas del sector. Tipos: lluvia_anegamiento, crecida, sudestada o control_negativo. Anegamiento: si, no o sin_confirmar.')
