SINARAME_RADAR_LOCAL_ID = "RMA2"


SINARAME_SELECTOR_ID = "radar-selector"


def _sinarame_catalogo_desde_html(texto):
    selector = re.search(r'<select\b[^>]*\bid=["\']'+re.escape(SINARAME_SELECTOR_ID)+r'["\'][^>]*>(.*?)</select>', str(texto), re.I|re.S)
    if not selector:
        return {}
    catalogo = {}
    for codigo, etiqueta in re.findall(r'<option\b[^>]*\bvalue=["\'](RMA\d+)["\'][^>]*>(.*?)</option>', selector.group(1), re.I|re.S):
        nombre = html.unescape(re.sub(r'<[^>]+>', '', etiqueta)).strip()
        if nombre and len(nombre) <= 100 and re.fullmatch(r'RMA\d{1,3}',codigo):
            catalogo[codigo] = nombre
    return catalogo


def _sinarame_permite_incrustar(headers):
    normalizados = {str(k).lower():str(v) for k,v in headers.items()}
    xfo = normalizados.get('x-frame-options','').upper()
    if 'DENY' in xfo or 'SAMEORIGIN' in xfo:
        return False
    politica = normalizados.get('content-security-policy','')
    ancestros = re.search(r'(?:^|;)\s*frame-ancestors\s+([^;]+)', politica, re.I)
    # A restrictive ancestor list is conservatively handled by opening the source.
    return not ancestros or any(x in ('*','https:') for x in ancestros.group(1).split())


