def _observaciones_smn_regionales(df, referencia=None):
    """Normaliza fechas y coordenadas sin afirmar una estación física en cada localidad."""
    if df.empty or not {'lat','lon'}.issubset(df.columns):
        return pd.DataFrame()
    resultado=df.copy()
    for campo in ('lat','lon'):
        resultado[campo]=pd.to_numeric(resultado[campo],errors='coerce')
    resultado=resultado[np.isfinite(resultado.lat)&np.isfinite(resultado.lon)
                        &resultado.lat.between(-90,90)&resultado.lon.between(-180,180)].copy()
    if resultado.empty:
        return resultado
    distancias=[]
    for nodo in NODOS:
        valor=2*6371.0088*np.arcsin(np.sqrt(np.clip(
            np.sin(np.radians(resultado.lat-nodo['lat'])/2)**2
            +np.cos(np.radians(nodo['lat']))*np.cos(np.radians(resultado.lat))
            *np.sin(np.radians(resultado.lon-nodo['lon'])/2)**2,0,1)))
        distancias.append(valor.to_numpy())
    resultado['distancia_referencia_km']=np.min(distancias,axis=0).round(1)
    resultado=resultado[resultado.distancia_referencia_km<=150].copy()
    if resultado.empty:
        return resultado
    estados=[_estado_observacion_smn(valor,referencia) for valor in resultado.get('fecha_smn',pd.Series(None,index=resultado.index))]
    resultado['fecha_smn']=[valor[0] for valor in estados]
    resultado['antiguedad_horas_smn']=[round(valor[1],1) if np.isfinite(valor[1]) else np.nan for valor in estados]
    resultado['estado_observacion_smn']=[valor[2] for valor in estados]
    resultado['observacion_actual_smn']=resultado.estado_observacion_smn.eq('Actual · hasta 3 h')
    for campo in ('temperatura_smn','humedad_smn','presion_smn','sensacion_smn','visibilidad_smn','viento_smn'):
        if campo not in resultado:
            continue
        valores=pd.to_numeric(resultado[campo],errors='coerce')
        validos=np.isfinite(valores)
        if campo=='humedad_smn':validos &= valores.between(0,100)
        elif campo in ('presion_smn','visibilidad_smn','viento_smn'):validos &= valores>=0
        resultado[campo]=valores.where(validos,np.nan)
    claves=[campo for campo in ('smn_id','lat','lon') if campo in resultado]
    return resultado.sort_values('fecha_smn',na_position='first').drop_duplicates(claves,keep='last').sort_values('distancia_referencia_km')


def _parsear_indice_cap_smn(contenido):
    """Acepta el RSS oficial y su vista HTML, que el SMN negocia por User-Agent."""
    if len(contenido) > 3_000_000:
        raise ValueError('El índice CAP excede el tamaño admitido.')
    links, invalidos, fechas = [], 0, []
    texto = contenido.decode('utf-8', errors='replace')
    if re.search(r'<(?:!doctype\s+html|html)\b', texto[:1000], re.I):
        formato = 'Índice HTML oficial'
        candidatos = re.findall(r'href\s*=\s*["\']([^"\']+\.xml(?:\?[^"\']*)?)["\']', texto, re.I)
        fechas_texto = re.findall(r'class\s*=\s*["\'][^"\']*\bfecha\b[^"\']*["\'][^>]*>(.*?)</', texto, re.I|re.S)
        for valor in fechas_texto:
            try:
                fecha = parsedate_to_datetime(re.sub('<[^>]*>', '', html.unescape(valor)).strip())
                if fecha.tzinfo is not None:
                    fechas.append(fecha.astimezone(timezone.utc))
            except (TypeError, ValueError):
                pass
    else:
        formato = 'RSS oficial'
        root = _xml_seguro(contenido)
        channel = root.find('channel')
        if channel is None:
            raise ValueError('La respuesta no tiene un canal RSS verificable.')
        candidatos = [item.findtext('link', default='') for item in channel.findall('item')]
        for tag in ('lastBuildDate', 'pubDate'):
            try:
                fecha = parsedate_to_datetime(channel.findtext(tag, default=''))
                if fecha.tzinfo is not None:
                    fechas.append(fecha.astimezone(timezone.utc))
                    break
            except (TypeError, ValueError):
                pass
    for candidato in candidatos:
        url = _url_cap_oficial(html.unescape(candidato))
        if url:
            if url not in links:
                links.append(url)
        else:
            invalidos += 1
    if not links and formato == 'Índice HTML oficial':
        raise ValueError('El índice HTML no permite identificar documentos CAP oficiales.')
    return {'links':links, 'invalidos':invalidos, 'fecha_feed':max(fechas) if fechas else None,
            'formato':formato}


def _estado_fecha_emision_cap(fila, instante):
    emision = fila.get('emision')
    if not isinstance(emision, datetime) or emision.tzinfo is None:
        return 'Fecha sin confirmar'
    if emision > instante + timedelta(minutes=5):
        return 'Fecha futura · sin confirmar'
    hasta = fila.get('hasta')
    if isinstance(hasta, datetime) and hasta < emision:
        return 'Fechas incoherentes · sin confirmar'
    return 'Confirmada'


