@st.cache_data(ttl=120, max_entries=80, show_spinner=False)
def descargar_frame_sinarame(radar_id, marca):
    if radar_id != SINARAME_RADAR_LOCAL_ID or not re.fullmatch(r'\d{14}',str(marca)):
        return None
    try:
        fecha = datetime.strptime(str(marca),'%Y%m%d%H%M%S').replace(tzinfo=TZ)
        url = f'{SINARAME_PUBLIC_URL}cache/{radar_id}/{marca}.png'
        respuesta = requests.get(url, headers={'User-Agent':'ALA-Zarate-Campana/1.2'}, timeout=(2.5,4))
        respuesta.raise_for_status()
        if len(respuesta.content)>8_000_000:
            return None
        with Image.open(BytesIO(respuesta.content)) as imagen:
            if imagen.format != 'PNG' or imagen.size != (512,512):
                return None
            ancho,alto=imagen.size
            imagen.verify()
        return {'url':url,'fecha':fecha,'imagen':respuesta.content,'ancho':ancho,'alto':alto,'verificado_en':ahora().isoformat()}
    except (requests.RequestException,OSError,ValueError,TypeError,Image.DecompressionBombError):
        return None


@st.cache_data(ttl=180, show_spinner=False)
def consultar_radar_sinarame(radar_id=SINARAME_RADAR_LOCAL_ID,cantidad=1):
    import time
    cantidad = cantidad if cantidad in (1,6,12) else 1
    if radar_id != SINARAME_RADAR_LOCAL_ID:
        return {'frames':[],'consultado':ahora().isoformat(),'intentados':0,'solicitados':cantidad,'parcial':False,'error':'Radar no configurado para esta consulta local.'}
    referencia = ahora()
    base = referencia.replace(minute=(referencia.minute//10)*10,second=0,microsecond=0)
    # The ten-minute ART grid and this public path were verified in the official viewer.
    # Every candidate must independently return a valid PNG; no URL itself is a datum.
    marcas = [(base-timedelta(minutes=10*i)).strftime('%Y%m%d%H%M%S') for i in range(18)]
    frames=[];intentados=0;limite=time.monotonic()+12
    for inicio in range(0,len(marcas),4):
        if time.monotonic()>=limite:
            break
        grupo=marcas[inicio:inicio+4]
        with ThreadPoolExecutor(max_workers=4) as pool:
            encontrados=list(pool.map(lambda marca:descargar_frame_sinarame(radar_id,marca),grupo))
        intentados+=len(grupo)
        frames.extend(f for f in encontrados if f is not None)
        if len(frames)>=cantidad:
            break
    frames=sorted(frames,key=lambda f:f['fecha'])[-cantidad:]
    parcial=len(frames)<cantidad
    tiempo_agotado=parcial and intentados<len(marcas)
    return {'frames':frames,'consultado':ahora().isoformat(),'intentados':intentados,'solicitados':cantidad,'parcial':parcial,'tiempo_agotado':tiempo_agotado,
            'error':'' if frames else 'No se recibió una imagen PNG válida en esta búsqueda acotada. No permite confirmar ausencia de lluvia.'}


def _sinarame_leyenda_html():
    # Colors and stop offsets transcribed from the SVG legend of the official viewer.
    colores=['#3d416b','#3b4f78','#3d5989','#3d6595','#3772a6','#3189bb','#25a1cf',
             '#4ce132','#3ab027','#237219','#c9d333','#d69818','#c50017','#c1005f',
             '#cb00cd','#e2f5ee','#a7ecce','#88dfbd','#88dfbd']
    gradiente=', '.join(color+' '+f'{i*100/18:.2f}%' for i,color in enumerate(colores))
    return f'<div style="max-width:640px;margin:6px 0 16px;font-family:system-ui"><b>Reflectividad · dBZ · escala oficial SINARAME</b><div style="height:18px;border:1px solid #64748b;background:linear-gradient(to right,{gradiente})"></div><div style="display:flex;justify-content:space-between;font-size:12px"><span>−15</span><span>0</span><span>15</span><span>30</span><span>45</span><span>60</span><span>75</span></div></div>'


def _sinarame_documento_secuencia(frames):
    items=[{'src':'data:image/png;base64,'+base64.b64encode(f['imagen']).decode('ascii'),
            'hora':f['fecha'].strftime('%d/%m/%Y %H:%M ART')} for f in frames]
    documento='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{margin:0;font:14px system-ui;background:#101820;color:white}.tools{display:flex;align-items:center;gap:14px;padding:10px;flex-wrap:wrap}button{padding:8px 16px;cursor:pointer}input{flex:1;min-width:120px}img{display:block;width:100%;height:550px;object-fit:contain}</style><div class="tools"><button id="play">▶ Reproducir</button><input aria-label="Imagen radar" id="range" type="range" min="0"><span id="time"></span></div><img id="img" alt="Imágenes verificadas del radar Ezeiza SINARAME"><script>const frames=__FRAMES__;let i=frames.length-1,timer=null;const slider=document.getElementById('range'),button=document.getElementById('play');slider.max=frames.length-1;function draw(){slider.value=i;document.getElementById('img').src=frames[i].src;document.getElementById('time').textContent=frames[i].hora;}function pause(){clearInterval(timer);timer=null;button.textContent='▶ Reproducir';}slider.oninput=()=>{pause();i=Number(slider.value);draw();};button.onclick=()=>{if(timer){pause();return;}button.textContent='⏸ Pausar';timer=setInterval(()=>{i=(i+1)%frames.length;draw();},700);};window.addEventListener('pagehide',pause);draw();</script></html>'''
    return documento.replace('__FRAMES__',json.dumps(items).replace('</','<\\/'))


def _sinarame_documento_mapa(frames):
    items=[]
    for frame in frames:
        origen=urlparse(str(frame.get('url','')))
        if origen.hostname != urlparse(SINARAME_PUBLIC_URL).hostname or not re.fullmatch(r'/cache/RMA2/\d{14}\.png',origen.path):
            continue
        try:
            with Image.open(BytesIO(frame['imagen'])) as imagen:
                if imagen.format!='PNG' or imagen.size!=(512,512):
                    continue
                imagen.verify()
            items.append({'src':'data:image/png;base64,'+base64.b64encode(frame['imagen']).decode('ascii'),
                          'hora':frame['fecha'].strftime('%d/%m/%Y %H:%M ART')})
        except (OSError,ValueError,TypeError,KeyError,Image.DecompressionBombError):
            continue
    # Placement reproduced from visible official IGN tiles and image positioning,
    # cross-checked at zoom 12 and zoom 9 on the date below. This is an inference
    # from the official display, not a published geospatial metadata endpoint.
    payload={'frames':items,'bounds':SINARAME_RMA2_BOUNDS,'centro':[MAP_CENTER_LAT,MAP_CENTER_LON],
             'nodos':NODOS,'revision':SINARAME_RMA2_GEO_REVISION}
    documento='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin><style>*{box-sizing:border-box}html,body{margin:0;background:#f8fafc;color:#173448;font:14px system-ui}.tools{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:8px}button{padding:7px 11px;border:1px solid #cbd5e1;border-radius:7px;background:#fff;color:#173448;cursor:pointer}button:disabled{opacity:.5;cursor:default}#range{flex:1;min-width:120px}#hora{font-weight:700;font-variant-numeric:tabular-nums}#map{height:580px;width:100%;border:1px solid #cbd5e1;border-radius:9px}#estado{min-height:28px;padding:8px;font-size:12px;color:#475569}.leaflet-tooltip{font-family:system-ui;font-size:12px}@media(max-width:500px){#map{height:500px}#hora{width:100%}.tools{gap:6px}}</style></head><body><div class="tools"><button id="local">📍 Zárate–Campana</button><button id="alcance">Ver alcance del producto</button><label for="opacidad">Opacidad de ecos</label><input id="opacidad" type="range" min="0" max="1" step="0.05" value="0.65"><output id="porcentaje">65%</output></div><div class="tools"><button id="antes" aria-label="Imagen anterior">◀</button><button id="play">▶ Reproducir</button><button id="despues" aria-label="Imagen siguiente">▶</button><input id="range" aria-label="Fecha de imagen radar" type="range" min="0" step="1"><span id="hora" aria-live="polite"></span></div><div id="map" aria-label="Radar Ezeiza sobre el entorno de Zárate y Campana"></div><div id="estado" role="status"></div><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin></script><script>const D=__DATA__,frames=D.frames;const estado=document.getElementById('estado'),hora=document.getElementById('hora'),slider=document.getElementById('range'),play=document.getElementById('play');const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));if(!window.L){estado.textContent='No se pudo cargar la cartografía. La imagen PNG y el visor oficial siguen disponibles en la página.';document.querySelectorAll('button,input').forEach(e=>e.disabled=true);}else{const M=L.map('map',{scrollWheelZoom:true,zoomSnap:.5}).setView(D.centro,9.5);const ign=L.tileLayer('https://wms.ign.gob.ar/geoserver/gwc/service/wmts?layer=capabaseargenmap&style=&tilematrixset=EPSG:3857&Service=WMTS&Request=GetTile&Version=1.0.0&Format=image/png&TileMatrix=EPSG:3857:{z}&TileCol={x}&TileRow={y}',{maxZoom:18,attribution:'© IGN Argentina'}).addTo(M);const osm=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'});let errores=0;ign.on('tileerror',()=>{if(++errores===3&&M.hasLayer(ign)){M.removeLayer(ign);osm.addTo(M);estado.textContent='Fondo OpenStreetMap: IGN no respondió en esta consulta.';}});M.createPane('referencias');M.getPane('referencias').style.zIndex=450;const puntos=L.layerGroup().addTo(M);D.nodos.forEach(n=>L.circleMarker([n.lat,n.lon],{pane:'referencias',radius:5,color:'#173448',weight:2,fillColor:'#fff',fillOpacity:1}).bindTooltip(esc(n.localidad)).bindPopup('<b>'+esc(n.localidad)+'</b><br>'+esc(n.partido)+' · Buenos Aires<br>Referencia meteorológica aproximada; no es una estación física.<br>'+esc(n.lat)+', '+esc(n.lon)).addTo(puntos));const bounds=L.latLngBounds(D.bounds);let i=frames.length-1,timer=null,eco=null;const capas={'Referencias locales aproximadas':puntos};if(frames.length){eco=L.imageOverlay(frames[i].src,bounds,{opacity:.65,interactive:false,alt:'Reflectividad verificada del radar Ezeiza SINARAME',attribution:'Radar: SINARAME / Recursos Hídricos'}).addTo(M);capas['Ecos radar SINARAME']=eco;eco.on('error',()=>{pause();estado.textContent='No se pudo mostrar esta imagen; conservá su fecha y consultá la fuente.';});estado.textContent='Ezeiza RMA2 · posición reproducida del visor oficial, revisión '+D.revision+'. Referencias locales aproximadas.';}else{hora.textContent='Sin imagen radar verificada';estado.textContent='Se muestran sólo las referencias geográficas; no informa ausencia de lluvia.';}L.control.layers({'IGN':ign,'OpenStreetMap':osm},capas,{collapsed:true}).addTo(M);L.control.scale({imperial:false}).addTo(M);document.getElementById('local').onclick=()=>M.setView(D.centro,9.5);document.getElementById('alcance').onclick=()=>M.fitBounds(bounds,{padding:[20,20]});slider.max=Math.max(0,frames.length-1);function draw(){if(!eco)return;slider.value=i;eco.setUrl(frames[i].src);hora.textContent=frames[i].hora;}function pause(){clearInterval(timer);timer=null;play.textContent='▶ Reproducir';}slider.oninput=()=>{pause();i=Number(slider.value);draw();};document.getElementById('antes').onclick=()=>{pause();i=(i-1+frames.length)%frames.length;draw();};document.getElementById('despues').onclick=()=>{pause();i=(i+1)%frames.length;draw();};play.onclick=()=>{if(timer){pause();return;}play.textContent='⏸ Pausar';timer=setInterval(()=>{i=(i+1)%frames.length;draw();},700);};['antes','despues','play','range'].forEach(id=>document.getElementById(id).disabled=frames.length<2);document.getElementById('opacidad').disabled=!eco;document.getElementById('opacidad').oninput=e=>{const v=Number(e.target.value);if(eco)eco.setOpacity(v);document.getElementById('porcentaje').textContent=Math.round(v*100)+'%';};window.addEventListener('pagehide',pause);window.addEventListener('resize',()=>M.invalidateSize());draw();M.invalidateSize();}</script></body></html>'''
    return documento.replace('__DATA__',json.dumps(payload,ensure_ascii=False).replace('</','<\\/'))




