def obtener_preparacion_inundaciones():
    """Entrega una copia para no modificar la orientación común entre sesiones."""
    return json.loads(json.dumps(PREPARACION_INUNDACIONES,ensure_ascii=False))


def mostrar_preparacion_inundaciones(key_prefix='prevencion_'):
    plan=obtener_preparacion_inundaciones()
    st.subheader('Prepará medidas antes de que llegue el agua')
    antes, durante=st.columns(2)
    with antes:
        st.markdown('**Antes del evento**')
        for accion in plan['antes']:
            st.write('• '+accion)
    with durante:
        st.markdown('**Si el agua ya afecta la zona**')
        for accion in plan['con_agua']:
            st.write('• '+accion)
    st.caption('Lluvia intensa, crecida y sudestada requieren comprobaciones complementarias. Un verde por lluvia no confirma seguridad en zonas bajas, costas o islas.')
    with st.expander('Preparación según tu entorno y fuentes oficiales',expanded=False):
        st.dataframe(pd.DataFrame(plan['entornos']),hide_index=True,use_container_width=True)
        st.caption('Confirmá puntos de encuentro, accesos y lugares de resguardo con la autoridad local. Esta página no declara refugios abiertos ni recorridos habilitados.')
        for i,fuente in enumerate(FUENTES_PREVENCION):
            st.link_button(fuente['organismo'],fuente['url'],key=key_prefix+'fuente_'+str(i))
        st.link_button('Zárate · contactos municipales','https://zarate.gob.ar/telefonos-utiles/',key=key_prefix+'contactos_zarate')
        st.link_button('Campana · contactos municipales','https://www.campana.gob.ar/telefonos-utiles/',key=key_prefix+'contactos_campana')


INA_REFERENCIAS_ZC_WFS = 'https://alerta.ina.gob.ar/geoserver/ows'


INA_REFERENCIAS_ZC_DOCUMENTACION = 'https://alerta.ina.gob.ar/pub/gui/metadata&layer=public2:ultimas_alturas_con_timeseries'


INA_REFERENCIAS_ZC_ESTACIONES = {40:'Zárate', 41:'Campana'}


def _numero_referencia_ina(valor, positivo=False):
    if valor is None or isinstance(valor,(bool,np.bool_)):
        return None
    try:
        numero=float(valor)
    except (ValueError,TypeError):
        return None
    if not np.isfinite(numero) or (positivo and numero<=0):
        return None
    return numero


def parsear_referencias_ina_zc(payload, fuente, consultado):
    """Read metadata only: do not interpret the layer's dates/values as live observations."""
    if not isinstance(payload,dict) or payload.get('type')!='FeatureCollection' or not isinstance(payload.get('features'),list):
        raise ValueError('INA no devolvió una colección GeoJSON de referencias hidrométricas.')
    referencias={}
    errores={}
    for feature in payload['features']:
        if not isinstance(feature,dict) or not isinstance(feature.get('properties'),dict):
            continue
        p=feature['properties']
        try:
            # An observed series is a different identity from a forecast series or site code.
            if isinstance(p.get('series_id'),bool):
                continue
            valor_serie=_numero_referencia_ina(p.get('series_id'))
            if valor_serie is None or not valor_serie.is_integer():
                continue
            serie=int(valor_serie)
        except (ValueError,TypeError,OverflowError):
            continue
        if serie not in INA_REFERENCIAS_ZC_ESTACIONES:
            continue
        nombre=texto_sin_html(p.get('nombre',''))
        esperado=INA_REFERENCIAS_ZC_ESTACIONES[serie]
        if normalizar_nombre(nombre)!=normalizar_nombre(esperado):
            errores[serie]='El nombre publicado no coincide con la estación observada esperada.'
            continue
        # This officially documented layer contains scale heights in metres; var_id=2 is stage.
        if str(p.get('var_id')) not in ('2','2.0') or p.get('tabla')!='alturas_prefe':
            errores[serie]='La red o variable no corresponden a la altura observada PNA configurada.'
            continue
        alerta=_numero_referencia_ina(p.get('nivel_de_alerta'),positivo=True)
        evacuacion=_numero_referencia_ina(p.get('nivel_de_evacuacion'),positivo=True)
        if alerta is None or evacuacion is None or evacuacion<=alerta:
            errores[serie]='Los umbrales publicados están ausentes, no son finitos o no tienen un orden válido.'
            continue
        cero=_numero_referencia_ina(p.get('cero_ign'))
        if cero is None:
            errores[serie]='El cero IGN de esta referencia no está identificado.'
            continue
        if serie in referencias:
            referencias.pop(serie,None)
            errores[serie]='La colección repite la referencia de esta serie; no se elige un duplicado.'
            continue
        if serie in errores:
            continue
        referencias[serie]={
            'serie_observada':serie,'estacion':esperado,'nombre_publicado':nombre,
            'red':'alturas_prefe','variable_id':2,'unidad':'m',
            'nivel_alerta_m':alerta,'nivel_evacuacion_m':evacuacion,'cero_ign_m':cero,
            'referencia_vertical':'Altura respecto del cero de la escala local; cero_ign publicado por INA',
            'fuente':fuente,'documentacion':INA_REFERENCIAS_ZC_DOCUMENTACION,
            'fecha_consulta':consultado,'fecha_documento_umbral':None,
            'vigencia_municipal_confirmada':False,
            'vinculo_serie_observada_confirmado':True,'vinculo_serie_pronostico_confirmado':False,
            'interpretacion':'Referencia publicada por INA para esta escala. No es una orden de evacuación; fecha de aprobación local no identificada.'}
    for serie in INA_REFERENCIAS_ZC_ESTACIONES:
        if serie not in referencias and serie not in errores:
            errores[serie]='La consulta no incluyó metadatos verificables de esta serie observada.'
    return {'referencias':referencias,'errores_por_serie':errores,'fuente':fuente,
            'consulta':consultado,'origen':'Consulta pública INA · referencias de escala',
            'error':'' if referencias else 'No se verificaron referencias hidrométricas locales.',
            'advertencia':'La fecha de consulta sólo acredita recuperación del catálogo. No acredita vigencia de la disposición local ni actualidad del río. Los umbrales no se aplican a los pronósticos 29534/3405 sin equivalencia documentada de escala.'}


@st.cache_data(ttl=300, show_spinner=False)
def consultar_referencias_ina_zc():
    """Fetch current public metadata; an unavailable reference is unknown, never zero."""
    consulta=ahora().isoformat()
    params={'service':'WFS','version':'1.0.0','request':'GetFeature',
            'typeName':'public2:ultimas_alturas_con_timeseries',
            'outputFormat':'application/json','CQL_FILTER':'series_id IN (40,41)',
            'propertyName':'series_id,nombre,var_id,tabla,nivel_de_alerta,nivel_de_evacuacion,cero_ign,fecha,valor,timeseries'}
    try:
        r=requests.get(INA_REFERENCIAS_ZC_WFS,params=params,
                       headers={'User-Agent':'Alerta-Zarate-Campana/prevencion-fuentes-publicas'},timeout=(3,8))
        r.raise_for_status()
        origen=urlparse(r.url)
        if origen.scheme!='https' or origen.hostname not in {'alerta.ina.gob.ar','alerta.ina.gov.ar'}:
            raise ValueError('La respuesta se redirigió fuera del servicio oficial INA.')
        payload=r.json()
        referencias=parsear_referencias_ina_zc(payload,r.url,consulta)
        referencias['observaciones_por_serie']=parsear_alturas_wfs_zc(payload,r.url,consulta)
        return referencias
    except (requests.RequestException,ValueError,TypeError,KeyError) as exc:
        return {'referencias':{},'errores_por_serie':{s:'Referencia sin confirmar por fallo de consulta.' for s in INA_REFERENCIAS_ZC_ESTACIONES},
                'fuente':INA_REFERENCIAS_ZC_WFS,'documentacion':INA_REFERENCIAS_ZC_DOCUMENTACION,
                'consulta':consulta,'origen':'Consulta INA no verificada',
                'error':'No se pudieron verificar los umbrales y el cero de las escalas locales.',
                'detalle_error':type(exc).__name__,
                'advertencia':'No se reemplaza la referencia ausente por cero ni se asigna una condición fluvial segura. Consultá INA y Defensa Civil.'}


