def _cuenca_normalizar_zc(texto):
    return re.sub(r'\s+', ' ', ''.join(c for c in unicodedata.normalize('NFD', str(texto))
                   if unicodedata.category(c) != 'Mn')).strip().casefold()

def _cuenca_estacion_zc(nombre, variable):
    for estacion, (tipo, alias) in CUENCA_INA_ESTACIONES_ZC.items():
        if tipo == variable and _cuenca_normalizar_zc(nombre) in {_cuenca_normalizar_zc(a) for a in alias}:
            return estacion
    return None

def _cuenca_url_ina_zc(url):
    origen = urlparse(str(url))
    try:puerto=origen.port
    except ValueError:return False
    return (origen.scheme == 'https' and origen.hostname in {'ina.gob.ar','www.ina.gob.ar','alerta.ina.gob.ar'}
            and not origen.username and not origen.password and puerto in {None,443})

def _cuenca_leer_html_zc(texto):
    """Extract cells, block text and links without third party HTML dependencies."""
    from html.parser import HTMLParser
    class Lector(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.tablas=[]; self.tabla=None; self.fila=None; self.celda=None
            self.partes=[]; self.enlaces=[]; self.enlace=None; self.ignorar=0
        def handle_starttag(self, tag, attrs):
            if tag in {'script','style'}:self.ignorar+=1
            if self.ignorar:return
            if tag=='table':self.tabla=[]
            elif tag=='tr':self.fila=[]
            elif tag in {'td','th'}:self.celda=[]
            elif tag=='a':self.enlace=[dict(attrs).get('href',''),[]]
            if tag in {'p','div','br','h1','h2','h3','h4','h5','tr','li'}:
                self.partes.append('\n')
                if self.celda is not None:self.celda.append(' ')
        def handle_data(self, data):
            if self.ignorar:return
            self.partes.append(data)
            if self.celda is not None:self.celda.append(data)
            if self.enlace is not None:self.enlace[1].append(data)
        def handle_endtag(self, tag):
            if tag in {'script','style'}:
                self.ignorar=max(0,self.ignorar-1);return
            if self.ignorar:return
            if tag in {'td','th'} and self.celda is not None:
                if self.fila is not None:self.fila.append(' '.join(''.join(self.celda).split()))
                self.celda=None
            elif tag=='tr' and self.fila is not None:
                if self.tabla is not None:self.tabla.append(self.fila)
                self.fila=None
            elif tag=='table' and self.tabla is not None:
                self.tablas.append(self.tabla);self.tabla=None
            elif tag=='a' and self.enlace is not None:
                self.enlaces.append((self.enlace[0],' '.join(''.join(self.enlace[1]).split())))
                self.enlace=None
            if tag in {'p','div','h1','h2','h3','h4','h5','tr','li'}:self.partes.append('\n')
    lector=Lector();lector.feed(str(texto))
    return {'tablas':lector.tablas,'texto':'\n'.join(x.strip() for x in ''.join(lector.partes).splitlines() if x.strip()),
            'enlaces':lector.enlaces}

def _cuenca_numero_zc(valor,caudal=False):
    texto=''.join(str(valor).split())
    if caudal and re.fullmatch(r'\d{1,3}(?:\.\d{3})+(?:,\d+)?',texto):
        texto=texto.replace('.','').replace(',','.')
    if not re.fullmatch(r'[+-]?\d+(?:[.,]\d+)?',texto):raise ValueError('Número publicado no reconocido.')
    numero=float(texto.replace(',','.'))
    if not np.isfinite(numero):raise ValueError('Número no finito.')
    return numero

def parsear_reporte_cuenca_ina_zc(texto,fuente=CUENCA_INA_DIARIO_ZC,consulta=None):
    if not _cuenca_url_ina_zc(fuente):raise ValueError('Fuente fuera del sitio oficial INA.')
    lectura=_cuenca_leer_html_zc(texto)
    plano=lectura['texto']
    match=re.search(r'Fecha de actualizaci[oó]n\s*:\s*(\d{2}/\d{2}/\d{4})',plano,re.I)
    if not match or 'Reporte hidrometeorológico diario de la Cuenca del Plata' not in plano:
        raise ValueError('No se verificó identidad y fecha del reporte diario INA.')
    emision=datetime.strptime(match[1],'%d/%m/%Y').date()
    filas=[]
    for tabla in lectura['tablas']:
        variable=None
        for celdas in tabla:
            cabecera=_cuenca_normalizar_zc(' '.join(celdas))
            if 'estacion' in cabecera and 'rio' in cabecera:
                variable='caudal' if 'caudal' in cabecera and ('3' in cabecera or '³' in cabecera) else 'nivel' if 'nivel' in cabecera and '(m)' in cabecera else None
                continue
            if variable is None or len(celdas)<3:continue
            estacion=_cuenca_estacion_zc(celdas[0],variable)
            if not estacion:continue
            # Arrows/icons may accompany the number, but all numeric text must be a single value.
            valor_texto=re.sub(r'[^0-9+.,\-]','',celdas[2])
            try:
                valor=_cuenca_numero_zc(valor_texto,variable=='caudal')
                if variable=='caudal' and valor<0:continue
            except ValueError:continue
            filas.append({'estacion':estacion,'nombre_publicado':celdas[0],'rio':celdas[1],
                'variable':variable,'valor':valor,'unidad':'m³/s' if variable=='caudal' else 'm',
                'fecha_documento':emision.isoformat(),'fecha_observacion':None,'serie_id':None,
                'perspectiva_publicada':celdas[5] if len(celdas)>5 else '',
                'tipo_dato':'Valor reproducido del reporte diario; hora de observación no publicada en la tabla',
                'fuente':fuente,'consulta':consulta or ahora().isoformat()})
    if not filas:raise ValueError('No se reconocieron tablas de nivel/caudal del reporte; no se inventan valores.')
    secciones={}
    for clave,inicio,fin in [('meteorologia','Situación meteorológica','Situación hidrológica'),
        ('paraguay_iguazu_parana','SISTEMA PARAGUAY - IGUAZÚ - PARANÁ:','FRENTE DEL DELTA:'),
        ('frente_delta','FRENTE DEL DELTA:','Gráficos de nivel observado y previsión')]:
        m=re.search(re.escape(inicio)+r'(.*?)'+re.escape(fin),plano,re.S|re.I)
        if m:secciones[clave]=m[1].strip()
    pdf=next((urljoin(fuente,u) for u,etiqueta in lectura['enlaces'] if 'versión pdf' in etiqueta.casefold()
              and _cuenca_url_ina_zc(urljoin(fuente,u))),None)
    return {'df':pd.DataFrame(filas),'emision':emision,'precision_emision':'día, sin hora publicada',
        'consulta':consulta or ahora().isoformat(),'fuente':fuente,'pdf_url':pdf,'secciones':secciones,
        'error':'','es_pronostico_local':False,'permite_alarma_local':False,
        'advertencia':'La fecha del parte no es la hora de observación de cada estación. Valores de cuenca para vigilancia; no se suman estaciones sucesivas ni se trasladan umbrales a Zárate–Campana.'}

@st.cache_data(ttl=600,show_spinner=False)
def consultar_reporte_cuenca_ina_zc():
    consulta=ahora().isoformat()
    try:
        r=requests.get(CUENCA_INA_DIARIO_ZC,headers={'User-Agent':'Alerta-Zarate-Campana/cuenca'},timeout=(4,10))
        r.raise_for_status()
        return parsear_reporte_cuenca_ina_zc(r.text,r.url,consulta)
    except (requests.RequestException,ValueError,TypeError,KeyError) as exc:
        return {'df':pd.DataFrame(),'emision':None,'consulta':consulta,'fuente':CUENCA_INA_DIARIO_ZC,
            'pdf_url':None,'secciones':{},'error':'No se verificó el reporte diario INA: '+type(exc).__name__,
            'es_pronostico_local':False,'permite_alarma_local':False}

def parsear_catalogo_cuenca_ina_zc(payload,fuente=CUENCA_INA_CATALOGO_ZC,consulta=None):
    if not _cuenca_url_ina_zc(fuente):raise ValueError('Catálogo fuera del sitio INA.')
    registros=payload if isinstance(payload,list) else payload.get('data',[]) if isinstance(payload,dict) else []
    if not isinstance(registros,list):raise ValueError('La respuesta del catálogo no tiene una lista de series.')
    filas=[]
    for dato in registros:
        if not isinstance(dato,dict):continue
        variable_nombre=_cuenca_normalizar_zc(dato.get('var_nombre',''))
        unidad_nombre=_cuenca_normalizar_zc(dato.get('unit_nombre',''))
        variable='caudal' if 'caudal' in variable_nombre and unidad_nombre in {'metros cubicos por segundo','m3/s','m³/s'} else 'nivel' if 'altura' in variable_nombre and unidad_nombre in {'metros','m'} else None
        estacion=_cuenca_estacion_zc(dato.get('estacion_nombre',''),variable)
        if estacion is None:continue
        try:
            ids={}
            for campo,origen in [('serie_id','seriesid'),('unidad_id','unitid'),('variable_id','varid')]:
                valor_id=dato[origen]
                if isinstance(valor_id,(bool,np.bool_)) or not re.fullmatch(r'\d+',str(valor_id)):raise ValueError('ID no entero.')
                ids[campo]=int(valor_id)
            if any(v<=0 for v in ids.values()):continue
        except (ValueError,TypeError,KeyError):continue
        filas.append({**ids,'estacion':estacion,'nombre_publicado':dato['estacion_nombre'],
            'variable':variable,'variable_publicada':dato['var_nombre'],'unidad_publicada':dato['unit_nombre'],
            'unidad':'m³/s' if variable=='caudal' else 'm','red':dato.get('red_nombre'),
            'procedimiento':dato.get('proc_nombre'),'estacion_id':dato.get('sitecode'),
            'fecha_inicio_catalogo':dato.get('from_date'),'fecha_fin_catalogo':dato.get('to_date'),
            'fuente_catalogo':fuente,'consulta_catalogo':consulta or ahora().isoformat()})
    if not filas:raise ValueError('Catálogo sin series de cuenca con nombre, variable e unidad verificables.')
    return {'df':pd.DataFrame(filas).drop_duplicates('serie_id'),'fuente':fuente,
        'consulta':consulta or ahora().isoformat(),'error':'',
        'advertencia':'Identificadores recuperados del catálogo; sus fechas no acreditan una observación actual. Distintas redes/procedimientos no se fusionan automáticamente.'}

@st.cache_data(ttl=1800,show_spinner=False)
def consultar_catalogo_cuenca_ina_zc():
    consulta=ahora().isoformat()
    try:
        r=requests.get(CUENCA_INA_CATALOGO_ZC,headers={'User-Agent':'Alerta-Zarate-Campana/cuenca'},timeout=(4,12))
        r.raise_for_status()
        return parsear_catalogo_cuenca_ina_zc(r.json(),r.url,consulta)
    except (requests.RequestException,ValueError,TypeError,KeyError) as exc:
        return {'df':pd.DataFrame(),'fuente':CUENCA_INA_CATALOGO_ZC,'consulta':consulta,
            'error':'No se verificaron identificadores/unidades de las series de cuenca: '+type(exc).__name__}

@st.cache_data(ttl=600,show_spinner=False)
def obtener_serie_cuenca_ina_zc(serie_id,dias=30):
    """Only use an ID found in the current INA catalog, never a guessed station ID."""
    consulta=ahora().isoformat()
    base={'df':pd.DataFrame(),'serie_id':serie_id,'consulta':consulta,'fuente':CUENCA_INA_DATOS_ZC,
          'error':'','permite_alarma_local':False}
    if isinstance(dias,(bool,np.bool_)) or not isinstance(dias,(int,np.integer)) or not 1<=int(dias)<=90:
        return {**base,'error':'Período inválido: elegí entre 1 y 90 días.'}
    catalogo=consultar_catalogo_cuenca_ina_zc()
    d=catalogo['df']
    if d.empty:return {**base,'error':catalogo['error']}
    selecion=d[d.serie_id.astype(str)==str(serie_id)]
    if len(selecion)!=1:return {**base,'error':'No se verificó una única identidad de serie en el catálogo INA.'}
    meta=selecion.iloc[0].to_dict()
    hoy=fecha_fuente(ahora()).date()
    url=CUENCA_INA_DATOS_ZC+urlencode({'seriesId':int(meta['serie_id']),
        'timeStart':str(hoy-timedelta(days=int(dias))),'timeEnd':str(hoy+timedelta(days=1)),'format':'json'})
    try:
        r=requests.get(url,headers={'User-Agent':'Alerta-Zarate-Campana/cuenca'},timeout=(4,12))
        r.raise_for_status()
        if not _cuenca_url_ina_zc(r.url):raise ValueError('Redirección fuera de INA.')
        payload=r.json()
        if not isinstance(payload,dict) or not isinstance(payload.get('responseHeader'),dict):raise ValueError('Respuesta sin cabecera de observaciones.')
        m=payload['responseHeader'].get('seriesmetadata',{})
        if not isinstance(m,dict) or not isinstance(payload.get('data'),list):raise ValueError('Metadatos/registros inválidos.')
        if str(m.get('seriesId'))!=str(meta['serie_id']) or str(m.get('unitId'))!=str(meta['unidad_id']):
            raise ValueError('Identidad/unidad de datos diferente del catálogo.')
        filas=[]
        for item in payload.get('data',[]):
            try:
                valor=float(item['valor']);t=pd.Timestamp(item['timestart'])
                if not np.isfinite(valor) or pd.isna(t) or (meta['variable']=='caudal' and valor<0):continue
                tiene_zona=t.tzinfo is not None
                t=t.tz_convert(TZ) if tiene_zona else t.tz_localize(TZ)
                filas.append({'fecha':t,'valor':valor,'zona_horaria_verificada':tiene_zona})
            except (ValueError,TypeError,KeyError,OverflowError):continue
        if not filas:raise ValueError('Serie sin fechas y números utilizables.')
        return {**base,**meta,'df':pd.DataFrame(filas).sort_values('fecha').drop_duplicates('fecha',keep='last'),
            'fuente':r.url,'dias':int(dias),'tipo_dato':'Observaciones INA; conservar hora y zona de cada registro',
            'advertencia':'Serie de una sección aguas arriba. No es una altura local ni aporta un tiempo fijo de llegada a Zárate–Campana.'}
    except (requests.RequestException,ValueError,TypeError,KeyError) as exc:
        return {**base,**meta,'fuente':url,'error':'Serie de cuenca no verificada: '+type(exc).__name__}

@st.cache_data(ttl=600,show_spinner=False)
def consultar_productos_cuenca_ina_zc():
    """Discover latest report/PDF URLs from the official index, without synthesizing dates."""
    consulta=ahora().isoformat()
    try:
        r=requests.get(CUENCA_INA_INDICE_ZC,headers={'User-Agent':'Alerta-Zarate-Campana/cuenca'},timeout=(4,10))
        r.raise_for_status()
        if not _cuenca_url_ina_zc(r.url):raise ValueError('Índice fuera de INA.')
        lectura=_cuenca_leer_html_zc(r.text)
        productos=[]
        tipos={'reporte diario':'diario','informe hidrometrico':'hidrometrico',
            'pronostico rio parana':'parana_7_14','informe semanal':'semanal','informe mensual':'mensual'}
        for href,etiqueta in lectura['enlaces']:
            normal=_cuenca_normalizar_zc(etiqueta)
            tipo=next((v for k,v in tipos.items() if normal.startswith(k)),None)
            url=urljoin(r.url,href)
            if tipo is None or not _cuenca_url_ina_zc(url):continue
            publicado=re.search(r'Actualizado al\s+(\d{2}-\d{2}-\d{4})',etiqueta,re.I)
            fecha=datetime.strptime(publicado[1],'%d-%m-%Y').date().isoformat() if publicado else None
            productos.append({'producto':tipo,'titulo':etiqueta,'url':url,
                'fecha_indicada_indice':fecha,'consulta':consulta,'fuente_indice':r.url})
        if not productos:raise ValueError('No se reconocieron vínculos del índice oficial.')
        return {'productos':productos,'consulta':consulta,'fuente':r.url,'error':'',
            'advertencia':'La fecha indicada por el índice pertenece al producto documental. El Paraná medio tiene horizontes de 7/14 o 4/11 días; el pronóstico local del Delta conserva su propio horizonte de 96 h.'}
    except (requests.RequestException,ValueError,TypeError,KeyError) as exc:
        return {'productos':[],'consulta':consulta,'fuente':CUENCA_INA_INDICE_ZC,
            'error':'No se verificaron las últimas publicaciones INA: '+type(exc).__name__}

@st.cache_data(ttl=600,show_spinner=False)
def consultar_disponibilidad_delta_15d_zc():
    """Check the published product availability; query time is never an emission."""
    consulta=ahora().isoformat()
    base={'url':CUENCA_INA_DELTA_15D_ZC,'fuente':CUENCA_INA_DELTA_15D_ZC,
        'fecha_consulta':consulta,'fecha_emision':None,'series':[],'error':'',
        'datos_extraidos':False,'permite_alarma_local':False}
    try:
        r=requests.get(CUENCA_INA_DELTA_15D_ZC,
            headers={'User-Agent':'Alerta-Zarate-Campana/cuenca'},timeout=(4,10))
        r.raise_for_status()
        if not _cuenca_url_ina_zc(r.url):raise ValueError('Producto Delta fuera del sitio INA.')
        lectura=_cuenca_leer_html_zc(r.text)
        if not lectura['texto'].strip():raise ValueError('Producto Delta sin contenido verificable.')
        fuera='TEMPORARIAMENTE FUERA DE SERVICIO' in lectura['texto'].upper()
        return {**base,'url':r.url,'fuente':r.url,
            'estado':'fuera_de_servicio' if fuera else 'disponibilidad_producto_por_verificar',
            'advertencia':'INA declara temporalmente fuera de servicio este producto.' if fuera else
                'Página recuperada; disponibilidad de la corrida, emisión, estaciones y series a 15 días todavía no verificadas. No se extrapola el producto local de 96 h.'}
    except (requests.RequestException,ValueError,TypeError,KeyError) as exc:
        return {**base,'estado':'sin_verificar','error':'No se verificó la disponibilidad del producto Delta a 15 días: '+type(exc).__name__}

# BEGIN BOLETINES ZC 1.5.2
def normalizar_boletin_cuenca_zc(boletin):
    """Completa metadatos de productos conocidos; no infiere pronósticos ni vigencia."""
    from urllib.parse import urlparse
    if not isinstance(boletin, dict):
        return {}
    b = dict(boletin)
    try:
        origen = urlparse(str(b.get('url') or b.get('fuente') or ''))
        es_ina = (origen.scheme == 'https' and
                  origen.hostname in {'ina.gob.ar', 'www.ina.gob.ar', 'alerta.ina.gob.ar'} and
                  not origen.username and not origen.password and origen.port in {None, 443})
    except ValueError:
        es_ina = False
    if not es_ina:
        return b
    if not str(b.get('organismo') or b.get('autoridad') or '').strip():
        b['organismo'] = 'Instituto Nacional del Agua (INA)'
    tipo = b.get('tipo')
    descripciones = {
        'diario': ('Reporte hidrometeorológico diario de la Cuenca del Plata. Las tablas recuperadas aportan niveles, caudales y condiciones publicadas; el análisis completo se consulta en el documento original.',
                   'Contexto regional fechado. La fecha del reporte no acredita la hora individual de las mediciones ni una alerta de evacuación en Zárate–Campana.'),
        'diario_pdf': ('PDF enlazado por el reporte diario recuperado. Los valores de esta consulta provienen de las tablas HTML asociadas; el PDF no fue leído automáticamente.',
                       'Mismo reporte documental fechado. No aporta una observación horaria local ni una fecha de llegada de la crecida.'),
        'hidrometrico': ('Informe hidrométrico enlazado por el índice oficial INA. Sus tablas y fechas deben revisarse en el PDF original; esta consulta no extrajo sus valores.',
                        'Actualización del producto indicada por el índice. Las fechas de sus observaciones pueden ser distintas; no se asigna vigencia horaria al documento.'),
        'parana_7_14': ('Pronóstico del río Paraná enlazado por INA para estaciones del Paraná medio. El índice confirma el enlace y su actualización; las cifras de este PDF no se extrajeron automáticamente.',
                       'El producto mantiene sus estaciones y horizontes originales. No se extiende el pronóstico local de Zárate–Campana de 96 horas ni se calcula la llegada de la onda.'),
        'semanal': ('Informe semanal de situación y perspectiva de la Cuenca del Plata enlazado por el índice oficial INA.',
                    'Contexto regional del período publicado. Emisión, estaciones y horizontes se revisan en el original; no se transforma en una alerta local automática.'),
        'mensual': ('Informe mensual de situación y perspectiva de la Cuenca del Plata enlazado por el índice oficial INA.',
                    'Contexto regional y estacional del período publicado. No determina una fecha de inundación ni una orden de evacuación local.'),
        'delta_15d': ('Página oficial del producto de pronóstico del Delta a 15 días. Se consulta su disponibilidad; no se recuperó una corrida con estaciones y series verificadas.',
                      'Sin emisión de corrida ni horizonte local verificados. La consulta de disponibilidad no habilita extender el pronóstico de 96 horas.'),
    }
    descripcion, alcance = descripciones.get(tipo, (
        'Producto documental enlazado desde una fuente INA. Revisá el contenido original.',
        'Área y período de validez del producto sin extracción automática confirmada.'))
    if not str(b.get('resumen') or b.get('descripcion') or '').strip():
        b['descripcion'] = descripcion
    if not str(b.get('alcance') or b.get('vigencia') or b.get('limites') or '').strip():
        b['alcance'] = alcance
    if not str(b.get('estado') or '').strip():
        b['estado'] = ('Tablas del reporte recuperadas; revisar su fecha' if b.get('datos_extraidos') is True
                       else 'Enlace identificado en el índice INA; contenido sin extracción automática')
    return b


def normalizar_boletines_cuenca_zc(cuenca):
    """Normaliza únicamente boletines; conserva fechas, registros y decisiones."""
    if not isinstance(cuenca, dict):
        return {}
    lista = cuenca.get('boletines')
    if not isinstance(lista, (list, tuple)):
        return dict(cuenca)
    return {**cuenca, 'boletines': [normalizar_boletin_cuenca_zc(b) for b in lista if isinstance(b, dict)]}


def fecha_boletin_cuenca_texto_zc(valor):
    """Una fecha documental sin hora no se convierte en medianoche ART."""
    from datetime import date, datetime
    import re
    if isinstance(valor, date) and not isinstance(valor, datetime):
        return valor.strftime('%d/%m/%Y') + ' · sin hora publicada'
    if isinstance(valor, str) and re.fullmatch(r'\d{4}-\d{2}-\d{2}', valor.strip()):
        try:
            return date.fromisoformat(valor.strip()).strftime('%d/%m/%Y') + ' · sin hora publicada'
        except ValueError:
            return 'Sin confirmar'
    return _cuenca_ui_fecha_texto(valor)

# END BOLETINES ZC 1.5.2

@st.cache_data(ttl=300,show_spinner=False)
def consultar_cuenca_parana_zc():
    """Normalize documentary and station source status for the basin UI/decision modules."""
    consulta=ahora().isoformat()
    # Independent sources run together; every getter returns a controlled failure.
    with ThreadPoolExecutor(max_workers=4) as pool:
        futuros={'ina_diario':pool.submit(consultar_reporte_cuenca_ina_zc),
                 'ina_indice':pool.submit(consultar_productos_cuenca_ina_zc),
                 'ina_delta_15d':pool.submit(consultar_disponibilidad_delta_15d_zc)}
        if callable(globals().get('_zc_eby_obtener_parte')):
            futuros['eby']=pool.submit(_zc_eby_obtener_parte)
        respuestas={}
        for nombre,futuro in futuros.items():
            try:respuestas[nombre]=futuro.result()
            except Exception as exc:respuestas[nombre]={'error':'Consulta no verificada: '+type(exc).__name__}
    diario=respuestas.get('ina_diario',{})
    indice=respuestas.get('ina_indice',{})
    delta_15d=respuestas.get('ina_delta_15d',{})
    eby=respuestas.get('eby',{'campos':[],'fecha_informe':None,'error':'Lector EBY no incorporado.'})
    registros=[]
    d=diario.get('df')
    if isinstance(d,pd.DataFrame) and not d.empty and not diario.get('error'):
        for fila in d.to_dict('records'):
            condicion=str(fila.get('perspectiva_publicada','')).strip()
            registros.append({**fila,'fecha_dato':None,'tipo_dato':'reporte_diario',
                'condicion_publicada':condicion,'alto_publicado':_cuenca_normalizar_zc(condicion)=='aguas altas',
                'tendencia_publicada':None,'url':fila.get('fuente',diario.get('fuente')),
                'fecha_consulta':fila.get('consulta',diario.get('consulta',consulta))})
    fecha_diario=diario.get('emision')
    fecha_diario=fecha_diario.isoformat() if hasattr(fecha_diario,'isoformat') else fecha_diario
    boletines=[]
    for p in indice.get('productos',[]):
        boletines.append({'tipo':p['producto'],'titulo':p['titulo'],'url':p['url'],
            'fecha_emision':p.get('fecha_indicada_indice'),'tipo_fecha':'Actualización indicada por el índice oficial INA; sin hora',
            'datos_extraidos':bool(p['producto']=='diario' and registros),'fecha_consulta':indice.get('consulta',consulta)})
    if diario.get('pdf_url'):
        boletines.append({'tipo':'diario_pdf','titulo':'PDF del reporte diario recuperado','url':diario['pdf_url'],
            'fecha_emision':fecha_diario,'tipo_fecha':'Fecha de actualización publicada en el reporte',
            'datos_extraidos':bool(registros),'fecha_consulta':diario.get('consulta',consulta)})
    boletines.append({'tipo':'delta_15d','titulo':'INA Delta · disponibilidad del producto a 15 días',
        'url':delta_15d.get('url',CUENCA_INA_DELTA_15D_ZC),'fecha_emision':None,
        'tipo_fecha':'Emisión de corrida no verificada; consulta no equivale a emisión',
        'datos_extraidos':False,'fecha_consulta':delta_15d.get('fecha_consulta',consulta),
        'estado':delta_15d.get('estado','sin_verificar'),
        'documento_recuperado':delta_15d.get('estado') in {'fuera_de_servicio','disponibilidad_producto_por_verificar'},
        'tipo_registro':'Acceso a producto; no acredita una corrida ni datos de pronóstico'})
    publicaciones=[b['fecha_emision'] for b in boletines if b.get('fecha_emision')]
    ultima=max(publicaciones) if publicaciones else None
    incertidumbres=['Las tablas del parte diario no publican la hora individual de cada observación.',
        'Caudales y niveles de secciones sucesivas describen el tránsito de la misma onda: no se suman.',
        'No se calcula un tiempo fijo de llegada ni se convierte caudal aguas arriba a altura local.',
        'Paraná medio: horizontes de 7/14 días y tendencias de 4/11 días, distintos del pronóstico local INA del Delta de 96 h.',
        'El Uruguay aporta al estuario por otra rama; su caudal no se agrega al Paraná de las Palmas aguas arriba de Zárate–Campana.',
        'Umbrales de otras estaciones y cota mSNM del embalse no equivalen a la escala de Zárate o Campana.',
        'Itaipú: boletín oficial enlazado en su web; API pública actual no verificada en esta revisión.']
    if fecha_diario and ultima and ultima>fecha_diario:
        incertidumbres.insert(0,f'El índice INA tiene una publicación de {ultima}, más nueva que los registros del parte {fecha_diario}; no se presentan estos valores anteriores como observaciones de hoy.')
    for nombre,r in respuestas.items():
        if r.get('error'):incertidumbres.append(nombre+': '+str(r['error']))
    if delta_15d.get('advertencia'):incertidumbres.append(delta_15d['advertencia'])
    for texto in eby.get('limitaciones',[]):
        if texto not in incertidumbres:incertidumbres.append(texto)
    url_topologia=CUENCA_INA_DIARIO_ZC
    conexiones=[{'origen':a,'destino':b,'tipo':tipo,'url':url_topologia,'verificada':True}
        for a,b,tipo in [('Alto Paraná / Itaipú','Confluencia Paraná–Iguazú','Cauce y aportes aguas arriba'),
            ('Iguazú / Andresito','Confluencia Paraná–Iguazú','Tributario'),
            ('Confluencia Paraná–Iguazú','Yacyretá','Tramo regulado y aportes en ruta'),
            ('Yacyretá','Paraná medio / Corrientes–La Paz','Tránsito aguas abajo y aportes laterales'),
            ('Paraguay','Paraná medio / Corrientes–La Paz','Tributario; requiere serie propia'),
            ('Paraná medio / Corrientes–La Paz','Santa Fe / Paraná–Rosario','Tránsito aguas abajo'),
            ('Santa Fe / Paraná–Rosario','Delta / Zárate–Campana','Distribución por brazos y aportes locales'),
            ('Uruguay','Estuario del Río de la Plata','Rama separada al estuario'),
            ('Estuario del Río de la Plata','Delta / Zárate–Campana','Condición aguas abajo: marea/viento, no caudal sumable')]]
    for conexion in conexiones:
        if conexion['origen']=='Uruguay':
            conexion['url']='https://www.argentina.gob.ar/prefecturanaval/buque-cientifico-spa-1-dr-luis-federico-leloir/principales-campanas'
        elif conexion['origen']=='Paraguay':
            conexion['url']='https://repositorio.ina.gob.ar/bitstreams/61904658-13af-4437-b688-8fde944566fe/download'
    fuentes=[{'organismo':'INA','url':CUENCA_INA_DIARIO_ZC,'fecha_consulta':diario.get('consulta',consulta),
        'estado_consulta':'verificado' if registros else 'sin_verificar'},
        {'organismo':'INA','url':CUENCA_INA_INDICE_ZC,'fecha_consulta':indice.get('consulta',consulta),
        'estado_consulta':'verificado' if indice.get('productos') else 'sin_verificar'},
        {'organismo':'EBY','url':eby.get('url','https://eby.gov.py/category/nivelembalse/'),
        'fecha_consulta':eby.get('consulta',consulta),'estado_consulta':'verificado' if eby.get('campos') and not eby.get('error') else 'sin_verificar'}]
    fuentes.append({'organismo':'INA','url':delta_15d.get('url',CUENCA_INA_DELTA_15D_ZC),
        'fecha_consulta':delta_15d.get('fecha_consulta',consulta),
        'estado_consulta':delta_15d.get('estado','sin_verificar')})
    valido_eby=bool(eby.get('campos') and not eby.get('error'))
    valido_indice=bool(indice.get('productos'))
    estado='verificado' if registros and valido_eby and valido_indice else 'parcial' if registros or valido_eby or valido_indice else 'sin_verificar'
    return normalizar_boletines_cuenca_zc({'estado':estado,'fecha_emision':fecha_diario,'fecha_consulta':consulta,'registros':registros,
        'boletines':boletines,'conexiones':conexiones,'incertidumbres':incertidumbres,'fuentes':fuentes,
        'eby':eby,'ultima_publicacion_indice':ultima,'permite_alarma_local':False,
        'delta_15d':delta_15d,
        'estado_fuentes':{k:v.get('estado','sin_verificar' if v.get('error') else 'verificado') for k,v in respuestas.items()},
        'error':'' if estado!='sin_verificar' else 'No se recuperaron fuentes de cuenca verificables.'})

# cuenca_decision_zc.py
def construir_decision_cuenca_zc(modelo_local, prevencion_local, cuenca, referencia=None):
    """Preserve local evidence and qualify daily INA basin context independently.

    Receiver policy: a daily report is documentary context for its ART calendar
    day or the previous day; an aware retrieval stamp must be no older than24h.
    Five minutes of clock tolerance does not create an individual observation.
    Only normalized priorities are consumed; labels and CAP instructions are
    never used to create an evacuation order or a local arrival/height forecast.
    """
    import math
    import numbers
    import re
    import unicodedata
    from datetime import date, datetime, timedelta, timezone
    from urllib.parse import urlparse
    from zoneinfo import ZoneInfo

    tz = ZoneInfo('America/Argentina/Buenos_Aires')
    modelo = modelo_local if isinstance(modelo_local, dict) else {}
    prevencion = prevencion_local if isinstance(prevencion_local, dict) else {}
    datos = cuenca if isinstance(cuenca, dict) else {}
    motivos, incertidumbres, cobertura = [], [], []

    def normal(valor):
        valor = valor if isinstance(valor, str) else ''
        return re.sub(r'\s+', ' ', ''.join(c for c in unicodedata.normalize('NFKD', valor)
                      if not unicodedata.combining(c))).strip().casefold()

    def verdadero(valor):
        return type(valor).__name__ in ('bool', 'bool_') and bool(valor)

    def numero(valor):
        if type(valor).__name__ in ('bool', 'bool_') or not isinstance(valor, numbers.Real):
            return None
        return float(valor) if math.isfinite(float(valor)) else None

    def prioridad(valor):
        valor = numero(valor)
        return int(valor) if valor in (0, 1, 2) else None

    def fecha(valor):
        try:
            if isinstance(valor, str):
                valor = datetime.fromisoformat(valor.replace('Z', '+00:00'))
            if not isinstance(valor, datetime) or valor.tzinfo is None or valor.utcoffset() is None:
                return None
            return valor.astimezone(tz)
        except (ValueError, TypeError, OverflowError):
            return None

    def dia(valor):
        # Calendar precision remains calendar precision; never synthesize midnight.
        if isinstance(valor, date) and not isinstance(valor, datetime):
            return valor
        if isinstance(valor, str) and re.fullmatch(r'\d{4}-\d{2}-\d{2}', valor):
            try:
                return date.fromisoformat(valor)
            except ValueError:
                return None
        return None

    def host(valor):
        try:
            parsed = urlparse(valor if isinstance(valor, str) else '')
            return parsed.hostname if parsed.scheme == 'https' else None
        except ValueError:
            return None

    ina_hosts = {'ina.gob.ar', 'www.ina.gob.ar', 'alerta.ina.gob.ar', 'repositorio.ina.gob.ar'}

    def recoger(objeto, ruta, claves=('incertidumbres', 'limites', 'limitaciones')):
        if isinstance(objeto, dict):
            for clave, valor in objeto.items():
                # These are outputs injected by the caller, not fresh evidence.
                if clave in ('decision_integrada', 'cuenca', 'estado_general'):
                    continue
                if clave in claves:
                    valores = valor if isinstance(valor, (list, tuple)) else [valor]
                    for item in valores:
                        if isinstance(item, str) and item.strip():
                            incertidumbres.append(ruta + ': ' + item.strip())
                elif clave == 'error' and isinstance(valor, str) and valor.strip():
                    incertidumbres.append(ruta + ': ' + valor.strip())
                else:
                    recoger(valor, ruta + '.' + str(clave), claves)
        elif isinstance(objeto, (list, tuple)):
            for i, valor in enumerate(objeto):
                recoger(valor, ruta + '[' + str(i) + ']', claves)

    recoger(modelo, 'Modelo local')
    recoger(prevencion, 'Prevención local')
    recoger(datos, 'Cuenca')
    ref = fecha(referencia) if referencia is not None else datetime.now(timezone.utc).astimezone(tz)
    if ref is None:
        incertidumbres.append('Hora de evaluación sin zona horaria verificable; cuenca sin confirmar.')

    prio_local = prioridad(prevencion.get('prioridad'))
    alto_actual = prio_local == 2
    if prevencion.get('prioridad') is not None and prio_local is None:
        incertidumbres.append('Prioridad de prevención local no numérica o no válida.')
    for item in prevencion.get('motivos', []) if isinstance(prevencion.get('motivos'), (list, tuple)) else []:
        if isinstance(item, str) and item.strip():
            motivos.append('Prevención local: ' + item.strip())
    alertas = modelo.get('alertas', [])
    if not isinstance(alertas, (list, tuple)):
        alertas = []
        incertidumbres.append('Señales del modelo local sin formato confirmado.')
    for alerta in alertas:
        if not isinstance(alerta, dict):
            continue
        p = prioridad(alerta.get('prioridad'))
        if p is None:
            incertidumbres.append('Prioridad de una señal del modelo local sin confirmar.')
            continue
        prio_local = max(prio_local if prio_local is not None else 0, p)
        if p == 2 and alerta.get('id_horizonte') == 'corto':
            alto_actual = True
        if p and alerta.get('id_horizonte') not in ('corto', 'medio', 'largo'):
            incertidumbres.append('Horizonte de una señal local sin confirmar; no se considera inmediata.')
        for item in alerta.get('motivos', []) if isinstance(alerta.get('motivos'), (list, tuple)) else []:
            if isinstance(item, str) and item.strip():
                motivos.append('Modelo local · ' + str(alerta.get('localidad') or 'sector')
                               + ' · ' + str(alerta.get('horizonte') or alerta.get('id_horizonte') or 'plazo por confirmar')
                               + ': ' + item.strip())
    if not modelo:
        incertidumbres.append('Modelo local no disponible.')
    atmosfera = modelo.get('atmosfera', [])
    if modelo and (not isinstance(atmosfera, (list, tuple)) or not atmosfera):
        incertidumbres.append('Cobertura atmosférica del modelo local no declarada.')
    elif isinstance(atmosfera, (list, tuple)):
        for a in atmosfera:
            if not isinstance(a, dict) or not verdadero(a.get('completo')):
                lugar = str(a.get('localidad') or 'Punto local') if isinstance(a, dict) else 'Punto local'
                plazo = str(a.get('horizonte') or a.get('id') or 'plazo sin confirmar') if isinstance(a, dict) else 'plazo sin confirmar'
                incertidumbres.append(lugar + ' · ' + plazo + ': cobertura atmosférica incompleta.')
    if not prevencion or prioridad(prevencion.get('prioridad')) is None:
        incertidumbres.append('Cobertura de la vigilancia local sin confirmar.')
    cobertura.extend([
        {'fuente': 'Modelo local', 'estado': 'Disponible con sus límites' if modelo else 'Sin verificar',
         'fecha_referencia': modelo.get('emision'), 'fecha_consulta': None,
         'alcance': 'Fecha de evaluación; las fechas de las fuentes no se sustituyen por ella.'},
        {'fuente': 'Vigilancia local', 'estado': 'Señal preventiva disponible' if prio_local else
            'Verificación pendiente' if prioridad(prevencion.get('prioridad')) is None else 'Mantener vigilancia',
         'fecha_referencia': prevencion.get('referencia'), 'fecha_consulta': None,
         'alcance': 'Meteorología, río observado, avisos, SHN y partes conservan sus incertidumbres.'}])

    emision = dia(datos.get('fecha_emision'))
    consulta = fecha(datos.get('fecha_consulta'))

    def consulta_vigente(valor):
        return ref is not None and valor is not None and -300 <= (ref-valor).total_seconds() <= 86400

    informe_actual = (ref is not None and emision is not None and 0 <= (ref.date()-emision).days <= 1
                      and consulta_vigente(consulta) and datos.get('estado') in ('verificado', 'parcial')
                      and not datos.get('error'))
    if not informe_actual:
        incertidumbres.append('Reporte diario INA sin fecha, consulta reciente o publicación de hoy/ayer confirmada.')
    if datos.get('estado') == 'parcial':
        incertidumbres.append('Fuentes de cuenca parcialmente disponibles; no confirman ausencia de señales.')
    cobertura.append({'fuente': 'INA · reporte diario de cuenca',
        'estado': 'Documento diario reciente · contexto' if informe_actual else 'Verificación pendiente',
        'fecha_referencia': datos.get('fecha_emision'), 'fecha_consulta': datos.get('fecha_consulta'),
        'alcance': 'Fecha del documento, no hora individual ni altura actual en Zárate–Campana.'})

    conexiones = datos.get('conexiones', [])
    conexiones = conexiones if isinstance(conexiones, (list, tuple)) else []

    def conectado(rio):
        rio = re.sub(r'^rio\s+', '', normal(rio))
        if rio in ('parana', 'alto parana', 'parana medio', 'parana inferior'):
            return True
        if rio not in ('iguazu', 'paraguay'):
            return False
        return any(isinstance(c, dict) and verdadero(c.get('verificada')) and host(c.get('url')) in ina_hosts
                   and re.search(r'\b' + rio + r'\b', normal(c.get('origen')))
                   and re.search(r'\bparana\b', normal(c.get('destino'))) for c in conexiones)

    registros = datos.get('registros', [])
    if not isinstance(registros, (list, tuple)) or not registros:
        registros = []
        incertidumbres.append('Sin registros del reporte diario de cuenca verificables.')
    validos, senales, vistos = 0, [], set()
    for r in registros:
        if not isinstance(r, dict):
            continue
        nombre = str(r.get('estacion') or r.get('nombre_publicado') or 'Estación sin identidad')
        valor = numero(r.get('valor'))
        unidad_valida = ((r.get('variable') == 'caudal' and r.get('unidad') in ('m³/s', 'm3/s')
                          and valor is not None and valor >= 0)
                         or (r.get('variable') == 'nivel' and r.get('unidad') == 'm' and valor is not None))
        fecha_reg = dia(r.get('fecha_documento'))
        valido = (informe_actual and unidad_valida and r.get('tipo_dato') == 'reporte_diario'
                  and fecha_reg == emision and consulta_vigente(fecha(r.get('fecha_consulta')))
                  and host(r.get('url')) in ina_hosts and conectado(r.get('rio')))
        if not valido:
            incertidumbres.append(nombre + ': identidad, conectividad, unidades o fecha documental sin confirmar.')
            continue
        # Identity/set membership prevents voting; values are never added.
        clave = (nombre, str(r.get('serie_id')), r.get('variable'), r.get('unidad'),
                 str(r.get('fecha_documento')), valor, normal(r.get('condicion_publicada')),
                 normal(r.get('tendencia_publicada')))
        if clave in vistos:
            continue
        vistos.add(clave)
        validos += 1
        alto = verdadero(r.get('alto_publicado')) and normal(r.get('condicion_publicada')) == 'aguas altas'
        ascenso = normal(r.get('tendencia_publicada')) in ('ascenso', 'en ascenso', 'ascendente', 'crece', 'creciente')
        if alto or ascenso:
            senales.append(nombre + ': ' + ('aguas altas' if alto else 'tendencia ascendente')
                           + ' publicadas en el reporte INA del ' + str(r.get('fecha_documento')) + '.')
    if registros and not validos:
        incertidumbres.append('Ningún registro conectado y fechado del reporte permite clasificar la vigilancia de cuenca.')
    for fuente in datos.get('fuentes', []) if isinstance(datos.get('fuentes'), (list, tuple)) else []:
        if not isinstance(fuente, dict):
            continue
        organismo = str(fuente.get('organismo') or 'Fuente documental')
        verificada = fuente.get('estado_consulta') == 'verificado' and consulta_vigente(fecha(fuente.get('fecha_consulta')))
        estado_producto = fuente.get('estado_consulta')
        estado_cobertura = ('Producto temporalmente fuera de servicio' if estado_producto == 'fuera_de_servicio'
                           else 'Acceso documental; datos del producto por verificar'
                           if estado_producto == 'disponibilidad_producto_por_verificar'
                           else 'Consulta documental disponible' if verificada else 'Consulta sin verificar')
        cobertura.append({'fuente': organismo + ' · ' + str(fuente.get('url') or 'origen por confirmar'),
            'estado': estado_cobertura,
            'fecha_referencia': None, 'fecha_consulta': fuente.get('fecha_consulta'),
            'alcance': 'Disponibilidad documental; no equivale a observación instantánea ni modelo de propagación.'})
        if not verificada:
            incertidumbres.append(organismo + ': disponibilidad documental sin verificar.')
    motivos.extend(sorted(set(senales)))
    if senales:
        motivos.append('La señal de cuenca refuerza la vigilancia; no determina cuándo llegará una crecida ni su altura local.')
    if alto_actual:
        nivel, p = 'ALERTA PREVENTIVA LOCAL · PREPARAR POSIBLE EVACUACIÓN', 2
        motivos.append('Preparación ante evidencia local: corroborar sectores, accesos y asistencia con la autoridad. No es una orden de evacuación.')
    elif prio_local in (1, 2):
        nivel, p = 'PREPARACIÓN PREVENTIVA LOCAL', prio_local
    elif senales:
        nivel, p = 'VIGILANCIA REFORZADA DE CUENCA', 1
    elif incertidumbres:
        nivel, p = 'VERIFICACIÓN PENDIENTE', None
    else:
        nivel, p = 'MANTENER VIGILANCIA', 0
    return {'nivel_preparacion': nivel, 'prioridad': p, 'cobertura_por_fuente': cobertura,
            'motivos': list(dict.fromkeys(motivos)), 'incertidumbres': list(dict.fromkeys(incertidumbres)),
            'llegada_local': None, 'nivel_local_pronosticado': None, 'instruccion_oficial_local': None}

# cuenca_ui_zc.py
import json

from datetime import datetime

from urllib.parse import urlparse

from zoneinfo import ZoneInfo

CUENCA_UI_FUENTES_PREPARACION = [
    {'nombre': 'SINAGIR · qué hacer durante una inundación',
     'url': 'https://www.argentina.gob.ar/sinagir/riesgos-frecuentes/inundacion/que-hacer'},
    {'nombre': 'SINAGIR · kit de emergencia',
     'url': 'https://www.argentina.gob.ar/sinagir/kit-de-emergencias'},
]

CUENCA_UI_ETAPAS = [
    {'Etapa': '1 · Vigilancia', 'Qué permite': 'Seguir fechas, tendencias y boletines de cuenca; contrastarlos con lluvia, río y partes locales.',
     'Qué falta confirmar': 'Una señal aguas arriba no determina por sí sola impacto ni hora de llegada a Zárate–Campana.'},
    {'Etapa': '2 · Preparación', 'Qué permite': 'Preparar documentación y medicación; informar necesidades de asistencia; confirmar medios, accesos y destino con la coordinación local.',
     'Qué falta confirmar': 'La app no certifica caminos abiertos, navegación, recursos disponibles ni una orden de salida.'},
    {'Etapa': '3 · Orden oficial local', 'Qué permite': 'Seguir las instrucciones de la autoridad para el ámbito indicado en una disposición vigente verificada.',
     'Qué falta confirmar': 'Autoridad, publicación, URL original, ámbito, vigencia y revisión de cancelaciones o reemplazos.'},
]

def _cuenca_ui_filas(valor):
    if isinstance(valor, pd.DataFrame):
        return valor.to_dict('records')
    if isinstance(valor, (list, tuple)):
        return [v for v in valor if isinstance(v, dict)]
    return []

def _cuenca_ui_texto(valor, falta='Sin confirmar'):
    if valor is None:
        return falta
    if valor is pd.NA or valor is pd.NaT:
        return falta
    if isinstance(valor, (float, np.floating)) and not np.isfinite(valor):
        return falta
    if isinstance(valor, (list, tuple)):
        return '; '.join(_cuenca_ui_texto(v, '') for v in valor if _cuenca_ui_texto(v, '')) or falta
    texto = str(valor).strip()
    return texto if texto and texto.lower() not in ('nan', 'nat', 'none') else falta

def _cuenca_ui_campo(fila, *nombres, defecto=None):
    for nombre in nombres:
        valor = fila.get(nombre)
        if valor is not None and _cuenca_ui_texto(valor, ''):
            return valor
    return defecto

def _cuenca_ui_url(valor):
    try:
        u = urlparse(str(valor or ''))
        return str(valor) if u.scheme in ('http', 'https') and u.hostname and not u.username and not u.password else ''
    except ValueError:
        return ''

def _cuenca_ui_fecha(valor):
    try:
        f = pd.Timestamp(valor)
        if pd.isna(f) or f.tzinfo is None:
            return None
        return f.tz_convert('America/Argentina/Buenos_Aires')
    except (ValueError, TypeError, OverflowError):
        return None

def _cuenca_ui_fecha_texto(valor):
    f = _cuenca_ui_fecha(valor)
    if f is not None:
        return f.strftime('%d/%m/%Y %H:%M ART')
    if isinstance(valor, str) and len(valor) == 10:
        try:
            return datetime.strptime(valor, '%Y-%m-%d').strftime('%d/%m/%Y') + ' · fecha documental, sin hora'
        except ValueError:
            pass
    return _cuenca_ui_texto(valor, 'Sin fecha y zona confirmadas') + (' · zona por confirmar' if valor is not None and _cuenca_ui_texto(valor, '') else '')

def _cuenca_ui_numero(valor):
    if isinstance(valor, (bool, np.bool_)):
        return None
    try:
        f = float(valor)
        return f if np.isfinite(f) else None
    except (ValueError, TypeError, OverflowError):
        return None

def _cuenca_ui_orden_validada(orden, referencia=None):
    if not isinstance(orden, dict) or not orden:
        return {'vigente': False, 'faltantes': ['Esta consulta no confirma una orden oficial local vigente.']}
    ahora_local = _cuenca_ui_fecha(referencia or datetime.now(ZoneInfo('America/Argentina/Buenos_Aires')))
    url = _cuenca_ui_url(_cuenca_ui_campo(orden, 'url', 'fuente_url', 'fuente'))
    host = urlparse(url).hostname or ''
    fuente_oficial = bool(host.endswith('.gob.ar') or host.endswith('.gov.ar'))
    publicada = _cuenca_ui_fecha(_cuenca_ui_campo(orden, 'publicada', 'fecha_publicacion'))
    desde = _cuenca_ui_fecha(_cuenca_ui_campo(orden, 'vigente_desde', 'inicio', defecto=publicada))
    hasta = _cuenca_ui_fecha(_cuenca_ui_campo(orden, 'valida_hasta', 'vigente_hasta', 'valido_hasta'))
    revisada = _cuenca_ui_fecha(_cuenca_ui_campo(orden, 'fecha_verificacion', 'fecha_consulta', 'consulta'))
    limite_h = _cuenca_ui_numero(orden.get('max_antiguedad_verificacion_h'))
    estado = _cuenca_ui_texto(orden.get('estado'), '').lower()
    tipo = _cuenca_ui_texto(_cuenca_ui_campo(orden, 'tipo_disposicion', 'tipo'), '').lower().replace(' ', '_')
    autoridad = _cuenca_ui_campo(orden, 'autoridad', 'autoridad_emisora')
    ambito = _cuenca_ui_campo(orden, 'ambito', 'ambito_textual', 'sectores')
    faltantes = []
    if tipo not in ('orden_evacuacion', 'orden_de_evacuacion') or estado != 'vigente':
        faltantes.append('No se confirmó que el documento sea una orden de evacuación vigente.')
    if orden.get('verificada') is not True:
        faltantes.append('Documento y autoridad sin corroboración confirmada.')
    if orden.get('aplicacion_local_confirmada') is not True or not ambito:
        faltantes.append('Aplicación a los sectores locales sin confirmar.')
    if not autoridad or not url or not fuente_oficial:
        faltantes.append('Falta autoridad o enlace original de un dominio oficial.')
    if publicada is None or desde is None or hasta is None or ahora_local is None:
        faltantes.append('Publicación o intervalo de validez sin fecha y zona horaria confirmadas.')
    elif not publicada <= ahora_local or not desde <= ahora_local <= hasta:
        faltantes.append('La disposición es futura, vencida o está fuera de su intervalo de validez.')
    if estado in ('cancelada', 'revocada', 'reemplazada', 'vencida') or orden.get('cancelada') is True:
        faltantes.append('La disposición figura cancelada, revocada, reemplazada o vencida.')
    if orden.get('cancelaciones_revisadas') is not True:
        faltantes.append('No se confirmó la revisión de cancelaciones y reemplazos.')
    if revisada is None or limite_h is None or limite_h <= 0 or ahora_local is None:
        faltantes.append('Falta una revisión fechada y su límite explícito de antigüedad.')
    elif not 0 <= (ahora_local - revisada).total_seconds() / 3600 <= limite_h:
        faltantes.append('La revisión de la fuente está atrasada o tiene una fecha futura.')
    elif publicada is not None and revisada < publicada:
        faltantes.append('La revisión declarada es anterior a la publicación del documento.')
    return {'vigente': not faltantes, 'faltantes': faltantes, 'url': url, 'publicada': publicada,
            'desde': desde, 'hasta': hasta, 'revisada': revisada, 'max_antiguedad_verificacion_h': limite_h}

def _cuenca_ui_json(valor):
    if valor is pd.NA or valor is pd.NaT:
        return None
    if isinstance(valor, pd.DataFrame):
        return _cuenca_ui_json(valor.to_dict('records'))
    if isinstance(valor, dict):
        return {str(k): _cuenca_ui_json(v) for k, v in valor.items()}
    if isinstance(valor, (list, tuple)):
        return [_cuenca_ui_json(v) for v in valor]
    if isinstance(valor, (bool, np.bool_)):
        return bool(valor)
    if isinstance(valor, (float, np.floating)):
        return float(valor) if np.isfinite(valor) else None
    if isinstance(valor, np.integer):
        return int(valor)
    if isinstance(valor, (datetime, pd.Timestamp)):
        return valor.isoformat() if not pd.isna(valor) else None
    return valor

def mostrar_decision_cuenca_zc(decision, referencia=None, key_prefix='zc_cuenca_'):
    decision = decision if isinstance(decision, dict) else {}
    orden_recibida = decision.get('instruccion_oficial_local') or decision.get('orden_oficial') or decision.get('orden') or {}
    orden = orden_recibida if isinstance(orden_recibida, dict) else {}
    validacion = _cuenca_ui_orden_validada(orden, referencia)
    nivel = _cuenca_ui_texto(_cuenca_ui_campo(decision, 'nivel_preparacion', 'nivel'), 'Vigilancia · datos por completar')
    preparar = any(p in nivel.upper() for p in ('PREPAR', 'ATENCI', 'ALERTA'))
    salida_no_confirmada = any(p in nivel.upper() for p in ('EVAC', 'SALIDA')) and not preparar
    st.subheader('Zárate–Campana · vigilancia, preparación y disposición oficial')
    if validacion['vigente']:
        st.error('**Orden oficial local vigente verificada** · ' + _cuenca_ui_texto(orden.get('titulo'), 'Revisá la disposición original'))
        st.write('Autoridad: **' + _cuenca_ui_texto(_cuenca_ui_campo(orden, 'autoridad', 'autoridad_emisora')) + '**')
        st.write('Ámbito: **' + _cuenca_ui_texto(_cuenca_ui_campo(orden, 'ambito', 'ambito_textual', 'sectores')) + '**')
        st.caption('Publicación: ' + _cuenca_ui_fecha_texto(validacion['publicada']) + ' · Validez: ' +
                   _cuenca_ui_fecha_texto(validacion['desde']) + ' a ' + _cuenca_ui_fecha_texto(validacion['hasta']))
        st.caption('Fuente revisada: ' + _cuenca_ui_fecha_texto(validacion['revisada']) +
                   f' · control de consulta declarado: hasta {validacion["max_antiguedad_verificacion_h"]:g} h; distinto de la validez oficial.')
        st.link_button('Leer la orden oficial original', validacion['url'], key=key_prefix + 'orden_original')
        st.write('Seguí las instrucciones de la autoridad para los sectores indicados. Confirmá el medio, destino y acceso con la coordinación local; la app no define una ruta de evacuación.')
    else:
        titulo = 'Preparación · disposición de salida sin confirmar' if salida_no_confirmada else nivel
        (st.warning if preparar or salida_no_confirmada or _cuenca_ui_numero(decision.get('prioridad')) in (1, 2) else st.info)('**' + titulo + '**')
        st.caption('Esta consulta no confirma una orden oficial local vigente. Una señal del modelo o de una estación aguas arriba no es una orden de evacuación.')
        if orden:
            with st.expander('Disposición recibida · verificación pendiente', expanded=True):
                st.write('Autoridad declarada: ' + _cuenca_ui_texto(_cuenca_ui_campo(orden, 'autoridad', 'autoridad_emisora')))
                st.write('Ámbito declarado: ' + _cuenca_ui_texto(_cuenca_ui_campo(orden, 'ambito', 'ambito_textual', 'sectores')))
                for falta in validacion['faltantes']:
                    st.write('• ' + falta)
                if validacion.get('url'):
                    st.link_button('Revisar documento recibido', validacion['url'], key=key_prefix + 'orden_por_verificar')
    for motivo in decision.get('motivos') or []:
        st.write('• ' + _cuenca_ui_texto(motivo))
    for incertidumbre in decision.get('incertidumbres') or []:
        st.caption('Por verificar: ' + _cuenca_ui_texto(incertidumbre))
    cobertura = _cuenca_ui_filas(decision.get('cobertura_por_fuente'))
    if cobertura:
        st.dataframe(pd.DataFrame([{'Fuente': c.get('fuente'), 'Estado': c.get('estado'),
                     'Referencia': _cuenca_ui_fecha_texto(c.get('fecha_referencia')),
                     'Consulta': _cuenca_ui_fecha_texto(c.get('fecha_consulta')), 'Alcance': c.get('alcance')}
                     for c in cobertura]), hide_index=True, use_container_width=True)
    st.caption('Llegada de la crecida a Zárate–Campana: no estimada. Nivel local derivado de aguas arriba: no estimado. La propagación requiere un modelo hidrodinámico verificado y condiciones locales; estos registros no lo reemplazan.')
    st.dataframe(pd.DataFrame(CUENCA_UI_ETAPAS), hide_index=True, use_container_width=True)
    st.write('Prepará documentos, medicación y una mochila de emergencia. Informá a la coordinación local si alguien necesita ayuda para salir. Si el agua impide moverse con seguridad, solicitá asistencia; evitá caminar, nadar o conducir por agua y mantenete lejos de cables.')
    st.caption('Si recibís una indicación directa de la autoridad local, seguí sus instrucciones. No esperes a que esta app confirme su publicación. Recursos, accesos y contactos: Territorio y accesos; preparación completa: Modelo de inundaciones.')
    for i, fuente in enumerate(CUENCA_UI_FUENTES_PREPARACION):
        st.link_button(fuente['nombre'], fuente['url'], key=key_prefix + 'preparacion_fuente_' + str(i))

def mostrar_eby_cuenca_zc(eby, key_prefix='zc_cuenca_'):
    eby = eby if isinstance(eby, dict) else {}
    st.subheader('Yacyretá · parte operativo publicado por EBY')
    st.caption('Fecha del informe: ' + _cuenca_ui_fecha_texto(eby.get('fecha_informe')) +
               ' · Publicación web: ' + _cuenca_ui_fecha_texto(eby.get('emision')) +
               ' · Consulta: ' + _cuenca_ui_fecha_texto(eby.get('consulta')))
    campos = _cuenca_ui_filas(eby.get('campos'))
    nombres = {'nivel_embalse_hoy': 'Nivel del embalse · hoy', 'nivel_embalse_ayer': 'Nivel del embalse · ayer',
               'caudal_afluente_hoy': 'Caudal afluente previsto · hoy', 'caudal_afluente_manana': 'Caudal afluente previsto · mañana',
               'caudal_vertido_brazo_principal': 'Vertido · brazo principal', 'caudal_vertido_ana_cua': 'Vertido · Aña Cuá'}
    if campos:
        st.dataframe(pd.DataFrame([{'Variable': nombres.get(c.get('variable'), _cuenca_ui_texto(c.get('variable'))),
                                   'Valor': _cuenca_ui_numero(c.get('valor')), 'Unidad': c.get('unidad'),
                                   'Carácter publicado': c.get('tipo'), 'Día informado': _cuenca_ui_fecha_texto(c.get('fecha')),
                                   'Hora literal': _cuenca_ui_texto(c.get('hora'), 'No publicada'),
                                   'Zona horaria de la lectura': 'Confirmada' if c.get('zona_horaria_verificada') is True else 'No confirmada',
                                   'Alcance': c.get('detalle')} for c in campos]), hide_index=True, use_container_width=True)
    else:
        st.warning('Esta consulta no obtuvo un parte operativo EBY con campos verificables. La falta de datos no significa que la represa no aporte agua.')
    st.caption('La afluencia prevista, el nivel del embalse y los vertidos publicados son magnitudes diferentes. Los vertidos por brazos no son la descarga total: el caudal turbinado y el efluente total no están obtenidos en esta consulta. No se suman ni se convierten en un pronóstico para Zárate–Campana.')
    for limite in eby.get('limitaciones') or []:
        st.caption(_cuenca_ui_texto(limite))
    url = _cuenca_ui_url(eby.get('url') or eby.get('indice'))
    if url:
        st.link_button('Leer parte operativo original EBY', url, key=key_prefix + 'eby_original')

def mostrar_cuenca_parana_zc(resultado, key_prefix='zc_cuenca_'):
    resultado = resultado if isinstance(resultado, dict) else {}
    cuenca = resultado.get('cuenca') if isinstance(resultado.get('cuenca'), dict) else {}
    referencia = datetime.now(ZoneInfo('America/Argentina/Buenos_Aires'))
    st.header('Cuenca del Paraná · aportes aguas arriba y respuesta local')
    st.caption('Síntesis calculada: ' + _cuenca_ui_fecha_texto(resultado.get('emision')) + '. Las fechas de cada observación, pronóstico y boletín se muestran por separado.')
    st.write('Las estaciones aguas arriba permiten seguir la evolución de la cuenca. Su señal no activa por sí sola una alerta de inundación en Zárate–Campana ni determina cuándo llegará una crecida. Se necesita contrastarla con los pronósticos, niveles y condiciones locales.')
    mostrar_decision_cuenca_zc(resultado.get('decision'), referencia, key_prefix)

    estaciones = _cuenca_ui_filas(cuenca.get('estaciones'))
    registros = _cuenca_ui_filas(cuenca.get('registros'))
    if not estaciones:
        estaciones = registros
    boletines = _cuenca_ui_filas(cuenca.get('boletines'))
    a, b, c = st.columns(3)
    a.metric('Referencias incluidas', len({_cuenca_ui_texto(_cuenca_ui_campo(e, 'nombre', 'estacion_nombre', 'estacion')) for e in estaciones}))
    b.metric('Registros recibidos', len(registros))
    c.metric('Productos documentales listados', len(boletines))
    st.caption('Estos conteos describen esta consulta. No acreditan cobertura continua de toda la cuenca ni disponibilidad operativa en costas o islas.')
    st.caption('Documento del que se extrajeron los registros: ' + _cuenca_ui_fecha_texto(cuenca.get('fecha_emision')) +
               ' · Consulta de la cuenca: ' + _cuenca_ui_fecha_texto(cuenca.get('fecha_consulta')))
    if cuenca.get('ultima_publicacion_indice'):
        st.caption('Última publicación listada por el organismo: ' + _cuenca_ui_fecha_texto(cuenca.get('ultima_publicacion_indice')) +
                   '. Una publicación más nueva no cambia automáticamente la fecha de la tabla extraída; revisá los boletines enlazados.')
    mostrar_eby_cuenca_zc(cuenca.get('eby'), key_prefix)

    st.subheader('Conexiones y aportes entre tramos')
    conexiones = _cuenca_ui_filas(cuenca.get('conexiones'))
    if not conexiones:
        conexiones = _cuenca_ui_filas(cuenca.get('topologia'))
    if conexiones:
        filas = [{'Desde': _cuenca_ui_texto(_cuenca_ui_campo(c, 'origen', 'desde')),
                  'Hacia': _cuenca_ui_texto(_cuenca_ui_campo(c, 'destino', 'hacia')),
                  'Relación': _cuenca_ui_texto(_cuenca_ui_campo(c, 'tipo', 'aporte', 'descripcion')),
                  'Verificación': 'Documentada' if c.get('verificada') is True else 'Pendiente de corroborar',
                  'Fuente': _cuenca_ui_url(_cuenca_ui_campo(c, 'url', 'fuente'))}
                 for c in conexiones]
        st.dataframe(pd.DataFrame(filas), hide_index=True, use_container_width=True,
                     column_config={'Fuente': st.column_config.LinkColumn('Fuente')})
        documentadas = [f for f in filas if f['Verificación'] == 'Documentada']
        if documentadas:
            lineas = ['digraph Cuenca { rankdir=TB; node [shape=box];']
            for f in documentadas[:40]:
                lineas.append(json.dumps(f['Desde'], ensure_ascii=False) + ' -> ' + json.dumps(f['Hacia'], ensure_ascii=False) +
                              ' [label=' + json.dumps(f['Relación'], ensure_ascii=False) + '];')
            st.graphviz_chart('\n'.join(lineas) + '\n}', use_container_width=True)
        st.caption('Esquema de conexiones documentadas; no es un mapa ni una simulación hidráulica. No asigna velocidades o tiempos de viaje a las crecidas.')
    else:
        st.info('Todavía no se recibió una topología documentada para esta consulta.')

    st.subheader('Estaciones, variables y estado de consulta')
    if estaciones:
        tabla = []
        for e in estaciones:
            fecha = _cuenca_ui_campo(e, 'fecha_dato', 'fecha', 'fecha_observacion')
            f = _cuenca_ui_fecha(fecha)
            edad = (pd.Timestamp(referencia) - f).total_seconds() / 3600 if f is not None else None
            tabla.append({'Estación': _cuenca_ui_texto(_cuenca_ui_campo(e, 'nombre', 'estacion_nombre', 'estacion')),
                          'Río / tramo': _cuenca_ui_texto(_cuenca_ui_campo(e, 'rio_tramo', 'tramo', 'rio')),
                          'Serie': _cuenca_ui_texto(_cuenca_ui_campo(e, 'serie_id', 'estacion_id')),
                          'Tipo': _cuenca_ui_texto(_cuenca_ui_campo(e, 'tipo_serie', 'tipo_dato', 'tipo')),
                          'Variable': _cuenca_ui_texto(e.get('variable')),
                          'Valor': _cuenca_ui_texto(e.get('valor'), 'Sin dato'),
                          'Unidad': _cuenca_ui_texto(e.get('unidad')),
                          'Referencia vertical': _cuenca_ui_texto(_cuenca_ui_campo(e, 'datum', 'referencia_vertical')),
                          'Fecha del dato': _cuenca_ui_fecha_texto(fecha),
                          'Fecha del documento': _cuenca_ui_fecha_texto(e.get('fecha_documento')),
                          'Antigüedad al abrir · h': round(edad, 1) if edad is not None and edad >= 0 else None,
                          'Consulta': _cuenca_ui_fecha_texto(_cuenca_ui_campo(e, 'fecha_consulta', 'consulta')),
                          'Estado': _cuenca_ui_texto(_cuenca_ui_campo(e, 'estado_consulta', 'estado')),
                          'Condición publicada': _cuenca_ui_texto(e.get('condicion_publicada')),
                          'Fuente': _cuenca_ui_url(_cuenca_ui_campo(e, 'url_origen', 'url', 'fuente'))})
        st.dataframe(pd.DataFrame(tabla), hide_index=True, use_container_width=True,
                     column_config={'Fuente': st.column_config.LinkColumn('Fuente')})
    else:
        st.info('No se recibieron estaciones con identidad y procedencia para mostrar.')
    st.caption('Una altura de escala depende del cero y datum de esa estación. No se suman alturas entre estaciones, no se trasladan umbrales y no se comparan directamente con una cota de terreno. Caudal, altura y descarga de una represa son magnitudes distintas.')

    st.subheader('Serie por estación · observaciones y pronósticos separados')
    grupos = {}
    for r in registros:
        identidad = tuple(_cuenca_ui_texto(_cuenca_ui_campo(r, *campos)) for campos in
                         [('estacion_nombre', 'estacion', 'nombre'), ('serie_id',), ('variable',), ('unidad',), ('datum', 'referencia_vertical'), ('tipo_serie', 'tipo_dato', 'tipo')])
        grupos.setdefault(identidad, []).append(r)
    if grupos:
        opciones = list(grupos)
        clave = key_prefix + 'serie'
        if st.session_state.get(clave) not in opciones:
            st.session_state.pop(clave, None)
        seleccion = st.selectbox('Serie para examinar', opciones,
            format_func=lambda v: f'{v[0]} · {v[1]} · {v[2]} · {v[5]}', key=clave)
        grupo = grupos[seleccion]
        puntos = []
        for r in grupo:
            fecha = _cuenca_ui_fecha(_cuenca_ui_campo(r, 'fecha', 'fecha_dato', 'time'))
            valor = _cuenca_ui_numero(_cuenca_ui_campo(r, 'valor', 'value'))
            if fecha is not None and valor is not None:
                puntos.append({'Fecha ART': fecha, 'Valor': valor})
        if puntos and seleccion[1] != 'Sin confirmar' and seleccion[2] != 'Sin confirmar' and seleccion[3] != 'Sin confirmar':
            d = pd.DataFrame(puntos).sort_values('Fecha ART')
            fig = px.line(d, x='Fecha ART', y='Valor', markers=True,
                          labels={'Valor': seleccion[2] + ' · ' + seleccion[3]},
                          title=seleccion[0] + ' · ' + seleccion[5] + ' · serie ' + seleccion[1])
            st.plotly_chart(fig, use_container_width=True, key=key_prefix + 'serie_grafico')
            if len(puntos) < len(grupo):
                st.caption('Se excluyeron del gráfico registros sin valor finito o sin fecha y zona horaria confirmadas.')
        else:
            st.warning('No se grafica una serie sin identidad, variable, unidad y fechas confirmadas. Los registros recibidos quedan disponibles para revisión.')
        with st.expander('Registros originales de esta serie'):
            st.dataframe(pd.DataFrame(grupo), hide_index=True, use_container_width=True)
            st.download_button('Descargar registros de la serie', pd.DataFrame(grupo).to_csv(index=False).encode('utf-8-sig'),
                               'cuenca_serie.csv', 'text/csv', key=key_prefix + 'serie_csv')
    else:
        st.caption('Todavía no hay registros temporales para consultar. La ausencia de datos no confirma estabilidad ni bajo riesgo.')

    st.subheader('Boletines y perspectivas de cuenca')
    if boletines:
        for i, b in enumerate(boletines):
            with st.expander(_cuenca_ui_texto(_cuenca_ui_campo(b, 'titulo', 'nombre'), 'Boletín recibido'), expanded=i == 0):
                st.write('Organismo: ' + _cuenca_ui_texto(_cuenca_ui_campo(b, 'organismo', 'autoridad')))
                st.caption('Estado: ' + _cuenca_ui_texto(b.get('estado'), 'Enlace identificado; revisar el documento original'))
                if b.get('documento_recuperado') is False:
                    st.warning('Esta consulta no recuperó el documento de este producto.')
                elif b.get('estado') == 'fuera_de_servicio':
                    st.warning('INA declara este producto temporalmente fuera de servicio.')
                st.caption('Publicación: ' + fecha_boletin_cuenca_texto_zc(_cuenca_ui_campo(b, 'publicado', 'fecha_publicacion', 'fecha_emision')) +
                           ' · Consulta: ' + _cuenca_ui_fecha_texto(_cuenca_ui_campo(b, 'consultado', 'fecha_consulta')))
                st.caption('Tipo de fecha: ' + _cuenca_ui_texto(b.get('tipo_fecha')) +
                           ' · Extracción: ' + ('Registros extraídos' if b.get('datos_extraidos') is True else 'Documento enlazado; contenido sin extracción automática confirmada'))
                st.write(_cuenca_ui_texto(_cuenca_ui_campo(b, 'resumen', 'descripcion')))
                st.caption('Alcance / validez: ' + _cuenca_ui_texto(_cuenca_ui_campo(b, 'alcance', 'vigencia', 'limites')))
                url = _cuenca_ui_url(_cuenca_ui_campo(b, 'url', 'fuente'))
                if url:
                    st.link_button('Leer boletín original', url, key=key_prefix + 'boletin_' + str(i))
    else:
        st.caption('No se recibieron boletines en esta consulta.')

    with st.expander('Límites, cobertura y procedencia', expanded=True):
        limites = list(resultado.get('limites') or []) + list(cuenca.get('incertidumbres') or [])
        for limite in dict.fromkeys(_cuenca_ui_texto(l) for l in limites):
            st.write('• ' + _cuenca_ui_texto(limite))
        st.caption('La cuenca aporta contexto regional. Las conexiones geográficas no reemplazan un pronóstico de propagación. La evaluación local y sus fuentes siguen disponibles en Modelo de inundaciones.')
        for i, fuente in enumerate(resultado.get('fuentes') or cuenca.get('fuentes') or []):
            fuente = fuente if isinstance(fuente, dict) else {'url': str(fuente)}
            url = _cuenca_ui_url(_cuenca_ui_campo(fuente, 'url', 'fuente'))
            if url:
                st.link_button(_cuenca_ui_texto(_cuenca_ui_campo(fuente, 'nombre', 'organismo'), 'Fuente original'),
                               url, key=key_prefix + 'fuente_' + str(i))
    exportacion = json.dumps(_cuenca_ui_json(resultado), ensure_ascii=False, indent=2, allow_nan=False, default=str)
    st.download_button('Descargar síntesis de cuenca y fuentes', exportacion, 'cuenca_parana_zc.json',
                       'application/json', key=key_prefix + 'json')

# cuenca_integracion_zc.py
def mostrar_sintesis_integrada_cuenca_zc(decision, key_prefix='zc_sintesis_'):
    decision=decision if isinstance(decision,dict) else {}
    st.subheader('Inundaciones · cuenca, pronóstico y situación local')
    nivel=decision.get('nivel_preparacion','VERIFICACIÓN PENDIENTE · EVALUACIÓN INTEGRADA NO DISPONIBLE')
    prioridad=decision.get('prioridad')
    (st.warning if prioridad in (1,2) else st.info)('**'+nivel+'**')
    st.caption('La crecida aguas arriba se contrasta con lluvia, suelo, río local, estuario y partes de accesos. Las fechas y los datos faltantes permanecen visibles. Una señal de preparación no es una orden de evacuación.')
    for motivo in decision.get('motivos',[])[:6]:
        st.write('• '+str(motivo))
    dudas=decision.get('incertidumbres',[])
    with st.expander('Cobertura y verificaciones pendientes',expanded=prioridad is None):
        cobertura=decision.get('cobertura_por_fuente',[])
        if isinstance(cobertura,dict):
            cobertura=[{'Fuente':k,'Estado':str(v)} for k,v in cobertura.items()]
        if cobertura:
            st.dataframe(pd.DataFrame(cobertura),hide_index=True,use_container_width=True)
        for duda in dudas:
            st.caption('Por verificar: '+str(duda))
    st.caption('Orden de evacuación local: ninguna verificada por esta consulta. Esto no acredita ausencia de disposiciones. Seguí las instrucciones directas de la autoridad local; no esperes una confirmación de la app.')

def mostrar_historicos_cuenca_zc(key_prefix='zc_cuenca_hist_'):
    st.subheader('Históricos oficiales de cuenca · consulta por serie')
    st.caption('El catálogo INA proporciona los identificadores reales. La consulta es opcional y conserva cada red, variable y unidad; no convierte estas curvas en tiempos de llegada ni alturas para Zárate–Campana.')
    if st.button('Consultar catálogo de estaciones de cuenca',key=key_prefix+'catalogo_button'):
        consultar_catalogo_cuenca_ina_zc.clear()
        st.session_state[key_prefix+'catalogo']=consultar_catalogo_cuenca_ina_zc()
    catalogo=st.session_state.get(key_prefix+'catalogo',{})
    if catalogo.get('error'):
        st.warning(catalogo['error'])
    tabla=catalogo.get('df',pd.DataFrame())
    if not isinstance(tabla,pd.DataFrame) or tabla.empty:
        st.info('Consultá el catálogo para elegir una serie verificada. Las estaciones del parte diario se muestran arriba con la fecha documental; no se inventa una historia a partir de un único valor.')
        return
    st.caption('Consulta del catálogo: '+_modelo_horizontes_fecha(catalogo.get('consulta')))
    ids=tabla.serie_id.astype(int).tolist()
    etiquetas={int(r['serie_id']):str(r['estacion'])+' · '+str(r['variable'])+' · '+str(r['unidad'])+' · '+str(r.get('red') or 'red sin confirmar')+' · serie '+str(r['serie_id']) for r in tabla.to_dict('records')}
    if st.session_state.get(key_prefix+'id') not in ids:
        st.session_state.pop(key_prefix+'id',None)
    serie=st.selectbox('Serie INA de cuenca',ids,format_func=lambda x:etiquetas[x],key=key_prefix+'id')
    dias=st.slider('Días de antecedentes de cuenca',1,90,30,key=key_prefix+'dias')
    clave=str(serie)+':'+str(dias)
    guardados=st.session_state.setdefault(key_prefix+'resultados',{})
    if st.button('Consultar observaciones de esta serie',key=key_prefix+'serie_button'):
        obtener_serie_cuenca_ina_zc.clear()
        guardados[clave]=obtener_serie_cuenca_ina_zc(serie,dias)
    resultado=guardados.get(clave,{})
    if not resultado:
        st.caption('No se recibió todavía este período de esta serie.')
        return
    if resultado.get('error'):
        st.warning(resultado['error'])
        return
    datos=resultado.get('df',pd.DataFrame()).copy()
    if datos.empty:
        st.warning('Serie sin observaciones recibidas.')
        return
    st.caption('Fuente consultada: '+_modelo_horizontes_fecha(resultado.get('consulta'))+'. Cada fila conserva la fecha del registro. Cero y datum: sin equivalencia local confirmada.')
    referencia=pd.Timestamp(ahora())
    grafico=datos[datos.zona_horaria_verificada.eq(True) & datos.fecha.le(referencia)].copy()
    if not grafico.empty:
        figura=px.line(grafico,x='fecha',y='valor',markers=True,labels={'fecha':'Fecha ART','valor':resultado.get('unidad','')},title=etiquetas[serie])
        st.plotly_chart(figura,use_container_width=True,key=key_prefix+'grafico')
    if len(grafico)<len(datos):
        st.warning('Se excluyeron del gráfico fechas futuras o sin zona horaria confirmada; sus registros se conservan para revisión.')
    st.dataframe(datos,hide_index=True,use_container_width=True)
    st.link_button('Fuente original de la serie',resultado['fuente'],key=key_prefix+'fuente')
    st.download_button('Descargar antecedentes de cuenca',datos.to_csv(index=False).encode('utf-8-sig'),'antecedentes_cuenca_ina.csv','text/csv',key=key_prefix+'csv')
# END CUENCA ZC 1.5.0

def mostrar_prevencion_inundaciones_zc(df):
    for clave in ('zc_modelo_predictivo_resultado','zc_prevencion_resultado','zc_cuenca_decision','zc_alturas_locales_resultado','zc_portada_contexto'):
        st.session_state.pop(clave,None)
    st.write('Lluvia intensa, crecida del Paraná y condiciones del estuario pueden afectar barrios, costas e islas. El modelo analiza pronósticos por horizonte y presenta por separado la evidencia actual.')
    if st.button('Actualizar vigilancia de inundaciones',key='zc_prevencion_refresh'):
        actualizar_fuentes_zc()
        st.rerun()
    cap=resolver_fuente_modelo_zc(obtener_cap_litoral,{'filas':[],'fecha_feed':None,'consultado':None},'avisos SMN')
    meteo=_resumen_meteorologico_prevencion_zc(df)
    with ThreadPoolExecutor(max_workers=7) as pool:
        f_refs=pool.submit(consultar_referencias_ina_zc)
        f_shn=pool.submit(obtener_contexto_shn_zc)
        f_cuenca=pool.submit(consultar_cuenca_parana_zc)
        f_obs={nombre:pool.submit(_zc_hidro_obtener_observaciones,c['observada']) for nombre,c in _zc_hidro_estaciones.items()}
        f_prono={nombre:pool.submit(_zc_hidro_obtener_pronostico,c['pronostico']) for nombre,c in _zc_hidro_estaciones.items()}
        referencias=resolver_fuente_modelo_zc(f_refs,{'referencias':{}},'referencias INA')
        shn=resolver_fuente_modelo_zc(f_shn,{'tabla':pd.DataFrame(),'inicio':None,'fin':None},'estuario SHN')
        observaciones={nombre:seleccionar_observaciones_locales_zc(resolver_fuente_modelo_zc(f_obs[nombre],
            {'df':pd.DataFrame(),'serie_id':c['observada'],'dias':7},'altura observada de '+nombre),referencias,c) for nombre,c in _zc_hidro_estaciones.items()}
        rios=[_resumen_rio_prevencion_zc(nombre,c,observaciones[nombre],referencias) for nombre,c in _zc_hidro_estaciones.items()]
        pronosticos={nombre:_zc_hidro_pronostico_para_mostrar(resolver_fuente_modelo_zc(f,
            {'df':pd.DataFrame(),'url':_zc_hidro_url_pronostico(_zc_hidro_estaciones[nombre]['pronostico'])},'pronóstico INA de '+nombre)) for nombre,f in f_prono.items()}
        cuenca=resolver_fuente_modelo_zc(f_cuenca,{'estado':'sin_verificar','registros':[],
            'incertidumbres':['No se recuperó contexto de cuenca verificable.']},'cuenca del Paraná')
    st.session_state['zc_alturas_locales_resultado']=snapshot_alturas_locales_zc(observaciones,referencias,obtener_alturas_prefectura_zc())
    st.session_state['zc_portada_contexto']={'cap':cap,'rios':{r['nombre']:r for r in rios}}
    st.session_state['zc_cuenca_resultado']=cuenca
    partes=st.session_state.get('zc_partes_inundacion',pd.DataFrame())
    if not partes.empty:
        try:
            partes=validar_partes_inundacion_zc(partes)
        except ValueError:
            partes=pd.DataFrame()
    evaluacion=evaluar_prevencion_inundaciones_zc(meteo,cap,rios,shn,partes)
    st.session_state['zc_prevencion_resultado']=evaluacion
    modelo=construir_modelo_predictivo_zc(NODOS,st.session_state.get('raw_ecmwf',[]),pronosticos,rios,cap,shn,partes,st.session_state.get('ficha_trimestral'),meteo_actual=meteo)
    decision=construir_decision_cuenca_zc(modelo,evaluacion,cuenca,ahora())
    modelo['estado_general_local']=modelo['estado_general']
    modelo['estado_general']=decision['nivel_preparacion']
    modelo['decision_integrada']=decision
    modelo['cuenca']=cuenca
    st.session_state['zc_cuenca_decision']=decision
    st.session_state['zc_modelo_predictivo_resultado']=modelo
    mostrar_modelo_predictivo_zc(modelo)
    mostrar_alturas_locales_zc(st.session_state['zc_alturas_locales_resultado'],key_prefix='zc_alturas_modelo_')
    st.subheader('Vigilancia actual y preparación ante inundaciones')
    st.session_state['zc_prevencion_resultado']=evaluacion
    nivel=evaluacion['nivel_preventivo']
    mensajes={2:st.error,1:st.warning,None:st.info,0:st.info}
    mensajes.get(evaluacion.get('prioridad'),st.info)('**'+nivel+'**')
    for motivo in evaluacion['motivos']:
        st.write('• '+motivo)
    for falta in evaluacion['incertidumbres']:
        st.caption('Por confirmar: '+falta)
    st.caption('Estado preventivo experimental, sin porcentaje de probabilidad de inundación. El índice meteorológico y los avisos oficiales conservan su significado; un color bajo por lluvia no determina el estado del río ni de los accesos.')
    st.subheader('Cuenca aguas arriba · contexto para anticipar la preparación')
    for motivo in decision.get('motivos',[]):
        st.write('• '+str(motivo))
    st.caption('Detalle de represas, estaciones, boletines y antecedentes: solapa Cuenca del Paraná. La fecha de cada informe y sus límites se conservan; no se estima una llegada local con tiempos fijos.')
    filas=[{'Factor':'Lluvia y anegamiento','Estado':meteo['nivel']+' · índice meteorológico experimental',
            'Fecha':meteo['fecha'].strftime('%d/%m/%Y %H:%M ART') if meteo['fecha'] is not None else 'Sin consulta confirmada',
            'Dato':f"{meteo['n_validos']}/{len(NODOS)} puntos completos; consultá lluvia, suelo y radar"}]
    fecha_cap=_ui_fecha_local(cap.get('fecha_feed'))
    consulta_cap=_ui_fecha_local(cap.get('consultado'))
    ref_cap=_ui_fecha_local(ahora())
    cap_completo=not any(cap.get(k) for k in ('error','fallos','truncado','fechas_no_confirmadas_locales','replacements_no_confirmados'))
    cap_actual=all(f is not None and -300<=(ref_cap-f).total_seconds()<=86400 for f in (fecha_cap,consulta_cap))
    filas.append({'Factor':'Avisos oficiales · SMN',
                  'Estado':'Canal vigente; revisar avisos y áreas' if cap_completo and cap_actual else 'Cobertura o vigencia por confirmar',
                  'Fecha':fecha_cap.strftime('%d/%m/%Y %H:%M ART') if fecha_cap is not None else 'Publicación sin confirmar',
                  'Dato':f"{cap.get('leidos',0)} de {cap.get('total',0)} documentos leídos; el aviso oficial conserva su área y horario"})
    for r in rios:
        dato=f"Último registro recibido: {r['altura_m']:.2f} m" if np.isfinite(r['altura_m']) else 'Sin altura verificada'
        filas.append({'Factor':'Río · '+r['nombre'],'Estado':'Observación de hasta 6 h' if r['observacion_vigente'] else 'Altura actual sin confirmar',
                      'Fecha':r['fecha'].strftime('%d/%m/%Y %H:%M ART') if r['fecha'] is not None else 'Sin fecha',
                      'Dato':dato+'; referencia de escala publicada '+('recuperada' if r['umbral_publicado'] else 'sin consulta vigente')})
        config=_zc_hidro_estaciones[r['nombre']]
        prono=pronosticos[r['nombre']]
        emision=_ui_fecha_local(prono.get('emision'))
        tabla_prono=prono.get('df',pd.DataFrame())
        dato_prono='Pronóstico no recuperado o sin horas futuras verificadas'
        if not prono.get('error') and not tabla_prono.empty:
            maximo=tabla_prono.loc[tabla_prono.main.idxmax()]
            dato_prono=f"Máximo de horas futuras: {maximo['main']:.2f} m, {maximo['fecha']:%d/%m %H:%M} ART; serie {config['pronostico']}"
        filas.append({'Factor':'Pronóstico INA · '+r['nombre'],
                      'Estado':'No verificado' if prono.get('error') else 'Corrida atrasada' if prono.get('atrasado') else 'Pronóstico experimental disponible',
                      'Fecha':emision.strftime('%d/%m/%Y %H:%M ART') if emision is not None else 'Emisión sin confirmar',
                      'Dato':dato_prono})
    n_partes=len(partes)
    n_partes_vigentes=int(partes['vigente'].eq(True).sum()) if n_partes and 'vigente' in partes else 0
    filas.append({'Factor':'Partes locales y accesos',
                  'Estado':'Partes declarados; corroborar cada sector' if n_partes_vigentes else 'Sin parte vigente aportado',
                  'Fecha':'Vigencia individual en Territorio y accesos',
                  'Dato':f'{n_partes_vigentes} de {n_partes} partes vigentes; no certifican transitabilidad de otros sectores'})
    fin=_ui_fecha_local(shn.get('fin')); inicio=_ui_fecha_local(shn.get('inicio')); ahora_local=_ui_fecha_local(ahora())
    shn_vigente=not shn.get('error') and inicio is not None and fin is not None and inicio<=ahora_local<=fin
    filas.append({'Factor':'Estuario / sudestada · SHN','Estado':'Boletín vigente de contexto' if shn_vigente else 'Contexto por verificar',
                  'Fecha':f'{inicio:%d/%m %H:%M} a {fin:%d/%m %H:%M} ART' if inicio is not None and fin is not None else 'Sin validez confirmada',
                  'Dato':'Río de la Plata; no traslada alturas de otros puertos a Zárate o Campana'})
    st.dataframe(pd.DataFrame(filas),hide_index=True,use_container_width=True)
    st.caption('Las alturas antiguas se conservan como antecedentes. Las referencias de alerta y evacuación describen la escala publicada; no acreditan profundidad en un barrio ni una orden de evacuación.')
    mostrar_preparacion_inundaciones(key_prefix='zc_prevencion_')
    with st.expander('Escalas fluviales y contexto del estuario'):
        refs=list(referencias.get('referencias',{}).values())
        if refs:
            tabla=pd.DataFrame(refs)[['estacion','serie_observada','nivel_alerta_m','nivel_evacuacion_m','cero_ign_m','fecha_consulta']]
            st.dataframe(tabla,hide_index=True,use_container_width=True)
            st.caption(referencias.get('advertencia',''))
        else:
            st.warning(referencias.get('error','Referencias fluviales sin verificar.'))
            documental=referencias_ina_zc_solo_documentales()
            st.dataframe(pd.DataFrame(documental['referencias']),hide_index=True,use_container_width=True)
            st.caption(documental['interpretacion'])
        st.link_button('INA · referencias y escalas publicadas',INA_REFERENCIAS_ZC_DOCUMENTACION,key='zc_prevencion_ina_metadata')
        st.link_button('INA · pronósticos locales',_zc_hidro_ina_producto,key='zc_prevencion_ina_productos')
        st.caption('Las referencias de las series observadas 40/41 no se aplican automáticamente a los pronósticos 29534/3405: falta equivalencia documentada de sus ceros de escala.')
        if shn.get('error'):
            st.warning(shn['error'])
        else:
            st.caption('Validez SHN: '+filas[-1]['Fecha']+'. Horas interpretadas en ART; contexto del estuario.')
            if not shn.get('tabla',pd.DataFrame()).empty:
                st.dataframe(shn['tabla'],hide_index=True,use_container_width=True)
            if not shn_vigente:
                st.warning('Boletín futuro o vencido: consultá una publicación vigente.')
        st.link_button('SHN · pronóstico mareológico del Río de la Plata',SHN_PREVENCION_URL,key='zc_prevencion_shn')
    st.info('Ante agua creciente, aislamiento o peligro para personas, contactá Defensa Civil 103 o Emergencias 911. Reconfirmá acceso, destino y asistencia con la autoridad; en Campana, SAME 107.')
    estado={'version':VERSION,'evaluacion':evaluacion,'decision_integrada':decision,'cuenca':cuenca,'factores':filas,'fecha_consulta':ahora().isoformat()}
    st.download_button('Descargar estado preventivo y fuentes',json.dumps(_modelo_horizontes_json_seguro(estado),ensure_ascii=False,indent=2,allow_nan=False),
                       'prevencion_inundaciones_zc.json','application/json',key='zc_prevencion_export')


def evaluar_prevencion_inundaciones_zc(meteo, cap, rios, shn, reportes=None, referencia=None):
    """Consolidate independent evidence without changing the meteorological index.

    Upstream must validate ``observacion_vigente`` as an aware observation <=6 h,
    ``umbral_publicado`` as current (<=24 h) INA metadata for that SAME observed
    scale, and report ``vigente`` as a local, sourced declaration <=24 h. A
    published INA evacuation reference is not a municipal evacuation order.
    Forecasts and SHN cannot establish current local flooding here.
    """
    import math
    import re
    import unicodedata
    from datetime import datetime, timedelta, timezone

    def texto(valor):
        return ''.join(c for c in unicodedata.normalize('NFKD', str(valor or ''))
                       if not unicodedata.combining(c)).strip().lower()

    def verdadero(valor):
        return type(valor).__name__ in ('bool', 'bool_') and bool(valor)

    def numero(valor):
        if valor is None or type(valor).__name__ in ('bool', 'bool_'):
            return None
        try:
            valor = float(valor)
            return valor if math.isfinite(valor) else None
        except (ValueError, TypeError):
            return None

    def fecha(valor):
        if not isinstance(valor, datetime) or valor.tzinfo is None or valor.utcoffset() is None:
            return None
        try:
            return valor.astimezone(timezone.utc)
        except (ValueError, OverflowError):
            return None

    instante = fecha(referencia) if referencia is not None else datetime.now(timezone.utc)
    motivos, incertidumbres, prioridad = [], [], 0
    if instante is None:
        return {'nivel_preventivo': 'VERIFICACIÓN PENDIENTE', 'prioridad': None,
                'motivos': [], 'incertidumbres': ['Hora de evaluación sin zona horaria confirmada.']}

    localidades = {'zarate', 'campana', 'zarate centro', 'zarate costanera', 'lima',
                   'escalada', 'delta de zarate · referencia', 'campana centro',
                   'campana costanera', 'ingeniero otamendi', 'rio lujan',
                   'delta de campana · referencia'}
    meteo = meteo if isinstance(meteo, dict) else {}
    nivel = numero(meteo.get('nivel'))
    clases = {'verde': 0, 'amarillo': 1, 'rojo': 2}
    clase = clases.get(texto(meteo.get('nivel')))
    if nivel is not None and 0 <= nivel <= 100:
        clase = 2 if nivel >= 55 else 1 if nivel >= 35 else 0
    elif nivel is not None:
        clase = None
    completo = verdadero(meteo.get('completo'))
    vigente = verdadero(meteo.get('vigente'))
    if not completo or not vigente or clase is None:
        incertidumbres.append('Meteorología incompleta, antigua o con nivel sin confirmar.')
    # A missing point must not suppress a positive signal from another valid point.
    # Partial low readings still retain uncertainty and cannot become all-clear.
    if vigente and clase is not None and (completo or verdadero(meteo.get('lecturas_validas'))):
        prioridad = max(prioridad, clase)
        motivos.append(('Meteorología: índice experimental ' + f'{nivel:g}/100' if nivel is not None
                        else 'Meteorología: nivel experimental ' + texto(meteo.get('nivel')))
                       + '; aporta preparación, no probabilidad de inundación.')

    cap = cap if isinstance(cap, dict) else {}
    feed, consulta = fecha(cap.get('fecha_feed')), fecha(cap.get('consultado'))
    canal_actual = all(f is not None and -300 <= (instante-f).total_seconds() <= 86400
                       for f in (feed, consulta))
    if cap.get('error') or not canal_actual:
        incertidumbres.append('Canal SMN sin consulta o publicación actual confirmada.')
    if cap.get('fallos') or cap.get('truncado'):
        incertidumbres.append('Lectura SMN parcial: no confirma ausencia de avisos locales.')
    if cap.get('replacements_no_confirmados'):
        incertidumbres.append('Reemplazos o cancelaciones SMN con emisión sin confirmar; revisar los avisos originales.')
    if cap.get('fechas_no_confirmadas_locales', cap.get('fechas_no_confirmadas', 0)):
        incertidumbres.append('Hay documentos SMN locales con fecha o vigencia sin confirmar.')
    filas = cap.get('filas')
    if not isinstance(filas, (list, tuple)):
        filas = []
        incertidumbres.append('Documentos SMN locales sin confirmar.')

    def emision_valida(fila):
        emision = fecha(fila.get('emision'))
        return emision is not None and emision <= instante + timedelta(minutes=5)

    reemplazados = {str(ref) for f in filas if isinstance(f, dict)
                   and f.get('status') == 'Actual' and f.get('tipo_mensaje') in ('Cancel', 'Update')
                   and emision_valida(f) for ref in (f.get('referencias') or [])}
    for fila in filas:
        if not isinstance(fila, dict) or fila.get('status') != 'Actual':
            continue
        local = (any(texto(n) in localidades for n in (fila.get('nodos') or []))
                 or (not fila.get('poligonos') and bool(re.search(
                     r'\b(zarate|campana)\b', texto(' '.join(fila.get('areas') or [])))))
                 or texto(fila.get('asociacion_local')).startswith('mencion textual local'))
        if not local:
            continue
        if not emision_valida(fila):
            incertidumbres.append('Aviso SMN local con emisión futura o sin fecha confirmada.')
            continue
        if fila.get('tipo_mensaje') == 'Cancel' or str(fila.get('id')) in reemplazados:
            continue
        if fila.get('tipo_mensaje') not in ('Alert', 'Update'):
            incertidumbres.append('Tipo de mensaje SMN local sin interpretar.')
            continue
        desde = fecha(fila.get('desde')) or fecha(fila.get('emision'))
        hasta, emision = fecha(fila.get('hasta')), fecha(fila.get('emision'))
        if hasta is None or desde is None or hasta <= desde or hasta < emision:
            incertidumbres.append('Aviso SMN local con período sin confirmar.')
            continue
        if hasta <= instante:
            continue
        evento = texto(str(fila.get('fenomeno') or '') + ' ' + str(fila.get('titulo') or ''))
        if not any(p in evento for p in ('lluv', 'torment', 'inund', 'crecida', 'desbord')):
            continue
        if cap.get('error') or not canal_actual:
            incertidumbres.append('Aviso SMN recibido: actualizar el canal antes de confirmar su vigencia.')
            continue
        severo = texto(fila.get('severidad_cap')) in ('severe', 'extreme')
        prioridad = max(prioridad, 2 if severo else 1)
        vigencia = 'previsto' if desde > instante else 'vigente'
        motivos.append('SMN: aviso local ' + vigencia + ' de ' + str(fila.get('fenomeno') or 'lluvia/tormenta')
                       + '; revisar área, horario y recomendaciones oficiales.')

    recibidos = set()
    rios = rios if isinstance(rios, (list, tuple)) else []
    for rio in rios:
        if not isinstance(rio, dict):
            continue
        serie = numero(rio.get('serie_id'))
        if serie not in (40, 41):
            incertidumbres.append('Referencia fluvial ajena a las escalas observadas INA 40/41.')
            continue
        recibidos.add(int(serie))
        nombre = 'Zárate' if serie == 40 else 'Campana'
        altura, alerta, evacuacion = (numero(rio.get(c)) for c in ('altura_m', 'alerta_m', 'evacuacion_m'))
        actual = verdadero(rio.get('observacion_vigente')) and altura is not None
        umbral = (verdadero(rio.get('umbral_publicado')) and alerta is not None
                  and (evacuacion is None or evacuacion > alerta))
        if not actual:
            incertidumbres.append(nombre + ': altura observada actual sin confirmar (máximo 6 h).')
        if not umbral:
            incertidumbres.append(nombre + ': umbral publicado de la misma escala sin confirmar.')
        if actual and umbral:
            if altura >= alerta:
                prioridad = max(prioridad, 2)
                referencia_umbral = 'referencia INA de evacuación' if evacuacion is not None and altura >= evacuacion else 'referencia INA de alerta'
                motivos.append(nombre + ': altura observada alcanza ' + referencia_umbral
                               + '; corroborar con la autoridad local. No confirma desborde ni una orden de evacuación.')
            else:
                motivos.append(nombre + ': observación actual por debajo del umbral publicado de su escala; mantener vigilancia local.')
    for serie, nombre in ((40, 'Zárate'), (41, 'Campana')):
        if serie not in recibidos:
            incertidumbres.append(nombre + ': observación y umbral local sin verificar.')

    shn = shn if isinstance(shn, dict) else {}
    inicio, fin = fecha(shn.get('inicio')), fecha(shn.get('fin'))
    if shn.get('error') or inicio is None or fin is None or not inicio <= instante < fin:
        incertidumbres.append('Contexto SHN del Río de la Plata sin período actual confirmado.')
    else:
        motivos.append('SHN: contexto vigente del estuario; no es una medición ni un umbral local de Zárate/Campana.')

    if hasattr(reportes, 'to_dict'):
        reportes = reportes.to_dict('records')
    partes = reportes if isinstance(reportes, (list, tuple)) else []
    partes_locales = [p for p in partes if isinstance(p, dict)
                      and verdadero(p.get('vigente')) and (
                          texto(p.get('localidad')) in localidades
                          or (verdadero(p.get('ambito_validado'))
                              and texto(p.get('partido')) in ('zarate', 'campana')))]
    estados_confirmados = ('agua_presente','acceso_cerrado','sin_afectacion_reportada')
    for parte in partes_locales:
        if texto(parte.get('estado')) not in estados_confirmados:
            incertidumbres.append(str(parte.get('localidad') or 'Sector local')+': estado del parte sin confirmar.')
    partes_vigentes = [p for p in partes_locales if texto(p.get('estado')) in estados_confirmados]
    if not partes_vigentes:
        incertidumbres.append('Partes locales y accesos sin corroboración vigente.')
    for parte in partes_vigentes:
        estado = texto(parte.get('estado'))
        if estado in ('agua_presente', 'acceso_cerrado'):
            prioridad = max(prioridad, 2)
            detalle = 'agua reportada' if estado == 'agua_presente' else 'acceso reportado cerrado'
            motivos.append(str(parte['localidad']) + ': ' + detalle
                           + ' en un parte declarado vigente; corroborar fuente y sector. No constituye una orden oficial.')
        else:
            motivos.append(str(parte['localidad']) + ': parte declarado vigente; reconfirmar el sector y los accesos antes de moverse.')

    incertidumbres = list(dict.fromkeys(incertidumbres))
    nivel = ('ATENCIÓN PREVENTIVA ALTA' if prioridad == 2 else 'PREPARACIÓN' if prioridad == 1
             else 'VERIFICACIÓN PENDIENTE' if incertidumbres else 'MANTENER VIGILANCIA')
    return {'nivel_preventivo': nivel, 'prioridad': None if prioridad == 0 and incertidumbres else prioridad,
            'motivos': list(dict.fromkeys(motivos)), 'incertidumbres': incertidumbres}



# Instrucciones internas del módulo omitidas de la interfaz.
# Instrucciones internas del módulo omitidas de la interfaz.
MODELO_PREDICTIVO_ZC_VERSION='MP-ZC 0.2 · cuenca y evidencia local'
REGLAS_MODELO_ZC={
    'lluvia_24_mm':50.0,'lluvia_72_mm':100.0,
    'humedad_modelada_m3_m3':0.35,'runoff_72_mm':30.0,
    'naturaleza':'Reglas provisionales del prototipo; no son umbrales locales de inundación ni recomendaciones oficiales.',
}


def _modelo_fecha_zc(valor):
    try:
        f=pd.Timestamp(valor)
        if pd.isna(f) or f.tzinfo is None:
            return None
        return f.tz_convert(TZ)
    except (TypeError,ValueError,OverflowError):
        return None


def horizontes_modelo_zc(referencia=None):
    ref=_modelo_fecha_zc(referencia if referencia is not None else ahora())
    if ref is None:
        raise ValueError('La evaluación necesita fecha y zona horaria verificadas.')
    base=ref.ceil('h')
    return [{'id':ident,'horizonte':nombre,'inicio':base+pd.Timedelta(hours=a),
             'fin':base+pd.Timedelta(hours=b),'horas':b-a}
            for ident,nombre,a,b in [('corto','Corto · 0–72 h',0,72),
                                    ('medio','Mediano · días 4–7',72,168),
                                    ('largo','Extendido · días 8–15',168,360)]]


# BEGIN FUENTES INDEPENDIENTES ZC 1.5.2 · validador_modelo_datos_zc.py
def _validar_respuesta_modelo_zc(nodo, datos, referencia):
    """Keep verified rain when another variable is absent, with explicit gaps."""
    ref = pd.Timestamp(referencia)
    if pd.isna(ref) or ref.tzinfo is None:
        raise ValueError('La evaluación del modelo necesita una hora con zona verificable.')
    ref = ref.tz_convert(TZ)
    if not isinstance(datos, dict) or datos.get('error'):
        raise ValueError('La fuente no devolvió una respuesta meteorológica utilizable.')
    try:
        coordenadas = (datos['latitude'], datos['longitude'], nodo['lat'], nodo['lon'])
        if any(isinstance(c, (bool, np.bool_)) for c in coordenadas):
            raise ValueError()
        lat, lon, nlat, nlon = map(float, coordenadas)
    except (KeyError, TypeError, ValueError):
        raise ValueError('La respuesta no permite verificar las coordenadas de la celda.') from None
    if (not np.isfinite([lat, lon, nlat, nlon]).all()
            or not (-90 <= lat <= 90 and -180 <= lon <= 180)
            or not (-90 <= nlat <= 90 and -180 <= nlon <= 180)):
        raise ValueError('Las coordenadas de la celda son inválidas.')
    p1, p2 = np.radians([nlat, lat])
    dp, dl = np.radians([lat - nlat, lon - nlon])
    distancia = float(6371.0 * 2.0 * np.arcsin(np.sqrt(np.clip(
        np.sin(dp / 2.0) ** 2 + np.cos(p1) * np.cos(p2) * np.sin(dl / 2.0) ** 2, 0, 1))))
    if distancia > 40:
        raise ValueError('La celda devuelta está a más de 40 km del punto solicitado.')
    if (datos.get('timezone') not in ('America/Argentina/Buenos_Aires', 'America/Buenos_Aires')
            or datos.get('utc_offset_seconds') != -10800):
        raise ValueError('La zona horaria o el desplazamiento UTC de la respuesta no están verificados.')
    hourly, units = datos.get('hourly'), datos.get('hourly_units')
    if not isinstance(hourly, dict) or not isinstance(units, dict) or units.get('time') != 'iso8601':
        raise ValueError('Faltan la serie horaria o sus unidades verificables.')
    tiempos = hourly.get('time')
    if not isinstance(tiempos, list) or not tiempos:
        raise ValueError('La respuesta no contiene una grilla horaria utilizable.')
    try:
        horas = pd.DatetimeIndex(pd.to_datetime(tiempos, errors='coerce'))
        if horas.tz is not None:
            horas = horas.tz_convert(TZ).tz_localize(None)
    except (TypeError, ValueError):
        raise ValueError('Los horarios meteorológicos son inválidos o mezclan zonas horarias.') from None
    if horas.isna().any() or not horas.is_unique or not horas.is_monotonic_increasing:
        raise ValueError('Los horarios meteorológicos son inválidos, repetidos o están desordenados.')
    if (horas != horas.floor('h')).any() or (len(horas) > 1
            and not np.all(np.diff(horas.asi8) == pd.Timedelta(hours=1).value)):
        raise ValueError('La grilla meteorológica no tiene pasos horarios continuos.')
    try:
        consulta = pd.Timestamp(datos.get('_consulta_meteorologica'))
        if pd.isna(consulta) or consulta.tzinfo is None:
            raise ValueError()
        consulta = consulta.tz_convert(TZ)
        if not -300 <= (ref - consulta).total_seconds() <= 1800:
            raise ValueError()
    except (TypeError, ValueError, OverflowError):
        raise ValueError('Consulta meteorológica vencida, futura o sin fecha verificable.') from None
    if units.get('precipitation') != 'mm':
        raise ValueError('La unidad de precipitación no está verificada en milímetros.')
    lluvia = hourly.get('precipitation')
    if not isinstance(lluvia, list) or len(lluvia) != len(horas):
        raise ValueError('La precipitación no coincide en longitud con la grilla horaria.')

    capas = ('soil_moisture_0_to_7cm', 'soil_moisture_7_to_28cm',
             'soil_moisture_28_to_100cm', 'soil_moisture_100_to_255cm')
    limpio = dict(hourly)
    limpio['time'] = [hora.isoformat() for hora in horas]
    problemas = []
    for campo in ('precipitation', 'runoff') + capas:
        esperada = 'm³/m³' if campo in capas else 'mm'
        valores = hourly.get(campo)
        if units.get(campo) != esperada:
            limpio[campo] = [None] * len(horas)
            problemas.append(campo + ': unidad ausente o no verificada; variable sin interpretar.')
            continue
        if not isinstance(valores, list) or len(valores) != len(horas):
            limpio[campo] = [None] * len(horas)
            problemas.append(campo + ': variable ausente o longitud incompatible; no se completa con cero.')
            continue
        normalizados = []
        invalidos = 0
        for valor in valores:
            if valor is None:
                normalizados.append(None)
                continue
            try:
                if isinstance(valor, (bool, np.bool_)):
                    raise ValueError()
                numero = float(valor)
                if np.isnan(numero):
                    normalizados.append(None)
                    continue
                # A broad plausibility guard, never a flood-trigger threshold.
                if (not np.isfinite(numero) or numero < 0
                        or (campo in capas and numero > 1)
                        or (campo in ('precipitation', 'runoff') and numero > 1000)):
                    raise ValueError()
                normalizados.append(numero)
            except (TypeError, ValueError, OverflowError):
                normalizados.append(None)
                invalidos += 1
        limpio[campo] = normalizados
        if invalidos:
            problemas.append(f'{campo}: {invalidos} valores inválidos quedaron sin dato; no afectan a otras variables.')

    referencia_hora = ref.floor('h').tz_localize(None)
    fechas_suelo = []
    for campo in capas:
        valores = np.asarray(limpio[campo], dtype=float)
        posiciones = np.where((horas <= referencia_hora) & np.isfinite(valores))[0]
        ultimo = horas[posiciones[-1]] if len(posiciones) else None
        if ultimo is not None and pd.Timedelta(0) <= referencia_hora - ultimo <= pd.Timedelta(hours=3):
            fechas_suelo.append(ultimo)
        else:
            limpio[campo] = [None if hora <= referencia_hora else valor
                             for hora, valor in zip(horas, limpio[campo])]
    sanear = globals().get('_sanear_variables_meteorologicas_opcionales')
    if callable(sanear):
        limpio = sanear(limpio, len(horas))
    meta = {'consulta_meteorologica': consulta.isoformat(),
            'referencia_datos': referencia_hora.tz_localize(TZ).isoformat(),
            'celda_lat': lat, 'celda_lon': lon, 'distancia_celda_km': round(distancia, 2),
            'capas_humedad_vigentes': len(fechas_suelo),
            'fecha_humedad_suelo': min(fechas_suelo).tz_localize(TZ).isoformat() if fechas_suelo else None,
            'problemas_variables_modelo': problemas}
    return {**datos, 'hourly': limpio}, horas, meta
# END FUENTES INDEPENDIENTES ZC 1.5.2

# BEGIN FUENTES INDEPENDIENTES ZC 1.5.2 · carga_fuentes_disponibles_zc.py
def asegurar_trimestral_zc(forzar=False, referencia=None):
    """Consulta automática acotada; conserva archivos aportados y documentos previos."""
    ref = _ui_fecha_local(referencia if referencia is not None else ahora())
    guardado = st.session_state.get('ficha_trimestral')
    if isinstance(guardado,dict) and guardado.get('error') and not guardado.get('referencia_documental'):
        guardado={**guardado,'referencia_documental':referencias_documentales_zc()['smn_trimestral']}
        st.session_state['ficha_trimestral']=guardado
    if isinstance(guardado, dict) and guardado.get('aportado_por_usuario'):
        return guardado
    intento = _ui_fecha_local(st.session_state.get('zc_trimestral_ultimo_intento'))
    edad = (ref - intento).total_seconds() if ref is not None and intento is not None else None
    # El intento, incluido un fallo, se conserva para no repetir la descarga
    # del PDF al cambiar localidad, radar u otro control de la aplicación.
    if not forzar and isinstance(guardado, dict) and edad is not None and 0 <= edad < 21600:
        return guardado
    if ref is not None:
        st.session_state['zc_trimestral_ultimo_intento'] = ref.isoformat()
    try:
        nuevo = consultar_trimestral()
        if not isinstance(nuevo, dict):
            nuevo = {'error': 'La consulta trimestral no devolvió un documento verificable.'}
    except Exception:
        nuevo = {'error': 'No se pudo completar la consulta del informe trimestral SMN.'}
    if nuevo.get('error') and isinstance(guardado, dict) and not guardado.get('error'):
        # Una caída posterior no borra el PDF ya obtenido. La consulta fallida
        # se muestra separada de su emisión y no renueva la fecha del producto.
        guardado = {**guardado, 'ultima_consulta_error': str(nuevo['error']),
                    'ultima_consulta_intento': ref.isoformat() if ref is not None else None}
        st.session_state['ficha_trimestral'] = guardado
    else:
        st.session_state['ficha_trimestral'] = nuevo
    return st.session_state['ficha_trimestral']

def resumen_trimestral_modelo_zc(informe, referencia=None):
    """Describe únicamente documento, período y vigencia; no extrae riesgo local."""
    ref = _ui_fecha_local(referencia if referencia is not None else ahora())
    informe = informe if isinstance(informe, dict) else {}
    if not informe or informe.get('error'):
        referencia_documental=informe.get('referencia_documental') if isinstance(informe,dict) else None
        referencia_documental=referencia_documental if isinstance(referencia_documental,dict) else {}
        inicio_doc=_ui_fecha_local(referencia_documental.get('inicio'))
        fin_doc=_ui_fecha_local(referencia_documental.get('fin'))
        estado_doc=estado_periodo_trimestral(inicio_doc,fin_doc,referencia=ref) if ref is not None and inicio_doc is not None and fin_doc is not None and inicio_doc<fin_doc else 'Período sin confirmar'
        return {'informe_smn_disponible': False,
                'referencia_documental_disponible':bool(referencia_documental),
                'referencia_documental':referencia_documental,
                'estado_documento':estado_doc if referencia_documental else 'Sin documento trimestral recuperado',
                'periodo': referencia_documental.get('periodo'), 'fecha_documento': referencia_documental.get('emision'), 'fecha_consulta': None,
                'url_documento': referencia_documental.get('url'),
                'error_consulta': str(informe.get('error') or 'Documento no consultado o sin confirmar.')}
    inicio = _ui_fecha_local(informe.get('inicio'))
    fin = _ui_fecha_local(informe.get('fin'))
    if inicio is None or fin is None or inicio >= fin or ref is None:
        estado = 'Período del documento sin confirmar'
    else:
        estado = estado_periodo_trimestral(inicio, fin, referencia=ref)
    return {'informe_smn_disponible': True, 'estado_documento': estado,
            'periodo': informe.get('periodo'),
            'fecha_documento': informe.get('emision'),
            'fecha_consulta': informe.get('consulta'),
            'url_documento': informe.get('url'),
            'aportado_por_usuario': bool(informe.get('aportado_por_usuario')),
            'error_consulta': informe.get('ultima_consulta_error') or ''}
# END FUENTES INDEPENDIENTES ZC 1.5.2

def analizar_atmosfera_predictiva_zc(nodo,payload,referencia=None):
    ref=_modelo_fecha_zc(referencia if referencia is not None else ahora())
    horizontes=horizontes_modelo_zc(ref)
    base=horizontes[0]['inicio']
    salida=[]
    try:
        limpio,horas,meta=_validar_respuesta_modelo_zc(nodo,payload,ref)
        consulta=_modelo_fecha_zc(meta.get('consulta_meteorologica'))
        if consulta is None or not -300<=(ref-consulta).total_seconds()<=1800:
            raise ValueError('Consulta meteorológica vencida, futura o sin fecha verificable.')
        hourly=limpio['hourly']; units=payload['hourly_units']
        horas=horas.tz_localize(TZ)
        p=pd.Series(hourly['precipitation'],index=horas,dtype=float)
        r=pd.Series(hourly['runoff'],index=horas,dtype=float)
        capas=['soil_moisture_0_to_7cm','soil_moisture_7_to_28cm',
               'soil_moisture_28_to_100cm','soil_moisture_100_to_255cm']
        suelo=pd.DataFrame({c:hourly[c] for c in capas},index=horas,dtype=float)
        fin_antecedente=ref.floor('h')
        pasado=p.reindex(pd.date_range(fin_antecedente-pd.Timedelta(hours=167),fin_antecedente,freq='h'))
        lluvia_previa=float(pasado.sum()) if len(pasado)==168 and pasado.notna().all() else None

        def auxiliar(campo,unidad,seleccion):
            if units.get(campo)!=unidad:
                return pd.Series(dtype=float)
            return pd.Series(hourly.get(campo,[None]*len(horas)),index=horas,dtype=float).reindex(seleccion)

        for h in horizontes:
            esperadas=pd.date_range(h['inicio']+pd.Timedelta(hours=1),h['fin'],freq='h')
            lluvia=p.reindex(esperadas); runoff=r.reindex(esperadas)
            validas=int(lluvia.notna().sum())
            incertidumbres=list(meta.get('problemas_variables_modelo',[]))
            if validas<h['horas']:
                incertidumbres.append(f"Lluvia: {validas}/{h['horas']} horas válidas; el horizonte no está completo.")
            if int(runoff.notna().sum())<h['horas']:
                incertidumbres.append('Escurrimiento modelado incompleto en este horizonte.')
            bloques=[]
            # Every candidate contains exactly 72 hours within its own horizon.
            # Soil and runoff belong to that same event; maxima from other days are not paired.
            for fin in esperadas[71:]:
                inicio=fin-pd.Timedelta(hours=72)
                fechas=pd.date_range(inicio+pd.Timedelta(hours=1),fin,freq='h')
                pp=p.reindex(fechas); rr=r.reindex(fechas)
                if not pp.notna().all():
                    continue
                max24=float(pp.rolling(24,min_periods=24).sum().max())
                p72=float(pp.sum())
                r72=float(rr.sum()) if rr.notna().all() else None
                valores=suelo.loc[inicio] if inicio in suelo.index else pd.Series(dtype=float)
                humedad=float(valores.mean()) if int(valores.notna().sum())>=3 else None
                lluvia_fuerte=max24+1e-9>=REGLAS_MODELO_ZC['lluvia_24_mm'] or p72+1e-9>=REGLAS_MODELO_ZC['lluvia_72_mm']
                agravantes=[]
                if humedad is not None and humedad+1e-12>=REGLAS_MODELO_ZC['humedad_modelada_m3_m3']:
                    agravantes.append('humedad modelada de al menos tres capas ≥ 0,35 m³/m³')
                if r72 is not None and r72+1e-9>=REGLAS_MODELO_ZC['runoff_72_mm']:
                    agravantes.append('escurrimiento modelado ≥ 30 mm/72 h')
                bloques.append({'inicio':inicio,'fin':fin,'lluvia_72_mm':p72,'max_24_mm':max24,
                                'runoff_72_mm':r72,'humedad_inicio_m3_m3':humedad,
                                'lluvia_fuerte':lluvia_fuerte,'agravantes':agravantes,
                                'senal':2 if lluvia_fuerte and agravantes else 1 if lluvia_fuerte else 0})
            if not bloques:
                incertidumbres.append('No hay un bloque completo de 72 horas dentro del horizonte para evaluar la regla combinada.')
            elegido=max(bloques,key=lambda b:(b['senal'],b['max_24_mm'],b['lluvia_72_mm'])) if bloques else None
            if elegido and elegido['humedad_inicio_m3_m3'] is None:
                incertidumbres.append('Suelo del bloque sin tres capas verificadas; no se asume humedad ni saturación.')
            if elegido and elegido['lluvia_fuerte'] and (elegido['humedad_inicio_m3_m3'] is None or elegido['runoff_72_mm'] is None):
                incertidumbres.append('Uno o más agravantes de suelo/escurrimiento están sin confirmar; su ausencia no reduce la señal de lluvia.')
            max24s=lluvia.rolling(24,min_periods=24).sum()
            max72s=lluvia.rolling(72,min_periods=72).sum()
            # Complete 24h rain still requests vigilance when a 72h block is unavailable.
            lluvia24_fuerte=bool(max24s.notna().any() and max24s.max()+1e-9>=REGLAS_MODELO_ZC['lluvia_24_mm'])
            if lluvia24_fuerte and elegido is not None and elegido['senal']==0:
                elegido=None
                incertidumbres.append('La señal de lluvia pertenece a una ventana completa de 24 h; no hay un bloque completo de 72 h que contenga ese evento.')
            nivel=max(elegido['senal'] if elegido else 0,1 if lluvia24_fuerte else 0)
            ventana24_fin=max24s.idxmax() if max24s.notna().any() else None
            cape=auxiliar('cape','J/kg',esperadas)
            presion=auxiliar('pressure_msl','hPa',esperadas)
            viento=auxiliar('wind_speed_10m','km/h',esperadas)
            direccion=auxiliar('wind_direction_10m','°',esperadas)
            se=viento.notna()&direccion.between(90,180)&viento.gt(0)
            prob=auxiliar('precipitation_probability','%',esperadas)
            salida.append({**h,'localidad':nodo['localidad'],'partido':nodo['partido'],
                           'lat':nodo['lat'],'lon':nodo['lon'],'consulta':consulta,'fuente':API_URL,
                           'horas_lluvia_validas':validas,'horas_runoff_validas':int(runoff.notna().sum()),
                           'fin_datos':lluvia.dropna().index.max() if lluvia.notna().any() else None,
                           'completo':validas==h['horas'] and runoff.notna().all(),
                           'max_lluvia_24_mm':float(max24s.max()) if max24s.notna().any() else None,
                           'max_lluvia_72_mm':float(max72s.max()) if max72s.notna().any() else None,
                           'lluvia_previa_7d_mm':lluvia_previa,'bloque_evaluado':elegido,
                           'ventana24_fin':ventana24_fin,'senal':nivel,
                           'cape_max_J_kg':float(cape.max()) if cape.notna().any() else None,
                           'presion_min_hPa':float(presion.min()) if presion.notna().any() else None,
                           'viento_SE_max_kmh':float(viento[se].max()) if se.any() else None,
                           'horas_viento_SE':int(se.sum()),
                           'prob_lluvia_max_pct':float(prob.max()) if prob.notna().any() else None,
                           'incertidumbres':incertidumbres,'error':''})
    except (TypeError,ValueError,KeyError,OverflowError) as exc:
        salida=[]
        for h in horizontes:
            salida.append({**h,'localidad':nodo['localidad'],'partido':nodo['partido'],
                           'lat':nodo['lat'],'lon':nodo['lon'],'senal':None,'completo':False,
                           'horas_lluvia_validas':0,'horas_runoff_validas':0,'fin_datos':None,
                           'fuente':API_URL,'error':str(exc),'incertidumbres':['Meteorología del punto sin verificar.']})
    return salida


def analizar_rio_predictivo_zc(nombre,resultado,referencia=None):
    ref=_modelo_fecha_zc(referencia if referencia is not None else ahora())
    config=_zc_hidro_estaciones[nombre]
    hlista=horizontes_modelo_zc(ref)
    serie=resultado.get('serie_id')
    emision=_modelo_fecha_zc(resultado.get('emision'))
    vigente=not resultado.get('error') and serie==config['pronostico'] and emision is not None and -300<=(ref-emision).total_seconds()<=21600
    tabla=resultado.get('df',pd.DataFrame()).copy()
    if not tabla.empty and {'fecha','main'}.issubset(tabla.columns):
        tabla['fecha']=tabla.fecha.map(_modelo_fecha_zc)
        tabla['main']=pd.to_numeric(tabla['main'],errors='coerce')
        tabla=tabla[tabla.fecha.notna()&np.isfinite(tabla.main)].sort_values('fecha').drop_duplicates('fecha')
        tabla=tabla[(tabla.fecha>=ref)&(tabla.fecha<=ref+pd.Timedelta(hours=96))]
    else:
        tabla=pd.DataFrame(columns=['fecha','main'])
    salida=[]
    for h in hlista:
        local=tabla[(tabla.fecha>h['inicio'])&(tabla.fecha<=h['fin'])] if not tabla.empty else tabla
        incertidumbres=['La escala del pronóstico no está vinculada documentalmente con los umbrales observados 40/41; no se calcula cruce de alerta.']
        if not vigente:
            incertidumbres.append('Emisión del pronóstico fluvial vencida, futura o sin verificar.')
        if local.empty:
            incertidumbres.append('Sin pronóstico fluvial numérico para este horizonte; no se extrapola.')
        else:
            incertidumbres.append('El pronóstico INA sólo cubre las horas publicadas, hasta aproximadamente cuatro días.')
        maximo=local.loc[local.main.idxmax()] if not local.empty else None
        primero=local.iloc[0] if not local.empty else None
        final=local.iloc[-1] if not local.empty else None
        # Native-series change is a trend descriptor, never an observed-scale level.
        diferencia=float(final.main-primero.main) if len(local)>=2 else None
        ascenso=float(maximo.main-primero.main) if len(local)>=2 else None
        salida.append({**h,'estacion':nombre,'serie_pronostico':config['pronostico'],
                       'emision':emision,'fuente':resultado.get('url',_zc_hidro_url_pronostico(config['pronostico'])),
                       'vigente':vigente,'n_horas_publicadas':len(local),
                       'inicio_publicado':primero.fecha if primero is not None else None,
                       'fin_publicado':final.fecha if final is not None else None,
                       'maximo_m_serie_pronostico':float(maximo.main) if maximo is not None else None,
                       'fecha_maximo':maximo.fecha if maximo is not None else None,
                       'ascenso_maximo_desde_inicio_m':ascenso,
                       'cambio_tramo_m':diferencia,'tendencia':'Ascenso neto en el tramo publicado' if diferencia is not None and diferencia>0 else
                           'Descenso neto en el tramo publicado' if diferencia is not None and diferencia<0 else 'Sin cambio neto o tendencia sin verificar',
                       'comparacion_umbral_permitida':False,'incertidumbres':incertidumbres})
    return salida


def construir_modelo_predictivo_zc(nodos,payloads,pronosticos,rios,cap,shn,partes=None,clima=None,referencia=None,meteo_actual=None):
    ref=_modelo_fecha_zc(referencia if referencia is not None else ahora())
    horizontes=horizontes_modelo_zc(ref)
    atmosfera=[]
    for i,nodo in enumerate(nodos):
        payload=payloads[i] if isinstance(payloads,list) and i<len(payloads) else {}
        atmosfera.extend(analizar_atmosfera_predictiva_zc(nodo,payload,ref))
    fluviales=[]
    for nombre in _zc_hidro_estaciones:
        fluviales.extend(analizar_rio_predictivo_zc(nombre,pronosticos.get(nombre,{}),ref))
    alertas=[]
    for a in atmosfera:
        if not a.get('senal'):
            continue
        b=a.get('bloque_evaluado')
        agravada=a['senal']==2
        motivos=[]
        if b:
            motivos.append(f"Lluvia prevista del bloque: {b['max_24_mm']:.1f} mm/24 h y {b['lluvia_72_mm']:.1f} mm/72 h.")
            motivos.extend(b['agravantes'])
        else:
            motivos.append(f"Lluvia prevista: máximo de {a['max_lluvia_24_mm']:.1f} mm en un tramo completo de 24 horas.")
        idh=a['id']
        nivel=('ALERTA EXPERIMENTAL · POSIBLE INUNDACIÓN PLUVIAL' if idh=='corto' and agravada else
               'PREALERTA EXPERIMENTAL · CONDICIONES FAVORABLES AL ANEGAMIENTO' if idh=='medio' and agravada else
               'PERSPECTIVA DE VIGILANCIA · LLUVIAS Y ANEGAMIENTO' if idh=='largo' else 'VIGILANCIA · LLUVIA PREVISTA')
        inicio=b['inicio'] if b else a['ventana24_fin']-pd.Timedelta(hours=24)
        fin=b['fin'] if b else a['ventana24_fin']
        limites=list(a['incertidumbres'])+['Reglas provisionales sin calibración local; no se conocen profundidad, extensión ni capacidad del drenaje.']
        alertas.append({'localidad':a['localidad'],'partido':a['partido'],'horizonte':a['horizonte'],'id_horizonte':idh,
                        'mecanismo':'Lluvia + suelo/escurrimiento' if agravada else 'Lluvia prevista',
                        'nivel':nivel,'prioridad':2 if idh=='corto' and agravada else 1,
                        'inicio':inicio,'fin':fin,'anticipacion_horas':max(0.,(inicio-ref).total_seconds()/3600),
                        'motivos':motivos,'incertidumbres':limites,'fuentes':[a['fuente']],
                        'accion':'Prepará documentos y medicación, revisá desagües desde un lugar seco y coordiná asistencia. Reconfirmá zonas y accesos con Defensa Civil; no cruces agua.'})
    for f in fluviales:
        if f['vigente'] and f['n_horas_publicadas']>=2 and f['ascenso_maximo_desde_inicio_m'] is not None and f['ascenso_maximo_desde_inicio_m']>=0.01-1e-9:
            alertas.append({'localidad':f['estacion']+' · estación de referencia','partido':f['estacion'],
                            'horizonte':f['horizonte'],'id_horizonte':f['id'],'mecanismo':'Tendencia del pronóstico fluvial',
                            'nivel':'VIGILANCIA FLUVIAL · ASCENSO EN EL TRAMO PREVISTO','prioridad':1,
                            'inicio':f['inicio_publicado'],'fin':f['fin_publicado'],
                            'anticipacion_horas':max(0.,(f['inicio_publicado']-ref).total_seconds()/3600),
                            'motivos':[f"Ascenso máximo desde el primer valor futuro de la misma serie: +{f['ascenso_maximo_desde_inicio_m']:.2f} m; máximo previsto {f['fecha_maximo']:%d/%m %H:%M} ART. No demuestra desborde."],
                            'incertidumbres':f['incertidumbres'],'fuentes':[f['fuente']],
                            'accion':'Seguí alturas, nuevas corridas INA y avisos de la autoridad. Confirmá comunicación y acceso en costas e islas.'})
    # Observed high stages and declared water reports are current evidence, not future propagation.
    actual=evaluar_prevencion_inundaciones_zc(meteo_actual or {'nivel':None,'completo':False,'vigente':False},cap,rios,shn,partes,ref)
    incertidumbres_locales=list(actual['incertidumbres'])
    actuales=[m for m in actual['motivos'] if ('altura observada alcanza' in m or 'agua reportada' in m or 'acceso reportado cerrado' in m)]
    # A high observed river is an independent aggravating context for local forecast rain.
    # Do not turn forecast absolute levels into observed-scale heights.
    rios_altos=set()
    for rio in rios:
        try:
            if (rio.get('serie_id') in (40,41) and rio.get('observacion_vigente') is True
                    and rio.get('umbral_publicado') is True and np.isfinite(float(rio.get('altura_m')))
                    and np.isfinite(float(rio.get('alerta_m'))) and float(rio['altura_m'])>=float(rio['alerta_m'])):
                rios_altos.add('Zárate' if rio['serie_id']==40 else 'Campana')
        except (TypeError,ValueError,OverflowError):
            continue
    for a in list(alertas):
        if a['id_horizonte']=='corto' and a['partido'] in rios_altos and a['mecanismo']=='Lluvia prevista':
            a['nivel']='ALERTA EXPERIMENTAL · POSIBLE AFECTACIÓN POR LLUVIA Y CRECIDA'
            a['mecanismo']='Lluvia prevista + río actualmente alto'
            a['prioridad']=2
            a['motivos'].append('La estación del partido tiene una altura observada vigente que alcanza su referencia publicada de alerta.')
            a['incertidumbres'].append('La altura es actual; no se supone que persista ni determina remanso o inundación en cada barrio.')
    if actuales:
        alertas.append({'localidad':'Zárate–Campana · sectores indicados en los motivos','partido':'Zárate–Campana',
                        'horizonte':horizontes[0]['horizonte'],'id_horizonte':'corto','mecanismo':'Evidencia actual de río / parte local',
                        'nivel':'ATENCIÓN PREVENTIVA ALTA · EVIDENCIA ACTUAL','prioridad':2,
                        'inicio':ref,'fin':None,'anticipacion_horas':0.,'motivos':actuales,
                        'incertidumbres':['Dato actual: no se propaga al resto de los días del horizonte ni confirma una inundación futura.'],
                        'fuentes':[INA_REFERENCIAS_ZC_DOCUMENTACION],
                        'accion':'Corroborá sector, altura, acceso y asistencia con la autoridad local; ante peligro para personas, 103 o 911.'})
    # CAP retains the official document's own interval and semantics in every horizon.
    feed=_modelo_fecha_zc(cap.get('fecha_feed')); consulta=_modelo_fecha_zc(cap.get('consultado'))
    canal=not cap.get('error') and all(f is not None and -300<=(ref-f).total_seconds()<=86400 for f in (feed,consulta))
    docs=cap.get('filas',[]) if isinstance(cap.get('filas'),list) else []
    reemplazados={str(r) for d in docs if d.get('status')=='Actual' and d.get('tipo_mensaje') in ('Cancel','Update')
                 and _estado_fecha_emision_cap(d,ref)=='Confirmada' for r in d.get('referencias',[])}
    for d in docs:
        if not canal or d.get('status')!='Actual' or d.get('tipo_mensaje') not in ('Alert','Update') or str(d.get('id')) in reemplazados or _estado_fecha_emision_cap(d,ref)!='Confirmada':
            continue
        nombres={normalizar_nombre(n['localidad']) for n in nodos}
        local=any(normalizar_nombre(n) in nombres for n in d.get('nodos',[])) or (
            not d.get('poligonos') and bool(re.search(r'\b(ZARATE|CAMPANA)\b',normalizar_nombre(' '.join(d.get('areas',[]))))))
        fenomeno=normalizar_nombre(str(d.get('fenomeno',''))+' '+str(d.get('titulo','')))
        inicio=_modelo_fecha_zc(d.get('desde')) or _modelo_fecha_zc(d.get('emision'))
        fin=_modelo_fecha_zc(d.get('hasta'))
        if not local or not any(p in fenomeno for p in ('LLUV','TORMENT','INUND','CRECIDA','DESBORD')) or inicio is None or fin is None or fin<=inicio or fin<=ref:
            continue
        for h in horizontes:
            if fin<=h['inicio'] or inicio>=h['fin']:
                continue
            alertas.append({'localidad':', '.join(d.get('nodos',[])) or 'Área local indicada por SMN','partido':'Zárate–Campana',
                            'horizonte':h['horizonte'],'id_horizonte':h['id'],'mecanismo':'Aviso oficial SMN',
                            'nivel':'AVISO OFICIAL SMN · '+str(d.get('fenomeno','')),
                            'prioridad':2 if d.get('severidad_cap') in ('Severe','Extreme') else 1,
                            'inicio':max(inicio,h['inicio']),'fin':min(fin,h['fin']),
                            'anticipacion_horas':max(0.,(inicio-ref).total_seconds()/3600),
                            'motivos':['Conserva el fenómeno, área, severidad y período del documento oficial. Un aviso de lluvia/tormenta no confirma una inundación.'],
                            'incertidumbres':['Cobertura CAP parcial: revisar todos los avisos oficiales.'] if any(cap.get(k) for k in ('fallos','truncado','fechas_no_confirmadas_locales','replacements_no_confirmados')) else [],
                            'fuentes':[d.get('fuente') or SMN_CAP_FEED],'accion':'Consultá el aviso original y seguí sus recomendaciones para el área y horario indicados.'})
    resumen=[]
    for h in horizontes:
        aa=[a for a in atmosfera if a['id']==h['id']]
        mensajes=[a for a in alertas if a['id_horizonte']==h['id']]
        completas=sum(bool(a.get('completo')) for a in aa)
        con_datos=sum(a.get('horas_lluvia_validas',0)>0 for a in aa)
        limites=['Cobertura espacial: puntos aproximados; no determina calles, parcelas o profundidad.']
        inicio_shn=_modelo_fecha_zc(shn.get('inicio')); fin_shn=_modelo_fecha_zc(shn.get('fin'))
        contexto_shn=not shn.get('error') and inicio_shn is not None and fin_shn is not None and max(inicio_shn,h['inicio'])<min(fin_shn,h['fin'])
        limites.append('Contexto SHN disponible sólo durante su período publicado; no da una altura local.' if contexto_shn else 'Sin boletín SHN que cubra este horizonte completo; no se extrapola el estuario.')
        if h['id']!='corto':
            limites.append('No hay pronóstico local del río para todo el horizonte; el alcance INA publicado se muestra por separado.')
        limites.append('La menor precisión a mayor plazo impide presentar una alerta puntual de inundación en días 8–15 o meses.')
        limites.extend(incertidumbres_locales)
        estado_h=max(mensajes,key=lambda a:a['prioridad'])['nivel'] if mensajes else (
            'VERIFICACIÓN PENDIENTE · COBERTURA O EVIDENCIA LOCAL INCOMPLETA' if completas<len(nodos) or incertidumbres_locales else
            'SIN DISPARADOR EN VARIABLES EVALUADAS · MANTENER VIGILANCIA')
        resumen.append({**h,'estado':estado_h,
                        'cobertura':f'{con_datos}/{len(nodos)} puntos con datos · {completas}/{len(nodos)} con toda la ventana',
                        'senal_maxima':max((a['prioridad'] for a in mensajes),default=None),
                        'limites':limites,'n_alertas':len(mensajes)})
    clima=clima if isinstance(clima,dict) else {}
    clima_estado={'estado':'PERSPECTIVA ESTACIONAL · REQUIERE INTERPRETACIÓN DEL PRODUCTO VIGENTE',
                  'descripcion':'SMN trimestral y perspectivas de cuenca INA sirven para planificar. La categoría local no está extraída ni validada automáticamente; no se genera una alarma de evento ni se extrapolan alturas del río a meses.',
                  'fuentes':['https://www.smn.gob.ar/pronostico-trimestral','https://www.ina.gob.ar/alerta/index.php'],
                  'informe_smn_disponible':bool(clima and not clima.get('error')),
                  **resumen_trimestral_modelo_zc(clima,ref)}
    estado_general=max(alertas,key=lambda a:a['prioridad'])['nivel'] if alertas else (
        'VERIFICACIÓN PENDIENTE · FUENTES LOCALES INCOMPLETAS' if incertidumbres_locales or any(a.get('senal') is None for a in atmosfera) else
        'SIN DISPARADOR EN VARIABLES EVALUADAS · REVISAR COBERTURA Y FUENTES')
    return {'modelo_version':MODELO_PREDICTIVO_ZC_VERSION,'emision':ref,'base_ventanas':horizontes[0]['inicio'],
            'estado_general':estado_general,'incertidumbres':incertidumbres_locales,
            'alertas':sorted(alertas,key=lambda a:(-a['prioridad'],str(a['inicio']),a['localidad'])),
            'horizontes':resumen,'atmosfera':atmosfera,'rios':fluviales,'clima':clima_estado,
            'reglas':dict(REGLAS_MODELO_ZC),'calibracion_local':False,
            'metodo':['Modelo de reglas provisionales; no es un modelo hidráulico calibrado ni una alerta oficial.',
                      'Regla pluvial: un mismo bloque completo de 72 h con ≥50 mm en 24 h o ≥100 mm en 72 h, más humedad de al menos tres capas ≥0,35 m³/m³ o escurrimiento ≥30 mm/72 h.',
                      'Sólo el corto plazo puede mostrar alerta experimental; mediano usa prealerta y extendido vigilancia. Lluvia sola conserva vigilancia.',
                      'CAPE, presión y viento aportan contexto atmosférico; no prueban inundación ni multiplican la puntuación. La probabilidad de lluvia no es probabilidad de inundación.',
                      'Ríos: tendencia dentro de cada serie publicada y evidencia observada actual por separado; sin trasladar ceros ni extrapolar más allá de las horas INA.',
                      'Lluvia fuerte de corto plazo y río observado actualmente sobre su referencia del mismo partido forman una señal combinada; no se calcula cuánto subirá el agua por el drenaje.',
                      'Puntos que comparten una celda ECMWF no son observaciones independientes ni votos de confianza.',
                      'La sudestada necesita pronóstico hidrodinámico y cotas locales; se conserva el boletín SHN y no se deduce una altura local sólo del viento.',
                      'Las reglas requieren calibración con impactos locales y evaluación independiente de anticipación, fallos y falsas alarmas.']}


MODELO_HORIZONTES_ZC = (
    {'horizonte':'0–72 h','uso':'Alerta experimental de corto plazo',
     'alcance':'Atmósfera y fuentes fluviales disponibles, con sus propias fechas.'},
    {'horizonte':'72–168 h','uso':'Planificación de los días 4–7',
     'alcance':'Pronóstico atmosférico; el pronóstico local del río sólo puede cubrir hasta 96 h.'},
    {'horizonte':'168–360 h','uso':'Tendencia de los días 8–15',
     'alcance':'Pronóstico atmosférico de mayor incertidumbre; sin pronóstico fluvial local a ese plazo.'},
)


def _modelo_horizontes_texto(valor, vacio='Sin información confirmada'):
    if valor is None:
        return vacio
    if isinstance(valor,(float,np.floating)) and not np.isfinite(valor):
        return vacio
    if isinstance(valor,dict):
        return '; '.join(str(k).replace('_',' ')+': '+_modelo_horizontes_texto(v,vacio) for k,v in valor.items()) or vacio
    if isinstance(valor,(list,tuple)):
        return ' · '.join(_modelo_horizontes_texto(x,'') for x in valor if x is not None) or vacio
    texto=str(valor).strip()
    return texto if texto else vacio


def _modelo_horizontes_fecha(valor):
    fecha=_ui_fecha_local(valor)
    return fecha.strftime('%d/%m/%Y %H:%M ART') if fecha is not None else 'Hora sin confirmar'


def _modelo_horizontes_json_seguro(valor):
    import math
    from datetime import datetime,date
    if valor is None or valor is pd.NaT:
        return None
    if isinstance(valor,(str,bool)):
        return valor
    if isinstance(valor,(np.bool_,)):
        return bool(valor)
    if isinstance(valor,(int,np.integer)):
        return int(valor)
    if isinstance(valor,(float,np.floating)):
        return float(valor) if math.isfinite(float(valor)) else None
    if isinstance(valor,(datetime,date,pd.Timestamp)):
        return valor.isoformat()
    if isinstance(valor,dict):
        return {str(k):_modelo_horizontes_json_seguro(v) for k,v in valor.items()}
    if isinstance(valor,(list,tuple,np.ndarray)):
        return [_modelo_horizontes_json_seguro(x) for x in valor]
    if isinstance(valor,pd.DataFrame):
        return _modelo_horizontes_json_seguro(valor.to_dict('records'))
    return str(valor)


def _modelo_horizontes_tabla_metricas(registros):
    if not isinstance(registros,(list,tuple)):
        return pd.DataFrame()
    filas=[]
    for registro in registros:
        if not isinstance(registro,dict):
            continue
        fila={}
        for clave,valor in registro.items():
            if isinstance(valor,(dict,list,tuple)):
                fila[clave]=_modelo_horizontes_texto(valor)
            elif isinstance(valor,(float,np.floating)) and not np.isfinite(valor):
                fila[clave]=None
            else:
                fila[clave]=valor
        filas.append(fila)
    return pd.DataFrame(filas)


# BEGIN DATOS VISIBLES ZC 1.5.2
# Presentación de datos del modelo: datos disponibles aunque no haya alertas.

def resolver_fuente_modelo_zc(consulta,fallback,nombre):
    try:
        resultado=consulta() if callable(consulta) else consulta.result()
        if not isinstance(resultado,dict):raise ValueError('Formato de fuente inválido')
        return resultado
    except Exception:
        return {**fallback,'error':'No se completó la consulta de '+nombre+'. Las otras fuentes conservan sus datos.'}


def _numero_visible_modelo_zc(valor,decimales=1,sufijo=''):
    if isinstance(valor,(bool,np.bool_)):return 'Sin dato'
    try:
        numero=float(valor)
        return f'{numero:.{decimales}f}'+sufijo if np.isfinite(numero) else 'Sin dato'
    except (ValueError,TypeError,OverflowError):return 'Sin dato'


def mostrar_datos_disponibles_modelo_zc(resultado):
    st.subheader('Datos disponibles · lluvia, suelo y pronóstico del río')
    st.caption('Una evaluación sin alertas puede tener datos completos. Cada variable conserva su valor, cobertura y fecha; una fuente ausente aparece como «Sin dato».')
    horizontes=resultado.get('horizontes') or []
    opciones=[h['id'] for h in horizontes if isinstance(h,dict) and h.get('id')]
    etiquetas={h['id']:h.get('horizonte',h['id']) for h in horizontes if isinstance(h,dict) and h.get('id')}
    if not opciones:
        st.info('Los horizontes todavía no tienen una evaluación disponible.')
        return
    if st.session_state.get('zc_modelo_horizonte_datos') not in opciones:
        st.session_state.pop('zc_modelo_horizonte_datos',None)
    horizonte=st.selectbox('Horizonte de los datos',opciones,format_func=lambda x:etiquetas[x],key='zc_modelo_horizonte_datos')
    atmosfera=[a for a in resultado.get('atmosfera',[]) if isinstance(a,dict) and a.get('id')==horizonte]
    max24=[a.get('max_lluvia_24_mm') for a in atmosfera if a.get('max_lluvia_24_mm') is not None]
    max72=[a.get('max_lluvia_72_mm') for a in atmosfera if a.get('max_lluvia_72_mm') is not None]
    c1,c2,c3=st.columns(3)
    c1.metric('Mayor acumulado previsto en 24 h',_numero_visible_modelo_zc(max(max24) if max24 else None,sufijo=' mm'))
    c2.metric('Mayor acumulado previsto en 72 h',_numero_visible_modelo_zc(max(max72) if max72 else None,sufijo=' mm'))
    c3.metric('Puntos con lluvia disponible',str(sum(a.get('horas_lluvia_validas',0)>0 for a in atmosfera))+'/'+str(len(atmosfera)))
    filas=[]
    for a in atmosfera:
        b=a.get('bloque_evaluado') or {}
        filas.append({'Referencia local':a.get('localidad'),'Máximo 24 h · mm':_numero_visible_modelo_zc(a.get('max_lluvia_24_mm')),
            'Máximo 72 h · mm':_numero_visible_modelo_zc(a.get('max_lluvia_72_mm')),
            'Antecedente 7 días · mm':_numero_visible_modelo_zc(a.get('lluvia_previa_7d_mm')),
            'Suelo al inicio del bloque · m³/m³':_numero_visible_modelo_zc(b.get('humedad_inicio_m3_m3'),3),
            'Escurrimiento del bloque 72 h · mm':_numero_visible_modelo_zc(b.get('runoff_72_mm')),
            'Horas de lluvia':str(a.get('horas_lluvia_validas',0))+'/'+str(a.get('horas',0)),
            'Horas de escurrimiento':str(a.get('horas_runoff_validas',0))+'/'+str(a.get('horas',0)),
            'Consulta':_modelo_horizontes_fecha(a.get('consulta')),
            'Hasta dónde hay datos':_modelo_horizontes_fecha(a.get('fin_datos')),
            'Estado de datos':a.get('error') or ('Ventana completa de lluvia y escurrimiento' if a.get('completo') else 'Ventana o variables parciales')})
    st.dataframe(pd.DataFrame(filas),hide_index=True,use_container_width=True)
    st.caption('Los máximos de lluvia se buscan dentro del horizonte elegido. Suelo y escurrimiento corresponden al mismo bloque de 72 horas evaluado; no se trasladan entre eventos. El extendido muestra sólo las horas realmente publicadas.')
    rios=[r for r in resultado.get('rios',[]) if isinstance(r,dict) and r.get('id')==horizonte]
    filas_rios=[{'Estación':r.get('estacion'),'Máximo previsto · escala de pronóstico (m)':_numero_visible_modelo_zc(r.get('maximo_m_serie_pronostico'),2),
        'Hora del máximo':_modelo_horizontes_fecha(r.get('fecha_maximo')),'Puntos publicados':r.get('n_horas_publicadas',0),
        'Emisión INA':_modelo_horizontes_fecha(r.get('emision')),
        'Último punto publicado':_modelo_horizontes_fecha(r.get('fin_publicado')),
        'Vigencia':('Pronóstico de hasta 6 horas' if r.get('vigente') else 'Corrida antigua o vigencia sin confirmar') if r.get('n_horas_publicadas') else 'Sin pronóstico para este plazo'} for r in rios]
    st.markdown('**Pronóstico fluvial por estación**')
    st.dataframe(pd.DataFrame(filas_rios),hide_index=True,use_container_width=True)
    st.caption('Una corrida antigua se conserva como contexto con su emisión y no activa señales automáticas. El pronóstico local del río no se extiende a días o meses que la fuente no publicó. Sus alturas no se comparan con otra escala sin equivalencia documentada.')

# END DATOS VISIBLES ZC 1.5.2

def mostrar_modelo_predictivo_zc(resultado):
    resultado=resultado if isinstance(resultado,dict) else {}
    st.header('🌊 Modelo integrado · vigilancia predictiva de inundaciones')
    st.caption('Cálculo de esta evaluación: '+_modelo_horizontes_fecha(resultado.get('emision'))+
               '. La emisión de cada fuente se conserva por separado en la evidencia.')
    estado=_modelo_horizontes_texto(resultado.get('estado_general'),'Evaluación pendiente de datos')
    if any(x in estado.upper() for x in ('ALERTA','ATENCIÓN','ATENCION')):
        st.warning('**'+estado+'**')
    else:
        st.info('**'+estado+'**')
    st.caption('Modelo experimental de reglas, con calibración local pendiente. Los resultados sirven para preparar medidas; no expresan una probabilidad de inundación ni una orden de evacuación. Lluvia, río y estuario conservan sus escalas y áreas de influencia.')
    mostrar_datos_disponibles_modelo_zc(resultado)

    alertas=[x for x in (resultado.get('alertas') or []) if isinstance(x,dict)]
    st.subheader('Lugar, período y mecanismo de cada señal')
    if alertas:
        tabla=pd.DataFrame([{
            'Referencia local':_modelo_horizontes_texto(a.get('localidad')),
            'Partido':_modelo_horizontes_texto(a.get('partido')),
            'Horizonte':_modelo_horizontes_texto(a.get('horizonte')),
            'Mecanismo':_modelo_horizontes_texto(a.get('mecanismo')),
            'Señal experimental':_modelo_horizontes_texto(a.get('nivel')),
            'Inicio de ventana':_modelo_horizontes_fecha(a.get('inicio')),
            'Fin de ventana':_modelo_horizontes_fecha(a.get('fin')),
            'Acción de preparación':_modelo_horizontes_texto(a.get('accion')),
        } for a in alertas])
        st.dataframe(tabla,hide_index=True,use_container_width=True,
                     column_config={'Acción de preparación':st.column_config.TextColumn(width='large')})
        with st.expander('Evidencia, incertidumbre y acción de una señal',expanded=True):
            previo=st.session_state.get('zc_modelo_alerta_detalle')
            if previo is not None and (not isinstance(previo,int) or not 0<=previo<len(alertas)):
                st.session_state.pop('zc_modelo_alerta_detalle',None)
            indice=st.selectbox('Señal para revisar',range(len(alertas)),
                format_func=lambda i:_modelo_horizontes_texto(alertas[i].get('localidad'))+' · '+
                    _modelo_horizontes_texto(alertas[i].get('horizonte'))+' · '+_modelo_horizontes_texto(alertas[i].get('mecanismo')),
                key='zc_modelo_alerta_detalle')
            alerta=alertas[indice]
            st.markdown('**'+_modelo_horizontes_texto(alerta.get('nivel'))+'**')
            st.caption('Ventana evaluada: '+_modelo_horizontes_fecha(alerta.get('inicio'))+' — '+_modelo_horizontes_fecha(alerta.get('fin'))+'. No es una hora confirmada de inicio de inundación.')
            st.markdown('**Evidencia que activa la señal**')
            motivos=alerta.get('motivos') or []
            for motivo in motivos:
                st.write('• '+_modelo_horizontes_texto(motivo))
            if not motivos:
                st.caption('Evidencia de activación no informada en este resultado.')
            st.markdown('**Qué falta comprobar**')
            dudas=alerta.get('incertidumbres') or []
            for duda in dudas:
                st.write('• '+_modelo_horizontes_texto(duda))
            if not dudas:
                st.caption('Las limitaciones generales del método siguen aplicándose.')
            st.info('Preparación: '+_modelo_horizontes_texto(alerta.get('accion')))
    else:
        st.info('Esta evaluación no produjo alertas de evento. Revisá la cobertura, las fechas y los límites de cada horizonte; los datos ausentes requieren verificación.')

    horizontes=[h for h in (resultado.get('horizontes') or []) if isinstance(h,dict)]
    st.subheader('Cobertura y alcance según el plazo')
    tabla_horizontes=pd.DataFrame([{
        'Horizonte':_modelo_horizontes_texto(h.get('horizonte')),
        'Desde':_modelo_horizontes_fecha(h.get('inicio')),
        'Hasta':_modelo_horizontes_fecha(h.get('fin')),
        'Estado':_modelo_horizontes_texto(h.get('estado')),
        'Cobertura disponible':_modelo_horizontes_texto(h.get('cobertura')),
        'Intensidad de preparación':{2:'Atención alta',1:'Vigilancia / preparación',0:'Vigilancia',None:'Sin clasificación confirmada'}.get(h.get('senal_maxima'),'Sin clasificación confirmada'),
        'Límites':_modelo_horizontes_texto(h.get('limites')),
    } for h in horizontes])
    if not tabla_horizontes.empty:
        st.dataframe(tabla_horizontes,hide_index=True,use_container_width=True)
    else:
        st.caption('Todavía no se recibió una evaluación de los horizontes.')
    st.caption('Los intervalos de evento son disjuntos: 0–72 h, 72–168 h y 168–360 h. En los días 4–7 el río sólo tiene cobertura parcial hasta 96 h; a los días 8–15 falta pronóstico fluvial local. La falta de esa fuente queda explícita.')

    clima=resultado.get('clima') if isinstance(resultado.get('clima'),dict) else {}
    st.subheader('Perspectiva estacional · período publicado por SMN')
    st.write('**'+_modelo_horizontes_texto(clima.get('estado'),'Contexto climático pendiente')+'**')
    st.write(_modelo_horizontes_texto(clima.get('descripcion'),'Revisá el trimestre y las leyendas del informe SMN disponible en Datos oficiales.'))
    st.caption('La perspectiva climática orienta preparación estacional. No asigna una fecha de inundación, y sus categorías no se convierten en probabilidades de inundación local.')
    if clima.get('informe_smn_disponible') or clima.get('referencia_documental_disponible'):
        st.write('**Trimestre del documento disponible:** '+_modelo_horizontes_texto(clima.get('periodo')))
        fecha_documento=_ui_fecha_local(clima.get('fecha_documento'))
        es_documental=clima.get('referencia_documental_disponible') and not clima.get('informe_smn_disponible')
        st.caption('Fecha de emisión identificada en el PDF: '+(fecha_documento.strftime('%d/%m/%Y')+' · sin hora identificada' if fecha_documento is not None else 'Sin confirmar')+(' · revisión documental: 14/10/2026 · sin hora guardada' if es_documental else ' · consulta: '+_modelo_horizontes_fecha(clima.get('fecha_consulta'))))
        if es_documental:
            st.warning('Referencia documental conservada. El servidor no descargó el PDF en esta consulta y no confirmó una edición mensual más reciente. Sus datos no activan alertas locales.')
            st.link_button('Abrir PDF oficial de la referencia SMN',clima['url_documento'],key='zc_modelo_clima_documental_pdf')
        estado_periodo={'vigente_mes_actual':'Trimestre que comienza este mes','vigente_iniciado_antes':'Incluye la fecha actual; comenzó en un mes anterior',
            'previsto':'Trimestre futuro','vencido':'Trimestre vencido; antecedente documental'}.get(clima.get('estado_documento'),'Período sin confirmar')
        st.caption('Estado del período: '+estado_periodo+'. El documento completo, sus mapas y leyendas están en Datos oficiales SMN.')
        if clima.get('estado_documento') == 'vigente_iniciado_antes':
            st.info('El período publicado aún incluye la fecha actual. Su emisión original no acredita una actualización de este mes ni extiende el pronóstico a los meses posteriores al trimestre indicado.')
    else:
        st.warning('Informe trimestral sin recuperar: '+_modelo_horizontes_texto(clima.get('error_consulta')))
    if clima.get('error_consulta') and clima.get('informe_smn_disponible'):
        st.warning('La última actualización del documento no se completó. Se conserva la edición disponible con su emisión original.')
    fuentes=clima.get('fuentes') or []
    if fuentes:
        from urllib.parse import urlparse
        for i,fuente in enumerate(fuentes):
            url=fuente.get('url') if isinstance(fuente,dict) else str(fuente)
            etiqueta=_modelo_horizontes_texto(fuente.get('organismo',fuente.get('nombre'))) if isinstance(fuente,dict) else ('SMN · perspectiva trimestral' if 'smn.gob.ar' in url else 'INA · perspectivas de cuenca')
            if isinstance(url,str) and urlparse(url).scheme=='https' and urlparse(url).hostname:
                st.link_button(etiqueta,url,key='zc_modelo_clima_fuente_'+str(i))
            else:
                st.caption(_modelo_horizontes_texto(fuente))

    with st.expander('Métricas atmosféricas y fluviales utilizadas',expanded=True):
        st.markdown('**Atmósfera por referencia local y horizonte**')
        filas_atmosfera=[]
        for a in resultado.get('atmosfera',[]):
            bloque=a.get('bloque_evaluado') or {}
            filas_atmosfera.append({'Referencia':a.get('localidad'),'Horizonte':a.get('horizonte'),
                'Lluvia · horas válidas':f"{a.get('horas_lluvia_validas',0)}/{a.get('horas',0)}",
                'Máximo 24 h · mm':a.get('max_lluvia_24_mm'),'Máximo 72 h · mm':a.get('max_lluvia_72_mm'),
                'Antecedente modelado 7 días · mm':a.get('lluvia_previa_7d_mm'),
                'Suelo al inicio del bloque · m³/m³':bloque.get('humedad_inicio_m3_m3'),
                'Escurrimiento del bloque 72 h · mm':bloque.get('runoff_72_mm'),
                'Inicio del bloque':_modelo_horizontes_fecha(bloque.get('inicio')),
                'Fin del bloque':_modelo_horizontes_fecha(bloque.get('fin')),
                'CAPE máximo · J/kg':a.get('cape_max_J_kg'),'Presión mínima · hPa':a.get('presion_min_hPa'),
                'Viento E–S máximo · km/h':a.get('viento_SE_max_kmh'),
                'Consulta de fuente':_modelo_horizontes_fecha(a.get('consulta')),
                'Por verificar':_modelo_horizontes_texto(a.get('incertidumbres'),'Sin faltantes adicionales en la grilla'),
                'Estado de datos':a.get('error') or ('Grilla completa' if a.get('completo') else 'Grilla parcial')})
        atmosfera=pd.DataFrame(filas_atmosfera)
        if atmosfera.empty:
            st.caption('Sin métricas atmosféricas recibidas.')
        else:
            st.dataframe(atmosfera,hide_index=True,use_container_width=True)
        st.markdown('**Río por estación y horizonte**')
        filas_rios=[]
        for r in resultado.get('rios',[]):
            filas_rios.append({'Estación':r.get('estacion'),'Horizonte':r.get('horizonte'),
                'Emisión INA':_modelo_horizontes_fecha(r.get('emision')),
                'Puntos publicados':r.get('n_horas_publicadas'),
                'Inicio publicado':_modelo_horizontes_fecha(r.get('inicio_publicado')),
                'Fin publicado':_modelo_horizontes_fecha(r.get('fin_publicado')),
                'Máximo · m de la serie de pronóstico':r.get('maximo_m_serie_pronostico'),
                'Hora del máximo':_modelo_horizontes_fecha(r.get('fecha_maximo')),
                'Ascenso máximo desde primer valor · m':r.get('ascenso_maximo_desde_inicio_m'),
                'Estado':r.get('tendencia') if r.get('vigente') else 'Pronóstico sin vigencia confirmada',
                'Por verificar':_modelo_horizontes_texto(r.get('incertidumbres'))})
        rios=pd.DataFrame(filas_rios)
        if rios.empty:
            st.caption('Sin métricas de pronóstico fluvial recibidas.')
        else:
            st.dataframe(rios,hide_index=True,use_container_width=True)
        st.caption('Las alturas de pronóstico no se comparan con referencias de otra escala sin equivalencia documentada. Las fechas de fuente y cobertura forman parte de la interpretación.')
    with st.expander('Método y validación del modelo integrado',expanded=False):
        for item in resultado.get('metodo') or []:
            st.write('• '+_modelo_horizontes_texto(item))
        if not resultado.get('calibracion_local',False):
            st.caption('Calibración local pendiente. Se necesitan episodios y controles independientes para medir anticipación, aciertos y falsas alarmas; no se publican métricas inventadas de desempeño.')
        st.dataframe(pd.DataFrame(MODELO_HORIZONTES_ZC),hide_index=True,use_container_width=True)

    exportacion=_modelo_horizontes_json_seguro(resultado)
    st.download_button('Descargar evaluación integrada y evidencia',json.dumps(exportacion,ensure_ascii=False,indent=2,allow_nan=False),
                       'modelo_predictivo_zarate_campana.json','application/json',key='zc_modelo_export')


def actualizar_fuentes_zc():
    """Renueva las consultas públicas y conserva los archivos aportados por el usuario."""
    st.cache_data.clear()
    st.session_state['sinarame_visor_revision'] = st.session_state.get('sinarame_visor_revision', 0) + 1
    for clave in ('df_alerta', 'raw_ecmwf', 'df_operativo', '_zc_meteo_ultimo_intento',
                  'zc_relieve', 'ficha_sat_catalogo','zc_ina_observaciones_guardadas',
                  'zc_alturas_locales_resultado','zc_portada_contexto',
                  'zc_trimestral_ultimo_intento',
                  'zc_cuenca_resultado','zc_cuenca_decision','zc_cuenca_hist_catalogo','zc_cuenca_hist_resultados'):
        st.session_state.pop(clave, None)
    informe = st.session_state.get('ficha_trimestral')
    if isinstance(informe, dict) and not informe.get('aportado_por_usuario'):
        st.session_state.pop('ficha_trimestral', None)


def mostrar_resumen_meteorologico_zc(df):
    st.subheader('Meteorología · datos de las diez referencias locales')
    st.caption('Condiciones modeladas por ECMWF / Open-Meteo. Los datos y las fechas de cada variable se conservan en el análisis completo de la localidad.')
    if df.empty:
        st.warning('No hay datos meteorológicos recuperados. Consultá las demás solapas y volvé a actualizar.')
        return
    filas=[]
    for _,r in df.iterrows():
        filas.append({'Localidad':r.get('localidad'),'Temperatura':_ui_formato_metrica(r.get('temperatura'),1,' °C'),
                      'Humedad relativa':_ui_formato_metrica(r.get('humedad_relativa'),0,' %'),
                      'Viento':_ui_formato_metrica(r.get('viento'),1,' km/h'),
                      'Suelo · contenido volumétrico':_ui_formato_metrica(r.get('humedad_suelo_promedio'),3,' m³/m³'),
                      'Lluvia prevista 24 h':_ui_formato_metrica(r.get('lluvia_futura_24'),1,' mm'),
                      'Lluvia prevista 72 h':_ui_formato_metrica(r.get('lluvia_futura_72'),1,' mm'),
                      'Índice meteorológico':r.get('nivel','SIN DATOS'),
                      'Cobertura':r.get('estado_datos','Sin confirmar')})
    st.dataframe(pd.DataFrame(filas),hide_index=True,use_container_width=True)
    st.markdown('[Tiempo y variables del modelo](#condiciones-meteorologicas-del-modelo) · [Suelo](#estado-del-suelo) · [Lluvia y escurrimiento](#precipitacion-y-runoff) · [Pronóstico diario](#pronostico-extendido-15-dias) · [Historial](#historial)')


def cargar_red_integrada_zc():
    import red_integrada as red
    if getattr(red,'VERSION_RED',None) != '2026-10-17.2':
        red=importlib.reload(red)
    return red


def mostrar_conexion_portada_zc():
    """Presentación breve del mismo informe y estado que utiliza Red integrada."""
    red = cargar_red_integrada_zc()
    resumen = red.resumen_publico_red(red.consultar_red_integrada())
    enlace = '[Abrir ALA](https://alerta-litoral-agro.streamlit.app/)'
    if resumen['estado'] == 'sin_confirmar':
        st.warning('Conexión con ALA sin confirmar. Revisá la fecha de cada dato antes de usarlo. ' + enlace)
        return
    edad = resumen.get('edad_horas')
    antiguedad = f" · hace {max(0, round(edad * 60))} min" if edad is not None else ''
    st.caption('Red con ALA · informe común: ' + red.fecha_publica(resumen['generated_at']) +
               antiguedad + f" · {resumen['nodos']} puntos · " + enlace)
    if resumen['estado'] == 'antiguo':
        st.warning('El informe compartido está vencido. Revisá su actualización en Red integrada.')
    elif resumen['prueba']:
        st.info('Informe de comprobación: no confirma por sí solo un control horario automático activo.')
    elif not resumen['control_reciente']:
        st.warning('Informe reciente; el control horario automático está por confirmar.')


def render_app():
    mostrar_hero_litoral()
    with st.sidebar:
        vigilar_actualizacion_meteorologica()
    try:
        mostrar_conexion_portada_zc()
    except Exception:
        st.caption('Conexión con la red regional por confirmar. Revisá el informe y su fecha en Red integrada.')
    firma_actual=firma_cobertura()
    if st.session_state.get('firma_cobertura')!=firma_actual:
        for clave in ('df_alerta','raw_ecmwf','df_operativo','firma_historial_operativo','ficha_localidad','localidad_seleccionada'):
            st.session_state.pop(clave,None)
        st.session_state['firma_cobertura']=firma_actual


    # ============================================================
    # SMN — DATOS EN DIRECTO
    # ============================================================

    tab_agro, tab_red, tab_modelo, tab_radar, tab_smn, tab_fuentes, tab_enos, tab_territorio, tab_historia, tab_cuenca = st.tabs([
        "🌧️ Alerta local", "🌐 Red integrada", "🌊 Modelo de inundaciones", "📡 Radar regional", "🇦🇷 Datos oficiales SMN",
        "🌱 Suelo y ríos", "🌊 El Niño / La Niña", "🗺️ Territorio y accesos", "📘 Método y validación local", "🏞️ Cuenca del Paraná",
    ])
    with tab_red:
        try:
            cargar_red_integrada_zc().mostrar_red_integrada(st, repository="FedericoIeraci-cell/Alerta-Litoral", app_actual="zc")
        except Exception:
            st.warning("No se pudo cargar la información compartida en esta consulta. Los paneles regionales siguen disponibles; no se confirma el estado de la red.")
    with tab_radar:
        mostrar_radar_smn()
    with tab_smn:
        mostrar_datos_smn()

    # ============================================================
    # SIDEBAR
    # ============================================================

    with st.sidebar:

        st.header(
            "⚙️ Control"
        )

        actualizar = st.button(
            "🔄 Actualizar datos",
            key="zc_actualizar_todas_fuentes",
            use_container_width=True,
        )

        if actualizar:
            actualizar_fuentes_zc()
            st.rerun()

        st.divider()

        st.markdown(
            """
    ### Fuentes

    **Meteorología principal**
    - Open-Meteo
    - ECMWF IFS / Open-Meteo
    - Precipitación / lluvia / chaparrones
    - Humedad y temperatura del suelo
    - Runoff
    - Probabilidad de precipitación
    - Viento y ráfagas
    - CAPE / VPD
    - Presión / nubosidad

    **Vigilancia satelital**
    - NOAA / GOES-19 ABI
    - GeoColor
    - Sector Sudamérica Sur

    **Fuentes meteorológicas oficiales**
    - SINARAME: visor de radares y mosaicos
    - SMN: alertas CAP, avisos y observaciones regionales
    - SMN: pronóstico local y perspectiva trimestral

    **Suelo e hidrología**
    - INTA SEPA: suelo, excedentes y NDVI
    - INA: alturas y pronóstico local, con fecha y estación
    - INA: Alto Paraná, Iguazú, Paraná medio y boletines de cuenca
    - EBY: operación de Yacyretá, afluencias y vertidos reportados
    - SHN: contexto mareológico del Río de la Plata con validez
    - NOAA CPC: ENOS (RONI)

    **Territorio**
    - DEM Copernicus / IGN
    - Recursos y accesos declarados con fuente y vigencia
    - Partes locales de agua y accesos con vencimiento
    - Sin inventario local confirmado de refugios o caminos
    """
        )

        st.divider()

        st.markdown(
            """
    ### Índice meteorológico

    🟢 **VERDE**

    🟡 **AMARILLO**

    🔴 **ROJO**

    ⚪ **SIN DATOS**
    """
        )


    with tab_agro:
        # ============================================================
        # DATOS
        # ============================================================

        if (
            actualizar
            or "df_alerta" not in st.session_state
        ):

            with st.spinner(
                "Consultando datos meteorológicos de ECMWF..."
            ):

                raw_ecmwf = obtener_datos_ecmwf()
                st.session_state['_zc_meteo_ultimo_intento'] = ahora().isoformat()

                raw_ecmwf = (
                    list(raw_ecmwf)
                    if isinstance(
                        raw_ecmwf,
                        list,
                    )
                    else []
                )

                if len(raw_ecmwf) < len(NODOS):

                    raw_ecmwf.extend(
                        [
                            {
                                "error":
                                "Respuesta incompleta de Open-Meteo"
                            }
                        ]
                        * (
                            len(NODOS)
                            - len(raw_ecmwf)
                        )
                    )

                raw_ecmwf = raw_ecmwf[
                    :len(NODOS)
                ]

                resultados = [
                    procesar_nodo(
                        nodo,
                        datos,
                    )
                    for nodo, datos
                    in zip(
                        NODOS,
                        raw_ecmwf,
                    )
                ]

                df_alerta = pd.DataFrame(
                    resultados
                )

                st.session_state[
                    "df_alerta"
                ] = df_alerta

                st.session_state[
                    "raw_ecmwf"
                ] = raw_ecmwf


        else:

            df_alerta = st.session_state[
                "df_alerta"
            ]

            if (
                "raw_ecmwf"
                not in st.session_state
            ):

                st.session_state[
                    "raw_ecmwf"
                ] = obtener_datos_ecmwf()

            raw_ecmwf = st.session_state[
                "raw_ecmwf"
            ]


        df_alerta = integrar_semaforo(df_alerta)
        localidades=sorted(df_alerta.localidad.tolist())
        localidad_seleccionada=None
        if localidades:
            if st.session_state.get('localidad_detalle') not in localidades:
                st.session_state.pop('localidad_detalle',None)
            destacada=localidad_prioritaria(df_alerta)
            localidad_seleccionada=st.selectbox('Seleccionar localidad',localidades,
                index=localidades.index(destacada) if destacada in localidades else 0,key='localidad_detalle',
                help='Elegí el punto más cercano. Son referencias del modelo; no certifican el estado de cada calle, isla o parcela.')
        portada=st.container()
        with tab_modelo:
            try:
                mostrar_prevencion_inundaciones_zc(df_alerta)
                mostrar_vigencia_para_respuesta(df_alerta)
            except Exception:
                st.session_state.pop('zc_modelo_predictivo_resultado',None)
                st.session_state.pop('zc_cuenca_decision',None)
                st.header('🌊 Modelo de inundaciones · verificación pendiente')
                st.error('No se pudo completar el panel de inundaciones. Revisá la vigencia de sus fuentes y volvé a actualizar; los demás datos se muestran en sus solapas.')
        with tab_cuenca:
            try:
                cuenca=st.session_state.get('zc_cuenca_resultado') or consultar_cuenca_parana_zc()
                st.session_state['zc_cuenca_resultado']=cuenca
                decision=construir_decision_cuenca_zc(st.session_state.get('zc_modelo_predictivo_resultado',{}),st.session_state.get('zc_prevencion_resultado',{}),cuenca,ahora())
                st.session_state['zc_cuenca_decision']=decision
                mostrar_cuenca_parana_zc({'emision':ahora().isoformat(),'cuenca':cuenca,'decision':decision,'limites':cuenca.get('incertidumbres',[]),'fuentes':cuenca.get('fuentes',[])})
                mostrar_historicos_cuenca_zc()
            except Exception:
                st.session_state.pop('zc_cuenca_decision',None)
                st.header('Cuenca del Paraná · verificación pendiente')
                st.error('No se pudo completar la consulta de cuenca. Las restantes solapas conservan sus datos; revisá los boletines originales y volvé a actualizar.')
                st.link_button('Boletines oficiales INA',CUENCA_INA_INDICE_ZC,key='zc_cuenca_error_ina')
        alturas=st.session_state.get('zc_alturas_locales_resultado')
        if not isinstance(alturas,dict):
            try:
                alturas=consultar_alturas_locales_zc()
                st.session_state['zc_alturas_locales_resultado']=alturas
            except Exception:
                alturas={'observaciones':{},'referencias':{}}
        if localidad_seleccionada:
            from portada_zc import construir_portada_zc,mostrar_portada_zc
            row_acciones=df_alerta[df_alerta.localidad.eq(localidad_seleccionada)].iloc[0]
            partido=row_acciones.get('partido')
            config=_zc_hidro_estaciones.get(partido)
            rio=_resumen_rio_prevencion_zc(partido,config,alturas.get('observaciones',{}).get(partido,{}),
                alturas.get('referencias',{})) if config else {}
            contexto=st.session_state.get('zc_portada_contexto',{})
            resumen=construir_portada_zc(row_acciones,
                decision=st.session_state.get('zc_cuenca_decision'),
                modelo=st.session_state.get('zc_modelo_predictivo_resultado'),rio=rio,
                cap=contexto.get('cap'),cuenca=st.session_state.get('zc_cuenca_resultado'),referencia=ahora())
            with portada:
                mostrar_portada_zc(st,resumen)
        try:
            with st.expander('Alturas de ambos puertos · fuentes, referencias y evolución'):
                mostrar_alturas_locales_zc(alturas)
        except Exception:
            st.subheader('🌊 Altura del agua · Zárate y Campana')
