def _referencia_meteorologica(referencia_historica=None):
    referencia = (pd.Timestamp(referencia_historica) if referencia_historica is not None
                  else hora_actual_local_redondeada())
    if referencia.tzinfo is not None:
        referencia = referencia.tz_convert(TZ).tz_localize(None)
    if pd.isna(referencia) or referencia != referencia.floor('h'):
        raise ValueError('La referencia meteorológica debe ser una hora completa válida.')
    return referencia



def _validar_respuesta_meteorologica(nodo, datos, referencia):
    """Valida la celda, unidades y grilla antes de efectuar sumas o interpretar datos."""
    if not isinstance(datos, dict) or datos.get('error'):
        raise ValueError('La fuente no devolvió una respuesta meteorológica utilizable.')
    try:
        lat, lon = float(datos['latitude']), float(datos['longitude'])
        nlat, nlon = float(nodo['lat']), float(nodo['lon'])
    except (KeyError, TypeError, ValueError):
        raise ValueError('La respuesta no permite verificar las coordenadas de la celda.') from None
    if not np.isfinite([lat, lon, nlat, nlon]).all() or not (-90 <= lat <= 90 and -180 <= lon <= 180):
        raise ValueError('Las coordenadas de la celda son inválidas.')
    p1, p2 = np.radians([nlat, lat])
    dp, dl = np.radians([lat - nlat, lon - nlon])
    distancia = float(6371.0 * 2.0 * np.arcsin(np.sqrt(np.clip(
        np.sin(dp / 2.0) ** 2 + np.cos(p1) * np.cos(p2) * np.sin(dl / 2.0) ** 2, 0, 1))))
    if distancia > 40:
        raise ValueError('La celda devuelta está a más de 40 km del punto solicitado.')
    if (datos.get('timezone') not in ('America/Argentina/Buenos_Aires', 'America/Buenos_Aires')
            or datos.get('utc_offset_seconds') != -10800):
        raise ValueError('La zona horaria o el desplazamiento UTC de la respuesta no están verificados.')
    hourly, units = datos.get('hourly'), datos.get('hourly_units')
    if not isinstance(hourly, dict) or not isinstance(units, dict) or units.get('time') != 'iso8601':
        raise ValueError('Faltan la serie horaria o sus unidades verificables.')
    tiempos = hourly.get('time')
    if not isinstance(tiempos, list) or not tiempos:
        raise ValueError('La respuesta no contiene una grilla horaria utilizable.')
    try:
        horas = pd.DatetimeIndex(pd.to_datetime(tiempos, errors='coerce'))
        if horas.tz is not None:
            horas = horas.tz_convert(TZ).tz_localize(None)
    except (TypeError, ValueError):
        raise ValueError('Los horarios meteorológicos son inválidos o mezclan zonas horarias.') from None
    if horas.isna().any() or not horas.is_unique or not horas.is_monotonic_increasing:
        raise ValueError('Los horarios meteorológicos son inválidos, repetidos o están desordenados.')
    if (horas != horas.floor('h')).any() or (len(horas) > 1 and
            not np.all(np.diff(horas.asi8) == pd.Timedelta(hours=1).value)):
        raise ValueError('La grilla meteorológica no tiene pasos horarios continuos.')
    capas = ('soil_moisture_0_to_7cm', 'soil_moisture_7_to_28cm',
             'soil_moisture_28_to_100cm', 'soil_moisture_100_to_255cm')
    limpio = dict(hourly)
    limpio['time'] = [hora.isoformat() for hora in horas]
    for campo in ('precipitation', 'runoff') + capas:
        if campo in capas and campo not in hourly:
            limpio[campo] = [None] * len(horas)
            continue
        esperada = 'm³/m³' if campo in capas else 'mm'
        if units.get(campo) != esperada:
            raise ValueError('Una unidad principal no coincide con mm o m³/m³ según la variable.')
        valores = hourly.get(campo)
        if not isinstance(valores, list) or len(valores) != len(horas):
            raise ValueError('Una variable principal no coincide en longitud con la grilla horaria.')
        normalizados = []
        for valor in valores:
            if valor is None:
                normalizados.append(None)
                continue
            try:
                if isinstance(valor, bool):
                    raise ValueError()
                numero = float(valor)
            except (TypeError, ValueError):
                raise ValueError('Una variable principal contiene valores no numéricos.') from None
            if np.isnan(numero):
                normalizados.append(None)
            elif not np.isfinite(numero) or numero < 0 or (campo in capas and numero > 1):
                raise ValueError('Una variable principal contiene valores fuera de sus límites físicos.')
            else:
                normalizados.append(numero)
        limpio[campo] = normalizados
    fechas_suelo = []
    for campo in capas:
        valores = np.asarray(limpio[campo], dtype=float)
        posiciones = np.where((horas <= referencia) & np.isfinite(valores))[0]
        ultimo = horas[posiciones[-1]] if len(posiciones) else None
        if ultimo is not None and pd.Timedelta(0) <= referencia - ultimo <= pd.Timedelta(hours=3):
            fechas_suelo.append(ultimo)
        else:
            # No reutilizar como actual una capa cuyo último valor corresponde a días anteriores.
            limpio[campo] = [None if hora <= referencia else valor
                             for hora, valor in zip(horas, limpio[campo])]
    consulta = datos.get('_consulta_meteorologica')
    if consulta:
        try:
            fecha_consulta = pd.Timestamp(consulta)
            if fecha_consulta.tzinfo is None or fecha_consulta > pd.Timestamp(ahora()) + pd.Timedelta(minutes=5):
                raise ValueError()
            consulta = fecha_consulta.tz_convert(TZ).isoformat()
        except (TypeError, ValueError):
            raise ValueError('La hora de consulta de la fuente no es verificable.') from None
    else:
        consulta = None
    metadatos = {'consulta_meteorologica': consulta,
                 'referencia_datos': referencia.tz_localize(TZ).isoformat(),
                 'celda_lat': lat, 'celda_lon': lon, 'distancia_celda_km': round(distancia, 2),
                 'capas_humedad_vigentes': len(fechas_suelo),
                 'fecha_humedad_suelo': min(fechas_suelo).tz_localize(TZ).isoformat() if fechas_suelo else None,
                 'antiguedad_humedad_horas': float((referencia - min(fechas_suelo)) / pd.Timedelta(hours=1)) if fechas_suelo else None}
    limpio = _sanear_variables_meteorologicas_opcionales(limpio, len(horas))
    return {**datos, 'hourly': limpio}, horas, metadatos



def _suma_ventana_meteorologica(horas, valores, referencia, cantidad, futura=False):
    """Devuelve NaN si falta cualquier hora o valor: un dato ausente nunca es cero."""
    inicio = referencia if futura else referencia - pd.Timedelta(hours=cantidad)
    fin = referencia + pd.Timedelta(hours=cantidad) if futura else referencia
    esperadas = pd.date_range(inicio + pd.Timedelta(hours=1), fin, freq='h')
    if not isinstance(valores, (list, tuple, np.ndarray)) or len(valores) != len(horas):
        return np.nan, 0
    try:
        numeros = np.asarray(valores, dtype=float)
    except (TypeError, ValueError):
        return np.nan, 0
    mascara = (horas > inicio) & (horas <= fin)
    seleccion = numeros[mascara]
    validas = np.isfinite(seleccion) & (seleccion >= 0)
    completas = (len(seleccion) == cantidad and len(esperadas) == cantidad
                 and horas[mascara].equals(esperadas) and bool(validas.all()))
    return (float(seleccion.sum()) if completas else np.nan), int(validas.sum())



def _ui_formato_metrica(valor, decimales=1, sufijo=""):
    if isinstance(valor, (bool, np.bool_)):
        return "Sin dato"
    try:
        numero = float(valor)
    except (TypeError, ValueError, OverflowError):
        return "Sin dato"
    return f"{numero:.{decimales}f}{sufijo}" if np.isfinite(numero) else "Sin dato"


def tabla_variables_atmosfericas_zc(row):
    """Valores de presentación con unidades independientes; conserva los datos del modelo."""
    campos = [
        ('CAPE', 'Último valor disponible', 'cape', 0, 'J/kg'),
        ('CAPE máximo', 'Próximas 24 h', 'cape_max_24', 0, 'J/kg'),
        ('Probabilidad horaria de precipitación', 'Media de las próximas 24 h', 'prob_lluvia_24', 1, '%'),
        ('Probabilidad horaria de precipitación', 'Media de las próximas 72 h', 'prob_lluvia_72', 1, '%'),
        ('Viento máximo', 'Próximas 24 h', 'viento_max_24', 1, 'km/h'),
        ('Ráfaga máxima', 'Próximas 24 h', 'rafaga_max_24', 1, 'km/h'),
        ('Nubosidad total', 'Último valor disponible', 'nubosidad', 0, '%'),
        ('Nubosidad baja', 'Último valor disponible', 'nubosidad_baja', 0, '%'),
        ('Nubosidad media', 'Último valor disponible', 'nubosidad_media', 0, '%'),
        ('Nubosidad alta', 'Último valor disponible', 'nubosidad_alta', 0, '%'),
    ]
    return pd.DataFrame([{'Variable':nombre, 'Período':periodo,
                          'Valor':_ui_formato_metrica(row.get(campo), decimales), 'Unidad':unidad}
                         for nombre, periodo, campo, decimales, unidad in campos])


def _ui_direccion_viento(grados, texto):
    valor = _ui_formato_metrica(grados, 0, "°")
    return valor + " " + str(texto) if valor != "Sin dato" else valor


def _ui_fecha_local(valor):
    if valor is None or (isinstance(valor, str) and not valor.strip()):
        return None
    try:
        fecha = pd.Timestamp(valor)
        if pd.isna(fecha):
            return None
        return fecha.tz_localize(TZ) if fecha.tzinfo is None else fecha.tz_convert(TZ)
    except (ValueError, TypeError, OverflowError):
        return None


def _ui_consulta_necesita_refresco(ultimo_intento, referencia=None):
    fecha = _ui_fecha_local(ultimo_intento)
    if fecha is None:
        return False
    referencia = _ui_fecha_local(referencia if referencia is not None else ahora())
    edad = (referencia - fecha).total_seconds()
    return edad >= 300 or edad < -60


def _ui_invalidar_meteorologia():
    obtener_datos_ecmwf.clear()
    for clave in ('df_alerta', 'raw_ecmwf', 'df_operativo', '_zc_meteo_ultimo_intento'):
        st.session_state.pop(clave, None)


@st.fragment(run_every=300)
def vigilar_actualizacion_meteorologica():
    ultimo = st.session_state.get('_zc_meteo_ultimo_intento')
    datos_sin_marcador = ultimo is None and 'df_alerta' in st.session_state
    if datos_sin_marcador or _ui_consulta_necesita_refresco(ultimo):
        _ui_invalidar_meteorologia()
        st.rerun(scope='app')
    st.caption('La meteorología se vuelve a consultar cada cinco minutos mientras esta página está abierta y conectada. El pronóstico del río conserva su emisión y se revisa al actualizar la interfaz.')


def _ui_fechas_de_columna(df, columna, formato=None):
    if df is None or df.empty or columna not in df:
        return []
    fechas = []
    for valor in df[columna]:
        if formato and isinstance(valor, str):
            try:
                valor = datetime.strptime(valor, formato)
            except ValueError:
                continue
        fecha = _ui_fecha_local(valor)
        if fecha is not None:
            fechas.append(fecha)
    return fechas


def mostrar_fechas_meteorologia(df):
    def texto_rango(fechas):
        if not fechas:
            return 'Sin fecha confirmada'
        inicio, fin = min(fechas), max(fechas)
        a = inicio.strftime('%d/%m/%Y %H:%M:%S ART')
        return a if inicio == fin else a + ' — ' + fin.strftime('%d/%m/%Y %H:%M:%S ART')
    consultas = _ui_fechas_de_columna(df, 'consulta_meteorologica')
    calculos = _ui_fechas_de_columna(df, 'actualizado', '%d/%m/%Y %H:%M')
    referencias = _ui_fechas_de_columna(df, 'referencia_datos')
    st.caption('Consulta a la fuente: ' + texto_rango(consultas) +
               ' · Cálculo local del índice: ' + texto_rango(calculos))
    st.caption('Hora de referencia para las ventanas del modelo: ' + texto_rango(referencias) +
               '. La consulta, el cálculo y esa referencia no son la hora de emisión de la corrida.')
    ultimo_intento = _ui_fecha_local(st.session_state.get('_zc_meteo_ultimo_intento'))
    if not consultas and ultimo_intento is not None:
        st.caption('Último intento de consulta en esta sesión: ' + ultimo_intento.strftime('%d/%m/%Y %H:%M:%S ART') +
                   '. No confirma recepción de datos meteorológicos utilizables.')
    if calculos and any(not dato_vigente(fecha, 12) for fecha in calculos):
        st.warning('El cálculo mostrado está vencido. No hay un color meteorológico operativo para esos puntos; los valores conservados son antecedentes. Actualizá los datos.')


def _fecha_observacion_smn(valor):
    if isinstance(valor, (int, float, np.integer, np.floating)):
        if not np.isfinite(valor) or valor <= 0:
            return None
        try:
            fecha = pd.to_datetime(valor, unit='ms' if valor > 1e12 else 's', utc=True)
            return fecha.tz_convert(TZ)
        except (ValueError, TypeError, OverflowError):
            return None
    try:
        fecha = pd.Timestamp(valor)
        if pd.isna(fecha) or fecha.tzinfo is None:
            return None
        return fecha.tz_convert(TZ)
    except (TypeError, ValueError, OverflowError):
        return None


def _estado_observacion_smn(valor, referencia=None):
    fecha = _fecha_observacion_smn(valor)
    if fecha is None:
        return None, np.nan, 'Fecha sin confirmar'
    referencia = _ui_fecha_local(referencia if referencia is not None else ahora())
    edad = (referencia-fecha).total_seconds()/3600
    estado = 'Actual · hasta 3 h' if 0 <= edad <= 3 else ('Fecha futura · no actual' if edad < 0 else 'Contexto histórico · más de 3 h')
    return fecha, edad, estado


def _zc_hidro_pronostico_para_mostrar(resultado, referencia=None):
    if resultado.get('error'):
        return dict(resultado)
    referencia = _ui_fecha_local(referencia if referencia is not None else ahora())
    emision = _ui_fecha_local(resultado.get('emision'))
    if emision is None or emision > referencia + pd.Timedelta(minutes=5):
        return {**resultado, 'df':pd.DataFrame(), 'error':'La emisión de esta corrida no permite confirmar su vigencia.'}
    df = resultado.get('df', pd.DataFrame()).copy()
    if not {'fecha','main'}.issubset(df.columns):
        return {**resultado, 'df':pd.DataFrame(), 'error':'El pronóstico recibido no tiene horas y alturas verificables.'}
    fechas = df.fecha.map(_ui_fecha_local)
    valores = pd.to_numeric(df.main, errors='coerce')
    valido = fechas.map(lambda fecha:fecha is not None and referencia <= fecha <= referencia+pd.Timedelta(hours=96)) & np.isfinite(valores)
    df = df.loc[valido].copy()
    df['fecha'] = fechas.loc[valido]
    if df.empty:
        return {**resultado, 'df':df, 'atrasado':True,
                'error':'La corrida recibida ya no tiene horas futuras utilizables. No se presenta un máximo pasado como pronóstico; consultá una actualización en el INA.'}
    return {**resultado, 'df':df.sort_values('fecha'), 'atrasado':referencia-emision>pd.Timedelta(hours=6), 'error':''}


def _sanear_variables_meteorologicas_opcionales(hourly, cantidad):
    """Una variable auxiliar inválida queda ausente sin anular el índice principal."""
    campos = ('temperature_2m', 'apparent_temperature', 'dew_point_2m',
              'relative_humidity_2m', 'pressure_msl', 'surface_pressure',
              'cloud_cover', 'cloud_cover_low', 'cloud_cover_mid', 'cloud_cover_high',
              'wind_speed_10m', 'wind_gusts_10m', 'wind_direction_10m',
              'shortwave_radiation', 'cape', 'vapour_pressure_deficit',
              'evapotranspiration', 'et0_fao_evapotranspiration',
              'rain', 'showers', 'precipitation_probability', 'weather_code',
              'soil_temperature_0_to_7cm', 'soil_temperature_7_to_28cm',
              'soil_temperature_28_to_100cm', 'soil_temperature_100_to_255cm')
    porcentaje = {'relative_humidity_2m', 'cloud_cover', 'cloud_cover_low',
                  'cloud_cover_mid', 'cloud_cover_high', 'precipitation_probability'}
    no_negativas = {'pressure_msl', 'surface_pressure', 'wind_speed_10m', 'wind_gusts_10m',
                   'shortwave_radiation', 'cape', 'vapour_pressure_deficit',
                   'evapotranspiration', 'et0_fao_evapotranspiration', 'rain', 'showers'}
    salida = dict(hourly)
    for campo in campos:
        valores = hourly.get(campo)
        if (not isinstance(valores, (list, tuple, np.ndarray))
                or np.asarray(valores, dtype=object).ndim != 1 or len(valores) != cantidad):
            salida[campo] = [None] * cantidad
            continue
        limpios = []
        for valor in valores:
            try:
                if valor is None or isinstance(valor, bool):
                    raise ValueError()
                numero = float(valor)
                if not np.isfinite(numero):
                    raise ValueError()
                if campo in porcentaje and not 0 <= numero <= 100:
                    raise ValueError()
                if campo in no_negativas and numero < 0:
                    raise ValueError()
                if campo == 'wind_direction_10m' and not 0 <= numero <= 360:
                    raise ValueError()
                if campo == 'weather_code' and (not 0 <= numero <= 99 or not numero.is_integer()):
                    raise ValueError()
                limpios.append(numero)
            except (TypeError, ValueError):
                limpios.append(None)
        salida[campo] = limpios
    return salida


def mostrar_vigencia_para_respuesta(df):
    """Resume evidencia disponible sin convertirla en una habilitación de rescate."""
    st.subheader('Vigencia de las fuentes · apoyo al equipo de respuesta')
    filas = []
    validos = int(df['estado_datos'].eq('OK').sum()) if 'estado_datos' in df else 0
    consultas = _ui_fechas_de_columna(df, 'consulta_meteorologica')
    fecha = min(consultas) if consultas else None
    filas.append({'Fuente':'Meteorología modelada',
                  'Estado':f'{validos}/{len(NODOS)} puntos con datos completos',
                  'Fecha publicada o de consulta':fecha.strftime('%d/%m/%Y %H:%M ART') if fecha else 'Consulta sin confirmar',
                  'Interpretación':'La fecha es de consulta, no de emisión del modelo. Los puntos representan celdas regionales.'})
    cap = obtener_cap_litoral()
    feed = _ui_fecha_local(cap.get('fecha_feed'))
    ahora_local = pd.Timestamp(ahora())
    edad = (ahora_local - feed).total_seconds()/3600 if feed is not None else None
    incompleto = bool(cap.get('error') or cap.get('fallos') or cap.get('truncado') or cap.get('fechas_no_confirmadas_locales') or cap.get('replacements_no_confirmados'))
    vigente = not incompleto and edad is not None and 0 <= edad <= 24
    avisos = [f for f in cap.get('filas', []) if estado_vigencia_cap(f, datetime.now(timezone.utc)) in ('Vigente','Previsto')]
    estado = f'{len(avisos)} avisos locales en los documentos recibidos' if vigente else 'Vigencia o cobertura sin confirmar'
    filas.append({'Fuente':'SMN · avisos oficiales', 'Estado':estado,
                  'Fecha publicada o de consulta':feed.strftime('%d/%m/%Y %H:%M ART') if feed is not None else 'Publicación sin confirmar',
                  'Interpretación':'La coincidencia usa puntos aproximados y menciones de los partidos; no cubre todos los sectores de islas.'})
    imagen_sinarame = st.session_state.get('sinarame_ultimo_RMA2', {})
    fecha_sinarame = _ui_fecha_local(imagen_sinarame.get('fecha'))
    edad_sinarame = (ahora_local-fecha_sinarame).total_seconds()/60 if fecha_sinarame is not None else None
    consulta_radar = st.session_state.get('sinarame_resultado_consulta', {})
    estado_radar = ('Imagen recibida · hasta 30 min' if edad_sinarame is not None and 0 <= edad_sinarame <= 30 else
                    'Imagen antigua o con fecha por confirmar' if fecha_sinarame is not None else 'Sin imagen verificada')
    if consulta_radar.get('error') and fecha_sinarame is not None:
        estado_radar = 'Actualización fallida · imagen anterior con su fecha'
    filas.append({'Fuente':'SINARAME · radar Ezeiza RMA2', 'Estado':estado_radar,
                  'Fecha publicada o de consulta':fecha_sinarame.strftime('%d/%m/%Y %H:%M ART') if fecha_sinarame is not None else 'Imagen sin fecha confirmada',
                  'Interpretación':'Fecha del archivo radar. El mapa reproduce el encuadre observado en el visor oficial; no indica lluvia en mm/h ni seguridad operativa.'})
    radar_sinarame = st.session_state.get('sinarame_estado_visor', {})
    consulta_sinarame = _ui_fecha_local(radar_sinarame.get('consultado'))
    filas.append({'Fuente':'SINARAME · visor oficial',
                  'Estado':'Acceso al visor comprobado; imagen según fuente' if radar_sinarame.get('disponible') else 'Acceso sin comprobar desde la aplicación',
                  'Fecha publicada o de consulta':consulta_sinarame.strftime('%d/%m/%Y %H:%M ART') if consulta_sinarame is not None else 'Consulta sin confirmar',
                  'Interpretación':'Esta fecha sólo comprueba acceso al visor. La hora del eco y su actualidad se revisan en Fecha frame y Última actualización dentro del radar oficial.'})
    marcas_radar = []
    for clave in st.session_state:
        if str(clave).startswith('radar_smn_ultimo_'):
            recibido = st.session_state.get(clave, {})
            if isinstance(recibido, dict):
                fecha_radar = _ui_fecha_local(recibido.get('frame', {}).get('fecha'))
                if fecha_radar is not None:
                    marcas_radar.append(fecha_radar)
    ultima_radar = max(marcas_radar) if marcas_radar else None
    edad_radar = (ahora_local-ultima_radar).total_seconds()/60 if ultima_radar is not None else None
    filas.append({'Fuente':'SMN · radar alternativo',
                  'Estado':'Imagen obtenida en esta sesión' if edad_radar is not None and 0<=edad_radar<=30 else
                           'Imagen antigua o sin vigencia confirmada' if ultima_radar is not None else 'Sin imagen verificada en esta sesión',
                  'Fecha publicada o de consulta':ultima_radar.strftime('%d/%m/%Y %H:%M ART') if ultima_radar is not None else 'Imagen sin fecha confirmada',
                  'Interpretación':'Consultar Radar regional y los visores oficiales. La ausencia de imagen no informa ausencia de lluvia.'})
    for ciudad, config in _zc_hidro_estaciones.items():
        resultado = _zc_hidro_pronostico_para_mostrar(_zc_hidro_obtener_pronostico(config['pronostico']))
        emision = _ui_fecha_local(resultado.get('emision'))
        estado = ('No verificado' if resultado.get('error') else
                  'Corrida atrasada' if resultado.get('atrasado') else 'Horas futuras disponibles')
        filas.append({'Fuente':'INA · pronóstico '+ciudad, 'Estado':estado,
                      'Fecha publicada o de consulta':emision.strftime('%d/%m/%Y %H:%M ART') if emision is not None else 'Emisión sin confirmar',
                      'Interpretación':'Pronóstico experimental de escala. La altura observada actual debe comprobarse por separado.'})
    st.dataframe(pd.DataFrame(filas),hide_index=True,use_container_width=True)
    st.info('Esta página apoya la vigilancia y preparación. El semáforo meteorológico no determina la seguridad de una navegación o rescate. La altura actual del río, los accesos y el destino requieren verificación local vigente.')
    with st.expander('Datos operativos que faltan confirmar con el equipo',expanded=False):
        st.write('Sectores y puntos de embarque; accesos terrestres y fluviales; bases y centros habilitados, capacidad y contactos; disponibilidad real de personal y embarcaciones; umbrales de cada escala y evidencia de impactos locales. El mapa no contiene todavía un inventario operativo confirmado de estos recursos.')
        st.write('El equipo puede aportar recursos y accesos con responsable, fuente y fecha en la pestaña Territorio y accesos. Los archivos aportados conservan su procedencia y deben reconfirmarse antes de organizar un traslado.')


